INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(9789, 'koKR', 'Łowy na rozłupokopyty', 'Chcesz zasłużyć na miejsce na tym safari? Musisz się wykazać.$B$BNie obchodzi mnie, na co $gpolowałeś:polowałaś; wcześniej. Nie wiesz, czym są łowy, dopóki nie zapolujesz na to, na co my tu polujemy. Zacznij od rozłupokopytów, jeśli jesteś $gdość twardy:dość twarda;.$B$BWiem, że widziałem je w najbliższej okolicy safari, a także niedaleko na południu.', 'Upoluj 12 rozłupokopytów i wróć do Hemeta Nesingwary\'ego na Safari Nesingwary\'ego w Nagrandzie, aby się wykazać.', '', 'Wróć do Hemeta Nesingwary\'ego na Safari Nesingwary\'ego w Nagrandzie.', '', '', '', '', 0),
(9800, 'koKR', 'Rzadkie ziarno', 'Nie jesteś $gprzygotowany:przygotowana; na starcie z niespokojnymi żywiołami Nagrandu. Zanim zdołasz pomóc Kręgowi Ziemi, musisz pomóc sobie.$B$BNa zachodzie znajdziesz kupy łajna pozostawione przez zwierzęta Nagrandu. Przeszukaj łajno i wydobądź z niego strawione resztki nagrandzkiego caracoli. Z tego ziarna potrafię zrobić tabletkę, która pomoże ci w walce z niespokojnymi siłami natury.$B$BWróć do mnie, gdy zbierzesz co najmniej dwie garście caracoli... Ogrze garście.', 'Elementalista Lo\'ap przy Tronie Żywiołów w Nagrandzie chce, żebyś $gprzyniósł:przyniosła; mu 8 strawionych caracoli.', '', 'Wróć do elementalisty Lo\'apa przy Tronie Żywiołów w Nagrandzie.', '', '', '', '', 0),
(9804, 'koKR', 'Wzburzone duchy Niebiańskiej Pieśni', 'Zaburzenie przypływów i odpływów wód Nagrandu mocno wzburzyło duchy wody z Jeziora Niebiańskiej Pieśni. One z kolei zaczęły siać zniszczenie w całej okolicznej sieci wód.$B$BWatoosun, duch wody, ukazał się nam w wizji i pozwolił zaradzić temu problemowi – pod warunkiem, że zajmiemy się też źródłem zaburzenia...$B$BDo źródła jeszcze dotrzemy, ale najpierw musisz uporać się z kłopotami tuż przy Tronie. Zniszcz wzburzone duchy jeziora i wróć do mnie.', 'Elementalista Lo\'ap przy Tronie Żywiołów w Nagrandzie chce, żebyś $gzniszczył:zniszczyła; 8 duchów jeziora.', '', 'Wróć do elementalisty Lo\'apa przy Tronie Żywiołów w Nagrandzie.', '', '', '', '', 0),
(9805, 'koKR', 'Błogosławieństwo Incineratusa', 'Nikczemni Zagubieni, dotąd wygnani na bagna Moczarów Zangarskich, chcą rozprzestrzenić swój brud na inne części naszego świata.$B$BSzukałem mądrości furii i zyskałem ich błogosławieństwo. Aby odciąć źródło, musimy rozpętać przeciw nim żywioły!$B$BDaję ci żywy ogień, wyrwany z ognistej esencji samego Incineratusa. Udaj się do Wioski Wietrznej Trzciny na południowy wschód stąd i rozpętaj żywy ogień na ich chatach! Niech ujrzą furię żywiołów!', 'Elementalista Lo\'ap przy Tronie Żywiołów w Nagrandzie chce, żebyś $gzniszczył:zniszczyła; w Wiosce Wietrznej Trzciny dużą chatę, chatę zachodnią, chatę południową i chatę wschodnią.$B$BPo wykonaniu zadania zwróć żywy ogień elementaliście Lo\'apowi.', '', 'Wróć do elementalisty Lo\'apa przy Tronie Żywiołów w Nagrandzie.', 'Duża chata zniszczona', 'Zachodnia chata zniszczona', 'Południowa chata zniszczona', 'Wschodnia chata zniszczona', 0),
(9810, 'koKR', 'Skażony duch', 'Watoosunowi udało się zrzucić z siebie smród skażenia, lecz przy tym stworzył wypaczoną esencję ducha. Esencję złożoną z najpodlejszego plugastwa, jakie można znaleźć wśród żywiołów!$B$BTego skażonego ducha bagien znajdziesz na południowy zachód stąd, ukrytego w głębinach Jeziora Słonecznego Źródła.$B$BOdszukaj i zniszcz skażoną esencję Watoosuna oraz wszelkie spaczone potomstwo, które mogła zrodzić.', 'Elementalista Lo\'ap przy Tronie Żywiołów w Nagrandzie chce, żebyś $gzniszczył:zniszczyła; skażoną esencję Watoosuna i 8 jeziornych bryzgaczy.', '', 'Wróć do elementalisty Lo\'apa przy Tronie Żywiołów w Nagrandzie.', '', '', '', '', 0),
(9815, 'koKR', 'Nurkowanie w mule', 'Najbardziej dotknięte żywioły wody znajdziesz w Kotlinie Halaani, na południowy zachód stąd, pod opuszczonym miastem Halaa. Niektóre udręczone żywiołaki można zniszczyć bez szkody dla otoczenia, lecz błotne pomioty trzeba po zniszczeniu fizycznie usunąć ze świata.$B$BWidzisz, błotne pomioty zostawiają po sobie grudki skażonych szczątków, które, jeśli nikt ich nie usunie, rozprzestrzenią się i jeszcze bardziej skażą otoczenie.$B$BZniszcz te błotne pomioty i przynieś mi ich zabłocone rdzenie.', 'Elementalista Lo\'ap przy Tronie Żywiołów w Nagrandzie chce, żebyś $gzdobył:zdobyła; 5 zabłoconych rdzeni.', '', 'Wróć do elementalisty Lo\'apa przy Tronie Żywiołów w Nagrandzie.', '', '', '', '', 0),
(9818, 'koKR', 'Podziemie', 'Coś szaleje w podziemiu. Tłucze w ziemię, jakby chciało ją ukarać.$B$B*Łup*$B$B<Untrag uderza się pięścią w pierś.>$B$BWydaje ten dźwięk sto tysięcy razy. Tłucze bez końca. Ziemia się chwieje. Teraz nas wzywa.$B$BGordawg do mnie mówi. Gordawg wie, że coś wypycha żywioły. Coś z podziemia.$B$BIdź teraz i porozmawiaj z Gordawgiem. Nie, słuchaj Gordawga, nie mów. Usłysz Gordawga...', 'Porozum się z Gordawgiem.', '', '', '', '', '', '', 0),
(9819, 'koKR', 'Umęczona ziemia', 'Wydobądź uzurpatora. Znajdziesz go. Idź ziemną ścieżką. Najpierw ukój umęczone duchy ziemi. Muszą znów zasnąć.$B$B<Gordawg wbija pięść w ziemię i wydobywa z niej glebę o bardzo przykrym zapachu.>$B$BMuszą spać!$B$B<Gordawg wskazuje na południowy wschód.>$B$BZnajdź duchy blisko gór. Blisko wzgórz. Blisko skał. Blisko ziemi.$B$BUśpij je.$B$BKotlina Telaari... Południowy wschód.$B', 'Gordawg przy Tronie Żywiołów w Nagrandzie prosi, żebyś $gzniszczył:zniszczyła; 10 umęczonych duchów ziemi.', '', 'Wróć do Gordawga przy Tronie Żywiołów w Nagrandzie.', '', '', '', '', 0),
(9821, 'koKR', 'Pożeranie potępienia', '<Gordawg podnosi kamień i zaczyna go przeżuwać.>$B$BGordawg smakuje. Gordawg wie, gdzie była ta ziemia.$B$B<Gordawg unosi jedną ze swoich potężnych nóg i tupie w ziemię.>$B$BPatrz. Zobacz Nagrand.$B$B<Gordawg wskazuje ci odcisk swojej stopy. W odcisku widzisz coś, co wygląda na doskonałą mapę geologiczną Nagrandu z zaznaczonymi miejscami, w których znajdziesz żywiołaki, które Gordawg chce zniszczyć.>$B$BROZBIJ JE! Przynieś Gordawgowi kawałki do jedzenia.$B$BWeź mapę.', 'Gordawg przy Tronie Żywiołów w Nagrandzie prosi, żebyś $gprzyniósł:przyniosła; mu 10 rdzeni rozwścieczonych miażdżycieli.', '', 'Wróć do Gordawga przy Tronie Żywiołów w Nagrandzie.', '', '', '', '', 0),
(9849, 'koKR', 'Rozbicie zasłony', '<Gordawg odłamuje ze swojego grzbietu kawałek hebanowej skały.>$B$BDostajesz kawałek furii ziemi. Weź głaz Gordawga i rzuć nim w trujący kamień. Rozbij ich skorupy, poznaj prawdę. Zniszcz sługi uzurpatora i wróć do Gordawga z imieniem.$B$BRozbite żywiołaki znajdziesz na krańcu świata. Południowy zachód.', 'Gordawg przy Tronie Żywiołów w Nagrandzie prosi, żebyś $gzabił:zabiła; 30 sług Guroka.', '', 'Wróć do Gordawga przy Tronie Żywiołów w Nagrandzie.', '', '', '', '', 0),
(9850, 'koKR', 'Łowy na rozłupokopyty', '$GUdowodniłeś:Udowodniłaś; mi, że potrafisz wytropić i powalić zwykłego rozłupokopyta, ale znacznie groźniejsze są samce rozłupokopytów.$B$BUstrzel dwanaście takich. Wtedy możesz mi opowiadać o swoim myśliwskim kunszcie.$B$BSzukaj ich w całym środkowym Nagrandzie, na zachód i na południe stąd.', 'Zabij 12 samców rozłupokopytów, a następnie porozmawiaj z Hemetem Nesingwarym na Safari Nesingwary\'ego w Nagrandzie o swoim kunszcie.', '', 'Wróć do Hemeta Nesingwary\'ego na Safari Nesingwary\'ego w Nagrandzie.', '', '', '', '', 0),
(9851, 'koKR', 'Łowy na rozłupokopyty', 'Banthar to najdzikszy i najbardziej nieuchwytny ze wszystkich rozłupokopytów na Rubieży. I najbardziej włochaty.$B$BPodobno wędruje ze swoim stadem po Polach Duchów niedaleko Oshu\'gun.$B$BChcesz naprawdę udowodnić swoje mistrzostwo w łowach? Przynieś mi jej róg!', 'Zdobądź Róg Banthara i zanieś go Hemetowi Nesingwary\'emu na Safari Nesingwary\'ego w Nagrandzie.', '', 'Wróć do Hemeta Nesingwary\'ego na Safari Nesingwary\'ego w Nagrandzie.', '', '', '', '', 0),
(9852, 'koKR', 'Najkrwawszy ze sportów', 'Królową wszystkiego, co żyje w Nagrandzie, jest Ciosaczka. To olbrzymi elekk, jakiego nigdzie indziej nie zobaczysz!$B$BSłusznie drżysz na dźwięk tego imienia. Bach\'lor, Patroszyciel i Banthar to nic w porównaniu z nią. Podobno można ją znaleźć na wielkim urwisku daleko na południowym zachodzie, z którego widać Oshu\'gun. Przynieś mi jej ogromne serce, jeśli się odważysz.$B$BChcesz zostawić u mnie list, żebym mógł go przekazać twoim najbliższym, gdybyś – co całkiem prawdopodobne – nie $gwrócił:wróciła;?', 'Przynieś Serce Ciosaczki Hemetowi Nesingwary\'emu na Safari Nesingwary\'ego w Nagrandzie.', '', 'Wróć do Hemeta Nesingwary\'ego na Safari Nesingwary\'ego w Nagrandzie.', '', '', '', '', 0),
(9853, 'koKR', 'Gurok Uzurpator', 'Gurok trzeba przyzwać. Ty przyzywasz Guroka i ty niszczysz.$B$BMusisz iść na Wzgórze Wojennych Maczug na północnym zachodzie i znaleźć, gdzie ogry czczą Guroka. Połóż ogrzą czaszkę z ogrów Wojennych Maczug na ziemnym piętnie Guroka. Tylko wtedy Gurok przyjdzie. Siedem czaszek.$B$BJeśli przeżyjesz, przynieś Gordawgowi ziemną głowę Guroka. Gordawg zmiażdży głowę.$B$B<Gordawg mocno zaciska szczęki, aż ziemia drży ci pod stopami.>', 'Gordawg przy Tronie Żywiołów w Nagrandzie prosi, żebyś $gzniszczył:zniszczyła; Guroka Uzurpatora i $gprzyniósł:przyniosła; ziemną głowę Guroka.', '', 'Wróć do Gordawga przy Tronie Żywiołów w Nagrandzie.', '', '', '', '', 0),
(9854, 'koKR', 'Łowy na wichrowe roki', 'Czy żyjesz dla łowów tak jak ja, $N? Czy szukasz spokoju, który przychodzi, gdy podchodzisz ofiarę? Czy chcesz wiedzieć, co znaczy uczcić ostatnie uderzenia serca powalonej zwierzyny? Pomogę ci to osiągnąć.$B$BNagrand to bujna kraina, pełna życia pośród tego rozbitego świata. Upoluj kilka wichrowych roków, a potem porozmawiamy dalej.$B$BZnajdziesz je w wielu miejscach niedaleko naszego obozu, we wszystkich kierunkach.', 'Zabij 12 wichrowych roków, a następnie wróć do Fitza na Safari Nesingwary\'ego w Nagrandzie.', '', 'Wróć do Shado „Fitza” Obieżyświata na Safari Nesingwary\'ego w Nagrandzie.', '', '', '', '', 0),
(9855, 'koKR', 'Łowy na wichrowe roki', 'Musisz zawsze stawiać sobie wyżej poprzeczkę, jeśli pewnego dnia masz podchodzić najpotężniejszą zwierzynę! Choć nie jesteś jeszcze $ggotów:gotowa;, wskażę ci właściwy kierunek.$B$BIstnieje jeszcze groźniejsza odmiana wichrowego roka. Odszukaj wygłodniałe wichrowe roki i sprawdź się w walce z nimi. Znajdziesz je w sercu Nagrandu, na zachodzie i południowym zachodzie.', 'Upoluj 12 wygłodniałych wichrowych roków, a następnie wróć do Fitza na Safari Nesingwary\'ego w Nagrandzie.', '', 'Wróć do Shado „Fitza” Obieżyświata na Safari Nesingwary\'ego w Nagrandzie.', '', '', '', '', 0),
(9856, 'koKR', 'Łowy na wichrowe roki', 'Jesteś $ggotów:gotowa;, $N. $GGotów:Gotowa;, by stanąć przed matką wszystkich wichrowych roków, Patroszycielem! Honor wymaga, byś po upolowaniu tylu jej dzieci $gdał:dała; jej szansę, by cię pokonała! Szukaj jej wśród większych wichrowych roków daleko na zachodzie.$B$BJeśli przeżyjesz, przynieś mi jej oko.', 'Przynieś Oko Patroszyciela Fitzowi na Safari Nesingwary\'ego w Nagrandzie.', '', 'Wróć do Shado „Fitza” Obieżyświata na Safari Nesingwary\'ego w Nagrandzie.', '', '', '', '', 0),
(9857, 'koKR', 'Łowy na talbuki', 'Chyba nie dam dziś rady iść na polowanie. Może zajmiesz moje miejsce?$B$BPowiedziałem Hemetowi, że spróbuję ustrzelić dla nas kilka talbuków, których tu wszędzie pełno. Na rogacze poluje się szczególnie przyjemnie. Znajdziesz je zebrane pod okolicznymi drzewami.$B$BMyślisz, że $gmógłbyś:mogłabyś; się tym za mnie zająć?', 'Zabij 12 talbuków rogaczy, a następnie wróć do Harolda Lane\'a na Safari Nesingwary\'ego w Nagrandzie.', '', 'Wróć do Harolda Lane\'a na Safari Nesingwary\'ego w Nagrandzie.', '', '', '', '', 0),
(9858, 'koKR', 'Łowy na talbuki', 'To przeklęte zadrapanie chyba bierze nade mną górę. No więc, czy $gmógłbyś:mogłabyś;... <kaszel>... znowu mnie zastąpić?$B$BTym razem ustrzelisz kilka cierniojadów. Są twardsze i sprytniejsze niż rogacze, więc miej się na baczności. Szukaj ich... <kaszel>... w cieniu drzew w środkowym Nagrandzie, na zachodzie i na południu.$B$BNo idź, ruszaj i... <kaszel>... pokaż Hemetowi, na co cię stać. Nic mi nie będzie.', 'Upoluj 12 talbuków cierniojadów, a następnie wróć do Harolda Lane\'a na Safari Nesingwary\'ego w Nagrandzie.', '', 'Wróć do Harolda Lane\'a na Safari Nesingwary\'ego w Nagrandzie.', '', '', '', '', 0),
(9859, 'koKR', 'Łowy na talbuki', '<Rozdzierający kaszel.>$B$BNie martw się... <kaszel>... o mnie. Nic mi nie będzie. To tylko... <kaszel>... zadrapanie.$B$BMimo wszystko chyba będziesz... <kaszel>... $gmusiał:musiała; mnie zastąpić jeszcze... <kaszel>... raz.$B$BMusisz odnaleźć wielkiego Bach\'lora, króla... <kaszel>... rogaczy. Możesz... <kaszel>... zabrać ze sobą przyjaciół.$B$BPrzynieś mi jedno z jego kopyt... <kaszel>, <kaszel>... na dowód.$B$BSzukaj go... <kaszel>... na czele stada, daleko na zachodzie Nagrandu.', 'Zdobądź Kopyto Bach\'lora i zanieś je Haroldowi Lane\'owi na Safari Nesingwary\'ego w Nagrandzie.', '', 'Wróć do Harolda Lane\'a na Safari Nesingwary\'ego w Nagrandzie.', '', '', '', '', 0),
(9861, 'koKR', 'Wyjący wiatr', 'Ta bezkształtna masa żywiołowego powietrza przemawia do ciebie w języku, którego nie rozumiesz. Sądzisz, że to mowa żywiołów: Kalimag. Może ktoś przy Tronie Żywiołów rzuci nieco światła na to niezwykłe znalezisko.', 'Znajdź przy Tronie Żywiołów kogoś, kto mówi w języku Kalimag, i pokaż mu Wyjący wiatr.', '', '', '', '', '', '', 0),
(9862, 'koKR', 'Kaziciele Mętnej Krwi', 'Mętna Krew chwyta i torturuje duchy powietrza! Mętna Krew to moi pobratymcy: plemię Złamanych, którzy służą podłemu Musel\'ekowi, władcy bestii Żmijokolców.$B$BDuch powietrza twierdzi, że zgniliciele Mętnej Krwi chwytają inne duchy powietrza i używają ich, by siać chaos w szeregach żywiołów. Wygląda na to, że Mętna Krew niedawno złupiła orkową wioskę na południowym zachodzie, zwaną Słonecznym Źródłem, i używa potężnej magii żywiołów, by wzburzyć jezioro. Odszukaj zgnilicieli i zniszcz ich.', 'Elementalista Morgh przy Tronie Żywiołów w Nagrandzie chce, żebyś $gzabił:zabiła; 5 zgnilicieli Mętnej Krwi.', '', 'Wróć do elementalisty Morgha przy Tronie Żywiołów w Nagrandzie.', '', '', '', '', 0),
(9863, 'koKR', 'Podłe bałwochwalstwo', 'Nasi przywódcy są w rozsypce, więc jesteśmy narażeni na ataki ze wszystkich stron. Plugawe plemię Mętnej Krwi nie mogło wybrać lepszej chwili, by nas zaatakować!$B$BW ostatnich dniach Złamani napadli na nas co najmniej 5 razy. Zajęli nawet jedyną inną naszą placówkę w okolicy: Posterunek Słonecznego Źródła.$B$BMusimy uderzyć i pokazać im, że nie jesteśmy bezsilni! Pokonaj podłych bałwochwalców i przynieś mi ich wypaczone bożki, żeby dosiadły błyskawicy.', 'Wieszcz Kurkush w Garadarze w Nagrandzie chce, żebyś $gprzyniósł:przyniosła; mu 10 bożków Mętnej Krwi.', '', 'Wróć do wieszcza Kurkusha w Garadarze w Nagrandzie.', '', '', '', '', 0),
(9864, 'koKR', 'Zaginiony oddział wojenny', 'Po ostatnim najeździe Mętnej Krwi grupa młodzików postanowiła działać. Próbowaliśmy ich powstrzymać, ale ogarnął ich gniew. Minął już tydzień, odkąd ostatni raz widzieliśmy naszych ukochanych młodzików.$B$BProszę, musisz ich odnaleźć! Ledwie wkroczyli w wiek dojrzewania. Jak mogą liczyć na pokonanie takich dzikusów?$B$BPoszli drogą prowadzącą z miasta na zachód. Idź tą drogą i szukaj śladów naszych młodzików.$B$BI, $N, omijaj Halaa, jeśli życie ci miłe. Tam toczy się wojna.', 'Spróbuj odnaleźć zaginiony oddział wojenny z Garadaru.', '', '', '', '', '', '', 0),
(9865, 'koKR', 'Kiedyś byli wojownikami', 'Nie znam cię, $gnieznajomy:nieznajoma;, ale proszę cię o pomoc. Wstydzę się tego, ale jestem tylko jednym orkiem.$B$BWypłynęły we mnie uczucia, jakich nigdy nie znałem. Ja... pragnę zemsty. Krew za krew. Czy twój lud też to czuje? Chcę chwycić topór i rozrąbać wrogów na pół. Wymachiwać bronią, aż ręce opadną mi bezwładnie, wyczerpane.$B$BPosterunek Słonecznego Źródła leży dokładnie na południe od tej procesji. Tam znajdziesz naszych wrogów... Zabij ich... Zabij ich wszystkich...', 'Zabij 20 padlinożerców Mętnej Krwi i 10 łupieżców Mętnej Krwi.', '', 'Wróć do Zaurzykła Młodszego przy Procesji Mag\'harów w Nagrandzie.', '', '', '', '', 0),
(9866, 'koKR', 'Będzie wędrował po świecie...', 'Czy oddasz mi ostatnią przysługę, $N? Nie chcę wracać do Garadaru. Wierzę, że moje przeznaczenie leży gdzie indziej – że pewnego dnia będę służył wyższemu celowi.$B$BProszę, wróć do wieszcza Corhuka i powiedz mu, że nie wrócę. Że nie mogę wrócić. Muszę wędrować po świecie... On zrozumie.', 'Przekaż wieści wieszczowi Corhukowi w Garadarze.', '', '', '', '', '', '', 0),
(9867, 'koKR', 'Przywódcy Mętnej Krwi...', 'W ostatnich tygodniach straciliśmy wielu przyjaciół.$B$BOd dziesięcioleci radzimy sobie z ogrami Nagrandu, ale teraz pojawiło się nowe zagrożenie. Plemię Złamanych zwane Mętną Krwią zaatakowało naszą wioskę rybacką na południowym zachodzie, Posterunek Słonecznego Źródła, i zdołało zabić lub wygnać wszystkich orków, którzy ją zamieszkiwali.$B$BInni uważają, że najlepiej zabijać bez wyboru, ale ja wiem, że musimy zniszczyć ich przywództwo. Nie wiem, kto nimi dowodzi, ale sądzę, że poznasz go, gdy go znajdziesz.', 'Wieszcz Margadesh w Garadarze w Nagrandzie chce, żebyś $gprzyniósł:przyniosła; mu Głowę Ortora z Mętnej Krwi.', '', 'Wróć do wieszcza Margadesha w Garadarze w Nagrandzie.', '', '', '', '', 0),
(9868, 'koKR', 'Totem Kar\'dasha', 'Dziękuję ci, $gnieznajomy:nieznajoma;. Gdyby nie ty, na pewno by mnie zabili.$B$BTa Mętna Krew porwała mnie 3 noce temu podczas nocnego najazdu na Garadar. To, czego się od tamtej pory dowiedziałem, może wstrząsnąć samymi podstawami Rubieży: te dzikusy chcą odzyskać totem Kar\'dasha! Nie możemy dopuścić, by totem wpadł w ręce Mętnej Krwi!$B$BMusisz mi pomóc uciec. I, $gnieznajomy:nieznajoma;, jeśli nie dotrę z powrotem do Garadaru, musisz powiedzieć Garoszowi, co się tu stało...', 'Wyprowadź pojmanego Mag\'hara z Posterunku Słonecznego Źródła. Jeśli ci się uda, porozmawiaj z Garoszem w Garadarze.', 'Uwolnij pojmanego Mag\'hara', 'Wróć do Garosza w Garadarze w Nagrandzie.', '', '', '', '', 0),
(9869, 'koKR', 'Tron Żywiołów', 'Witaj, $N. Jestem Ioki, elementalista Kręgu Ziemi. Przybyłem do Telaar, by poinformować Kurenai o stanie żywiołów.$B$BCzy mogę cię prosić o przysługę? Czy $gudałbyś:udałabyś; się do Tronu Żywiołów na północnych wzgórzach Nagrandu, za Jeziorem Niebiańskiej Pieśni, i $gprzekazał:przekazała; elementalistce Sharvak, że bezpiecznie dotarłem do Telaar? Z pewnością wynagrodzi cię za tę drobną przysługę.', 'Elementalista Ioki chce, żebyś $gudał:udała; się do Tronu Żywiołów i $gporozmawiał:porozmawiała; z elementalistką Sharvak.', '', '', '', '', '', '', 0),
(9870, 'koKR', 'Tron Żywiołów', 'Witaj, $N. Jestem Yal\'hah, elementalista Kręgu Ziemi. Przybyłem do Garadaru, by poinformować Mag\'harów o stanie żywiołów.$B$BCzy mogę cię prosić o przysługę? Czy $gudałbyś:udałabyś; się do Tronu Żywiołów na północnych wzgórzach Nagrandu, za Jeziorem Niebiańskiej Pieśni, i $gprzekazał:przekazała; elementalistce Sharvak, że bezpiecznie dotarłem do Garadaru? Z pewnością wynagrodzi cię za tę drobną przysługę.', 'Elementalista Yal\'hah chce, żebyś $gudał:udała; się do Tronu Żywiołów i $gporozmawiał:porozmawiała; z elementalistką Sharvak.', '', '', '', '', '', '', 0),
(9871, 'koKR', 'Najeźdźcy Mętnej Krwi', 'Na pergaminie niezdarnie namalowano mapę Nagrandu. W miejscu, gdzie powinno leżeć Telaar, widnieje duży czerwony „X”. Wygląda na to, że te dzikusy planują atak na miasto. Zanieś plany inwazji Mętnej Krwi Arechronowi w Telaar.$B', 'Zanieś Plany inwazji Mętnej Krwi Arechronowi w Telaar w Nagrandzie.', '', '', '', '', '', '', 0),
(9872, 'koKR', 'Najeźdźcy Mętnej Krwi', 'Na pergaminie niezdarnie namalowano mapę Nagrandu. W miejscu, gdzie powinien leżeć Garadar, widnieje duży czerwony „X”. Wygląda na to, że te dzikusy planują atak na miasto. Zanieś plany inwazji Mętnej Krwi Garoszowi w Garadarze.', 'Zanieś Plany inwazji Mętnej Krwi Garoszowi.', '', '', '', '', '', '', 0),
(9873, 'koKR', 'Ortor, mój stary przyjaciel...', 'Te plany inwazji spisał ktoś, kogo kiedyś znałem. Ortor z Mętnej Krwi, niegdyś szlachetny Złamany, biegły w drodze żywiołów, a teraz ogłupiały od mułu potakiwacz Musel\'eka, władcy bagien.$B$BZ planów wynika, że zajęli orkową wioskę na północny zachód stąd, zwaną Słonecznym Źródłem.$B$BUdaj się do Posterunku Słonecznego Źródła i uwolnij świat od Ortora z Mętnej Krwi. To, co zrobisz, zrobisz dla dobra nas wszystkich...', 'Arechron w Telaar w Nagrandzie chce, żebyś $gzabił:zabiła; Ortora z Mętnej Krwi.', '', 'Wróć do Arechrona w Telaar w Nagrandzie.', '', '', '', '', 0),
(9874, 'koKR', 'Powstrzymać zarazę', 'Właśnie dotarły do mnie wieści o katastrofie epickich rozmiarów, $N. Plugawa Mętna Krew złupiła orkową wioskę, Posterunek Słonecznego Źródła, na północny zachód stąd, i wymordowała jej mieszkańców. Co gorsza, zaczęli wrzucać ciała do Jeziora Słonecznego Źródła. Jeśli te ciała zgniją, nasze główne źródło wody w okolicy zostanie skażone.$B$BNastępne zadanie, które ci daję, jest makabryczne, ale trzeba je wykonać. Weź tę zaklętą pochodnię i wróć do Słonecznego Źródła. Spal wszystkie gnijące zwłoki orków...', 'Otonbu Mędrzec w Telaar w Nagrandzie chce, żebyś $gużył:użyła; Pochodni płynnego ognia, by zniszczyć 10 zwłok mieszkańców Słonecznego Źródła. Po wykonaniu zadania zwróć Pochodnię płynnego ognia.$B', '', 'Wróć do Otonbu Mędrca w Telaar w Nagrandzie.', 'Spalone zwłoki mieszkańca Słonecznego Źródła', '', '', '', 0),
(9878, 'koKR', 'Rozwiązanie problemu', 'Pojawienie się Mętnej Krwi w Nagrandzie odbiło się bardzo źle na naszym otoczeniu. Wszystkie żywiołaki są wzburzone, co z kolei mocno zaniepokoiło dzikie zwierzęta. Co gorsza, zniszczenie Posterunku Słonecznego Źródła na nowo rozpaliło nienawiść orków do naszego ludu.$B$BChoć Kurenai to inne plemię niż Mętna Krew, ork widzi tylko Złamanych.$B$BMusimy spróbować rozwiązać ten problem. Udaj się do Posterunku Słonecznego Źródła, na północny zachód stąd, i rozwiąż problem Mętnej Krwi.', 'Poli\'lukluk Mędrszy w Telaar w Nagrandzie chce, żebyś $gzabił:zabiła; 10 padlinożerców Mętnej Krwi i 5 łupieżców Mętnej Krwi.', '', 'Wróć do Poli\'lukluka Mędrszego w Telaar w Nagrandzie.', '', '', '', '', 0),
(9879, 'koKR', 'Totem Kar\'dasha', 'Zabiliby mnie, gdyby nie ty, $gnieznajomy:nieznajoma;. W poszukiwaniu zaginionej relikwii wymordowali już tylu Kurenai.$B$BSzukają totemu Kar\'dasha. Nie rozumiem, czemu sądzą, że wiemy cokolwiek o tym totemie. Czyż totem nie jest z natury orkowym narzędziem?$B$BTę wiadomość trzeba zanieść Arechronowi. Może on wie, czemu Mętna Krew porywa Kurenai i torturuje ich, by wydobyć informacje o orkowym przedmiocie.$B$BChodźmy, zanim przyjdą następni.', 'Wyprowadź pojmanego Kurenai z Posterunku Słonecznego Źródła. Jeśli ci się uda, porozmawiaj z Arechronem w Telaar.', 'Uwolnij pojmanego Kurenai', 'Wróć do Arechrona w Telaar w Nagrandzie.', '', '', '', '', 0),
(9882, 'koKR', 'Okraść złodziei', 'Książę Nexusa Haramad zakazał nam rozpoczynania prac wewnątrz Oshu\'gun, bo mogłoby to rozgniewać pewnego potężnego naaru. Trochę to studzi zapał naszego przedsięwzięcia.$B$BChyba jednak znalazłem lukę w przepisach.$B$BWidzisz, nie jesteśmy jedynymi eterykami, których przyciąga ten kolosalny diament. Złodziej imieniem Gava\'xi przyprowadził do Oshu\'gun bandę eteryków-renegatów i zaczęli odłupywać z niego duże fragmenty.$B$BTwoim zadaniem, $N, jest udać się tam i odzyskać to, co słusznie należy do nas.', 'Zdobądź 10 odłamków kryształu z Oshu\'gun i zanieś je Gezhemu na Przystani Aeris w Nagrandzie.', '', 'Wróć do Gezhego na Przystani Aeris w Nagrandzie.', '', '', '', '', 0),
(9883, 'koKR', 'Więcej odłamków kryształu', '', '', '', 'Wróć do Gezhego w Nagrandzie.', '', '', '', '', 0),
(9884, 'koKR', 'Korzyści z członkostwa', '', '', '', '', '', '', '', '', 0),
(9885, 'koKR', 'Korzyści z członkostwa', '', '', '', '', '', '', '', '', 0),
(9886, 'koKR', 'Korzyści z członkostwa', '', '', '', '', '', '', '', '', 0),
(9887, 'koKR', 'Korzyści z członkostwa', '', '', '', '', '', '', '', '', 0),
(9892, 'koKR', 'Więcej obsydianowych paciorków wojennych', '', '', '', 'Wróć do Gezhego w Nagrandzie.', '', '', '', '', 0),
(9893, 'koKR', 'Obsydianowe paciorki wojenne', 'Całe to czekanie, aż Oshu\'gun będzie gotowe do kopania, zżera nasze zyski, $N.$B$BNa szczęście wymyśliłem inne źródło dochodu. Ogry z Nagrandu noszą paciorki wojenne z obsydianu, minerału, za który na wielu innych światach płaci się słono.$B$BZerid już musiał się rozprawić z kilkoma z tych osiłków dla bezpieczeństwa. Traktuj paciorki jako dodatkową premię. A jeszcze lepiej – nie zastanawiaj się nad tym za bardzo, tylko mi je przynieś.', 'Przynieś 10 obsydianowych paciorków wojennych Gezhemu na Przystani Aeris w Nagrandzie.', '', 'Wróć do Gezhego na Przystani Aeris w Nagrandzie.', '', '', '', '', 0),
(9897, 'koKR', 'Uratowana!', 'Chętnie się podzielę. Po prostu cieszę się, że ktoś mnie uratował przed tym gnojkiem Ganklym! A na Moczarach Zangarskich nazbierałam mnóstwo skór, więc to żaden problem!', 'Daj Pakunek skór Haroldowi Lane\'owi na Safari Nesingwary\'ego w Nagrandzie.', '', '', '', '', '', '', 0),
(9900, 'koKR', 'Gava\'xi', 'Obecność eteryków-renegatów w okolicy może bawić Gezhego, który wszędzie, dokąd się udamy, widzi wyłącznie okazje, ale dla bezpieczeństwa naszych przedsięwzięć to prawdziwe zagrożenie.$B$BIch przywódca, Gava\'xi, to niebezpieczny przestępca i jego unieszkodliwienie stało się moim najważniejszym celem.$B$BJeśli chcesz się na coś przydać, idź i zajmij się Gava\'xim. Dopilnuję, żebyś $gzostał:została; odpowiednio $gwynagrodzony:wynagrodzona;.', 'Zabij Gava\'xiego w pobliżu Oshu\'gun i wróć do Zerida na Przystani Aeris w Nagrandzie.', '', 'Wróć do Zerida na Przystani Aeris w Nagrandzie.', '', '', '', '', 0),
(9906, 'koKR', 'List w bitwie', 'Ogry rozumieją tylko jedno: siłę. Jeśli okażemy się przed nimi słabi, wykorzystają tę słabość i nas wybiją.$B$BGarosz może i jest gotów się położyć i pozwolić ogrzym psom zabrać nam ziemie, ale ja nie! Musisz przekazać wiadomość Głazopięściom, $N. Jedyną wiadomość, jaką są w stanie zrozumieć: brutalność.$B$BUdaj się do Ruin Płonącego Ostrza na południowy wschód stąd i pokaż im potęgę Mag\'harów.$B$BI, $N, zanim wyruszysz, zajrzyj do pozostałych.', 'Jorin Celnooki w Garadarze w Nagrandzie prosi, żebyś $gzabił:zabiła; 8 miażdżycieli Głazopięści i 8 mistyków Głazopięści.', '', 'Wróć do Jorina Celnookiego w Garadarze w Nagrandzie.', '', '', '', '', 0),
(9907, 'koKR', 'Zuchwały wypad', 'Dokładnie na zachód stąd znajdziesz Kotlinę Halaani. W kotlinie leżą bliźniacze szczeliny Nagrandu: Północnego i Południowego Wiatru. Oddziały szturmowe Głazopięści ukrywają w tych szczelinach swoje ogrze kopce.$B$BWytrop te oddziały i zabij wszystkich, których napotkasz, w imię Mag\'harów.', 'Jorin Celnooki w Garadarze w Nagrandzie prosi, żebyś $gzabił:zabiła; 10 wojowników Głazopięści i 10 magów Głazopięści.', '', 'Wróć do Jorina Celnookiego w Garadarze w Nagrandzie.', '', '', '', '', 0),
(9910, 'koKR', 'Sztandarowe praktyki', 'Jeśli wybierasz się do Ruin Płonącego Ostrza, mam dla ciebie zadanie. Weź te sztandary bojowe Mag\'harów i umieść je w trzech różnych miejscach ogrzego obozowiska. Najlepiej tam, gdzie dobrze je widać. Szukaj olbrzymich płonących stosów na wyższych poziomach. Postaw sztandar przy pierwszym, drugim i trzecim stosie Płonącego Ostrza.$B$BSztandar wywrze trwałe wrażenie na każdym ogrze, który mógł przegapić bitwę.', 'Elkay\'gan Mistyk w Garadarze w Nagrandzie chce, żebyś $gużył:użyła; Sztandaru bojowego Mag\'harów przy Pierwszym stosie Płonącego Ostrza, Drugim stosie Płonącego Ostrza i Trzecim stosie Płonącego Ostrza. Gdy skończysz, zwróć mu pozostałe Sztandary bojowe Mag\'harów.', '', 'Wróć do Elkay\'gana Mistyka w Garadarze w Nagrandzie.', 'Pierwszy sztandar bojowy postawiony', 'Drugi sztandar bojowy postawiony', 'Trzeci sztandar bojowy postawiony', '', 0),
(9913, 'koKR', 'Konsorcjum cię potrzebuje!', 'Moja organizacja, Konsorcjum, szuka kilku zaradnych osób, takich jak ty. Trudno ci będzie znaleźć eteryków uczciwszych, bardziej pracowitych czy przyjemniejszych w obyciu niż my.$B$BWymagamy tylko lojalności, oddania i rozsądnej dozy moralnej elastyczności. Jeśli jesteś $gzainteresowany:zainteresowana;, porozmawiaj z Gezhem, szefem naszych operacji w terenie. Znajdziesz go na Przystani Aeris, na północ od Oshu\'gun.', 'Zgłoś się do Gezhego na Przystani Aeris w Nagrandzie.', '', '', '', '', '', '', 0),
(9914, 'koKR', 'Głowa pełna kości słoniowej', 'Kość słoniowa to bardzo pożądany towar. Mam wielu klientów w dalekich krainach, którzy tylko czekają, żeby ją kupić.$B$BMożna by mnie przekonać, żebym dał ci działkę z zysków.$B$BDzikie elekki wędrujące po Nagrandzie mają kły tak wysokiej jakości, jakiej szukam. Omijaj elekki samce – ich kość słoniowa nie jest w takim stanie, jaki mnie interesuje.$B$BA, i nie martw się, to nie kłusownictwo – mam porozumienie zarówno z orkami, jak i z draenei.$B$BCzy my też się porozumiemy?', 'Zbierz 3 pary kłów z kości słoniowej i zanieś je Shadrekowi na Przystani Aeris w Nagrandzie.', '', 'Wróć do Shadreka na Przystani Aeris w Nagrandzie.', '', '', '', '', 0),
(9915, 'koKR', 'Więcej głów pełnych kości słoniowej', '', '', '', 'Wróć do Shadreka w Nagrandzie.', '', '', '', '', 0),
(9916, 'koKR', 'Skrzynie z zapasami Krwawiącego Oczodołu', 'Głazopięści przenieśli zapasy, które ukradli z naszej wioski, do bliźniaczych szczelin Nagrandu, na zachód stąd, w Kotlinie Halaani.$B$BKiedy będziesz w okolicy, wypatruj skrzyń z zapasami. Gdybyśmy zdołali je odzyskać, zdjęłoby to wiele ciężaru z barków matron Garadaru.', 'Elkay\'gan Mistyk w Garadarze w Nagrandzie chce, żebyś $godzyskał:odzyskała; 10 skrzyń z zapasami Krwawiącego Oczodołu.', '', 'Wróć do Elkay\'gana Mistyka w Garadarze w Nagrandzie.', '', '', '', '', 0),
(9917, 'koKR', 'Czy wzrok mnie nie myli', 'Czy wzrok mnie myli, czy tam dalej jest ogrzy oddział łowiecki? Co ogry mogą robić tak daleko od swojego kopca? Wcale mi się to nie podoba, $gnieznajomy:nieznajoma;. Najpierw Mętna Krew, a teraz ogry. Po prostu nie mamy dość ludzi, by poradzić sobie ze wszystkimi zagrożeniami dla naszej ziemi.$B$BCzy $gmógłbyś:mogłabyś; zbadać dla nas, co ogry robią na wschodzie? Ich wysunięty obóz jest jakieś 200 kroków na wschód stąd. Poznasz, że $gdotarłeś:dotarłaś; na miejsce, gdy zobaczysz łowców Głazopięści. Zabij ich, a znajdziesz plany!', 'Łowczyni Bintook w Telaar w Nagrandzie chce, żebyś $godzyskał:odzyskała; Plany Głazopięści.', '', 'Wróć do łowczyni Bintook w Telaar w Nagrandzie.', '', '', '', '', 0),
(9918, 'koKR', 'Nie na mojej warcie!', 'Te plany bitewne spisał ogrzy porucznik. Nazywa się albo Brudas, albo Bryła.$B$B<Bintook obraca pergamin bokiem i przekrzywia głowę.>$B$BRównie dobrze może to być Bolek.$B$BTak czy inaczej, uważam, że $gpowinieneś:powinnaś; tam wrócić i zamienić słowo z Bolkiem, Bryłą, Brudaskiem czy jak mu tam! Spróbuj podejść do niego dyplomatycznie. Jeśli to nie zadziała, spróbuj użyć mięśni.', 'Łowczyni Bintook w Telaar w Nagrandzie chce, żebyś $gporozmawiał:porozmawiała; z Bryłą. Gdy zdobędziesz informacje, o które prosiła, wróć do łowczyni Bintook.', '', 'Wróć do łowczyni Bintook w Telaar w Nagrandzie.', 'Bryła przesłuchany', '', '', '', 0),
(9920, 'koKR', 'Mo\'mor Łamacz', 'Musisz natychmiast odszukać Mo\'mora! Znajdziesz go w centrum Telaar, przy fontannie. Powtórz mu dokładnie, co powiedział ci ogr.', 'Łowczyni Bintook w Telaar w Nagrandzie chce, żebyś $gporozmawiał:porozmawiała; z Mo\'morem Łamaczem.', '', '', '', '', '', '', 0),
(9921, 'koKR', 'Ruiny Płonącego Ostrza', 'Te ogrze oddziały łowieckie to zapowiedź inwazji. Musimy w nie uderzyć, zanim zdążą zebrać armię dość dużą, by zająć nasze miasto.$B$BBędziesz $gmusiał:musiała; ubrudzić sobie ręce, $N.$B$BNajwięcej Głazopięściów w tej okolicy znajdziesz w Ruinach Płonącego Ostrza, niemal dokładnie na wschód od Telaar, przy granicy z Puszczą Terokkar. Udaj się tam i pokaż Głazopięściom, że Telaar nie ugnie się przed ich wolą!', 'Mo\'mor Łamacz w Telaar w Nagrandzie chce, żebyś $gzabił:zabiła; 8 miażdżycieli Głazopięści i 8 mistyków Głazopięści.', '', 'Wróć do Mo\'mora Łamacza w Telaar w Nagrandzie.', '', '', '', '', 0),
(9922, 'koKR', 'Bliźniacze szczeliny Nagrandu', '$GSpisałeś:Spisałaś; się świetnie, $N. Jesteś $ggotów:gotowa; na więcej?$B$BDoniesiono mi o dużym oddziale ogrów Głazopięści ukrytym w bliźniaczych szczelinach Nagrandu, na północny zachód stąd, w Kotlinie Halaani.$B$BWyrusz do szczelin i rozpraw się z resztą ogrów Głazopięści.', 'Mo\'mor Łamacz w Telaar w Nagrandzie prosi, żebyś $gzabił:zabiła; 10 wojowników Głazopięści i 10 magów Głazopięści.', '', 'Wróć do Mo\'mora Łamacza w Telaar w Nagrandzie.', '', '', '', '', 0),
(9923, 'koKR', 'RATUNKU!', 'RATUNKU! Oni mnie zjedzą! Ja to wiem!$B$BZnajdź klucz, na pewno ma go któryś z tych ogrów.$B$BJeśli mnie stąd wyciągniesz, mój ojciec sowicie cię wynagrodzi! To przywódca Telaar, Arechron.$B', 'Znajdź Klucz Głazopięści i uwolnij Corkiego. Jeśli ci się uda, porozmawiaj z Arechronem w Telaar.$B', '', 'Odszukaj Arechrona w Telaar w Nagrandzie.', 'Corki uwolniony', '', '', '', 0),
(9924, 'koKR', 'Corki znowu zaginął!', '<Arechron wzdycha.>$B$BTo takie krępujące. Pamiętasz mojego chłopca, Corkiego? Niedawno $guratowałeś:uratowałaś; go z Ruin Płonącego Ostrza. Cóż, ciekawość znów wzięła nad nim górę. Powiedział mi, że idzie zbadać zagrożenie ze strony Głazopięściów dla „wujka” Mo\'mora, i pobiegł do ogrzych kopców w Kotlinie Halaani, na północ stąd.$B$BCzy $gmógłbyś:mogłabyś; go wytropić? Byłbym ci dozgonnie wdzięczny.$B', 'Arechron w Telaar prosi, żebyś $godnalazł:odnalazła; i $guwolnił:uwolniła; Corkiego.', '', 'Wróć do Arechrona w Telaar w Nagrandzie.', 'Corki znowu uwolniony', '', '', '', 0),
(9925, 'koKR', 'Kwestie bezpieczeństwa', 'Gezhe postanowił umieścić naszą bazę jak najbliżej Oshu\'gun, bez względu na bezpieczeństwo załogi. Dlaczego? Bo wyliczył, że założenie interesu tutaj, a nie w górach na południu, zwiększy wydajność o dziesięć procent.$B$BMniejsza o oszalałe pomioty Pustki, które kręcą się raptem trzy metry od nas. To problem oficera bezpieczeństwa, nie Gezhego.$B$BZabij dla mnie trochę pomiotów Pustki, a zapłacę ci jedną dziesiątą naszego budżetu na bezpieczeństwo. Nie ciesz się za bardzo, to niewielki budżet.', 'Zerid na Przystani Aeris w Nagrandzie chce, żebyś $gzabił:zabiła; 8 pomiotów Pustki w pobliżu Oshu\'gun.', '', 'Wróć do Zerida na Przystani Aeris w Nagrandzie.', '', '', '', '', 0),
(9927, 'koKR', 'Bezwzględny podstęp', '<Lantresor podaje ci torbę pełną sztandarów.>$B$BTo sztandary ogrów z Wojennych Maczug, które niedawno zdobyłem.$B$BChcę, żebyś $gudał:udała; się do Fortecy Kil\'sorrow, dokładnie na południe stąd, i $gzabił:zabiła; tylu tych plugawców z Kil\'sorrow, ilu zdołasz znaleźć. Wbij sztandar ogrów z Wojennych Maczug w serce każdego poległego żołnierza Kil\'sorrow. Wróć do mnie, gdy wykonasz to zadanie i drugie, którego wymaga ten plan.', 'Lantresor z Ostrza w Ruinach Płonącego Ostrza w Nagrandzie chce, żebyś $gwbił:wbiła; 10 sztandarów ogrów z Wojennych Maczug w ciała członków Kil\'sorrow w Fortecy Kil\'sorrow.$B$BZwróć niewykorzystane sztandary ogrów z Wojennych Maczug.', '', 'Wróć do Lantresora z Ostrza w Ruinach Płonącego Ostrza w Nagrandzie.', 'Sztandar ogrów z Wojennych Maczug wbity', '', '', '', 0),
(9928, 'koKR', 'Uzbrojenie do podstępu', 'Aby mój plan się powiódł, musisz ukraść uzbrojenie Kil\'sorrow z Fortecy Kil\'sorrow.$B$BPrzeszukaj fortecę i znajdź skrzynie z uzbrojeniem Kil\'sorrow. Przynieś mi wszystko, co znajdziesz.$B$BForteca Kil\'sorrow leży dokładnie na południe od Ruin Płonącego Ostrza, nieco na zachód.', 'Lantresor z Ostrza w Ruinach Płonącego Ostrza w Nagrandzie chce, żebyś $gzebrał:zebrała; 10 sztuk uzbrojenia Kil\'sorrow.', '', 'Wróć do Lantresora z Ostrza w Ruinach Płonącego Ostrza w Nagrandzie.', '', '', '', '', 0),
(9931, 'koKR', 'Odwzajemniona przysługa', 'Teraz musisz zasiać ziarno wojny w tłustych, bezużytecznych łbach Wojennych Maczug. Na północnym zachodzie, przy górach, znajdziesz Ruiny Śmiejącej się Czaszki.$B$B<Lantresor wskazuje skrzynię z uzbrojeniem, którą mu $gprzyniosłeś:przyniosłaś;.>$B$BPoznajesz te sztandary? To sztandary Kil\'sorrow. Weź plik sztandarów Kil\'sorrow i wbij je w trupy ogrów z Wojennych Maczug. Pamiętaj, ogry znajdziesz na północnym zachodzie.', 'Lantresor z Ostrza w Ruinach Płonącego Ostrza w Nagrandzie chce, żebyś $gwbił:wbiła; 10 sztandarów Kil\'sorrow w ciała ogrów z Wojennych Maczug w Ruinach Śmiejącej się Czaszki.$B$BZwróć niewykorzystane sztandary Kil\'sorrow.', '', 'Wróć do Lantresora z Ostrza w Ruinach Płonącego Ostrza w Nagrandzie.', 'Sztandar Kil\'sorrow wbity', '', '', '', 0),
(9932, 'koKR', 'Ciała dowodem', 'Twoja rzeź w Fortecy Kil\'sorrow dała nam wyjątkową okazję. Mamy dość ciał, by wyglądało na to, że stoczono wielką bitwę.$B$BUdaj się do Ruin Śmiejącej się Czaszki i znajdź Dziedziniec Śmiejącej się Czaszki. Na dziedzińcu powinien płonąć stos. Upewnij się, że teren jest bezpieczny, a potem użyj tego koca, by nadać sygnały dymne. Gdy moje ogry zobaczą dym, zakradną się tam i podrzucą ciała zabitych żołnierzy Kil\'sorrow.$B$BTo powinna być ostatnia kropla!', 'Lantresor z Ostrza w Ruinach Płonącego Ostrza w Nagrandzie chce, żebyś $gużył:użyła; Wilgotnego wełnianego koca przy Płonącym stosie Wojennych Maczug na Dziedzińcu Śmiejącej się Czaszki, by dać znak jego ogrom.', '', 'Wróć do Lantresora z Ostrza w Ruinach Płonącego Ostrza w Nagrandzie.', 'Ciała Kil\'sorrow podrzucone', '', '', '', 0),
(9933, 'koKR', 'Wiadomość dla Telaar', '<Lantresor wskazuje nieoznakowaną skrzynię.>$B$BWeź ją. To mój dar dla twojego ludu. W pojedynkę $gocaliłeś:ocaliłaś; mój klan przed zagładą.$B$BMożesz powiedzieć swojemu przywódcy, że Lantresor z Płonącego Ostrza i jego ogry Głazopięści przyjmują propozycję pokoju.$B$B<Lantresor się kłania.>$B', 'Zanieś Dar pokoju Płonącego Ostrza Arechronowi w Telaar w Nagrandzie.', '', '', '', '', '', '', 0),
(9934, 'koKR', 'Wiadomość dla Garadaru', '<Lantresor wskazuje nieoznakowaną skrzynię.>$B$BWeź ją. To mój dar dla twojego ludu. W pojedynkę $gocaliłeś:ocaliłaś; mój klan przed zagładą.$B$BMożesz powiedzieć swojemu przywódcy, że Lantresor z Płonącego Ostrza i jego ogry Głazopięści przyjmują propozycję pokoju.$B$B<Lantresor się kłania.>', 'Zanieś Dar pokoju Płonącego Ostrza Garoszowi w Garadarze.', '', '', '', '', '', '', 0),
(9935, 'koKR', 'Poszukiwana: Giselda Wiedźma', 'Poszukiwani żywi lub martwi$B$BGiselda Wiedźma z Kil\'sorrow i jej poplecznicy, za morderstwa, rytualne ofiary, konszachty z Legionem, porwania i włamania.$B$BZwykle przebywają w Fortecy Kil\'sorrow w południowo-wschodnim Nagrandzie, przy granicy z Puszczą Terokkar.$B$BKażdy, kto zdoła postawić Giseldę przed sądem, otrzyma od strażnika Bullroka w Garadarze wysoką nagrodę w złocie.', 'Zabij Giseldę Wiedźmę i w dowolnym składzie 10 agentów Kil\'sorrow. Po wykonaniu zadania wróć do strażnika Bullroka w Garadarze.', '', 'Wróć do strażnika Bullroka w Garadarze w Nagrandzie.', '', '', '', '', 0),
(9936, 'koKR', 'Poszukiwana: Giselda Wiedźma', 'Poszukiwani żywi lub martwi$B$BGiselda Wiedźma z Kil\'sorrow i jej poplecznicy, za morderstwa, rytualne ofiary, konszachty z Legionem, porwania i włamania.$B$BZwykle przebywają w Fortecy Kil\'sorrow w południowo-wschodnim Nagrandzie, przy granicy z Puszczą Terokkar.$B$BKażdy, kto zdoła postawić Giseldę przed sądem, otrzyma od strażnika Moi\'bff Jilla w Telaar wysoką nagrodę w złocie.', 'Zabij Giseldę Wiedźmę i w dowolnym składzie 10 agentów Kil\'sorrow. Po wykonaniu zadania wróć do strażnika Moi\'bff Jilla w Telaar.', '', 'Wróć do strażnika Moi\'bff Jilla w Telaar w Nagrandzie.', '', '', '', '', 0),
(9937, 'koKR', 'Poszukiwany: Durn Łaknący', '$GZniszczyłeś:Zniszczyłaś; dwa największe zagrożenia w Nagrandzie, $N. Jesteś $ggotów:gotowa; zmierzyć się z plagą Pól Duchów?$B$BDurn Łaknący panuje nad okolicami Oshu\'gun i niszczy wszystko na swojej drodze. Jak dotąd nikomu nie udało się uwolnić Nagrandu od tego dzikiego gronna. Zbierz sojuszników, wyrusz na Pola Duchów, daleko na południowy zachód stąd, w pobliże Oshu\'gun, i wytrop Durna. Zabij go, a zapewniam cię, że nagroda będzie współmierna do trudności zadania.$B', 'Zabij Durna Łaknącego. Jeśli ci się uda, wróć do strażnika Bullroka.', '', 'Wróć do strażnika Bullroka w Garadarze w Nagrandzie.', '', '', '', '', 0),
(9938, 'koKR', 'Poszukiwany: Durn Łaknący', '$GZniszczyłeś:Zniszczyłaś; dwa największe zagrożenia w Nagrandzie, $N. Jesteś $ggotów:gotowa; zmierzyć się z plagą Pól Duchów?$B$BDurn Łaknący panuje nad okolicami Oshu\'gun i niszczy wszystko na swojej drodze. Jak dotąd nikomu nie udało się uwolnić Nagrandu od tego dzikiego gronna. Zbierz sojuszników, wyrusz na Pola Duchów, na zachód stąd, i wytrop Durna. Zabij go, a zapewniam cię, że nagroda będzie współmierna do trudności zadania.', 'Zabij Durna Łaknącego. Jeśli ci się uda, wróć do strażnika Moi\'bff Jilla.', '', 'Wróć do strażnika Moi\'bff Jilla w Telaar w Nagrandzie.', '', '', '', '', 0),
(9939, 'koKR', 'Poszukiwany: Zorbo Doradca', 'Poszukiwany żywy lub martwy$B$BZorbo Doradca, poszukiwany za liczne zaplanowane ataki na Garadar. Wraz ze swoimi grabieżcami i szamanami Zorbo zabił niezliczonych orków. Zorbo jest uzbrojony, niebezpieczny i bezlitosny.$B$BZorbo mieszka w Ruinach Śmiejącej się Czaszki w północnych górach Nagrandu.$B$BNagrodę za zabicie lub schwytanie Zorbo Doradcy wypłaci strażnik Bullrok w Garadarze.', 'Zabij Zorbo Doradcę, 5 szamanów Wojennych Maczug i 5 grabieżców Wojennych Maczug. Jeśli ci się uda, wróć do strażnika Bullroka.', '', 'Wróć do strażnika Bullroka w Garadarze w Nagrandzie.', '', '', '', '', 0),
(9940, 'koKR', 'Poszukiwany: Zorbo Doradca', 'Poszukiwany żywy lub martwy$B$BZorbo Doradca, poszukiwany za liczne zaplanowane ataki na Telaar. Wraz ze swoimi grabieżcami i szamanami Zorbo zabił niezliczonych Złamanych. Zorbo jest uzbrojony, niebezpieczny i bezlitosny.$B$BZorbo mieszka w Ruinach Śmiejącej się Czaszki w północnych górach Nagrandu.$B$BNagrodę za zabicie lub schwytanie Zorbo Doradcy wypłaci strażnik Moi\'bff Jill w Telaar.', 'Zabij Zorbo Doradcę, 5 szamanów Wojennych Maczug i 5 grabieżców Wojennych Maczug. Jeśli ci się uda, wróć do strażnika Moi\'bff Jilla.', '', 'Wróć do strażnika Moi\'bff Jilla w Telaar w Nagrandzie.', '', '', '', '', 0),
(9944, 'koKR', 'Zaginiona procesja Mag\'harów', 'Wszechmatka mówi, że musimy trwać i służyć naszemu ludowi. Mówi, że mamy być przykładem dla Garosza – pokazać, że życie toczy się dalej.$B$BMam tu tyle spraw na głowie, zwłaszcza odkąd Wszechmatka zachorowała. Czy uczcisz Mag\'harów, pomagając jednej z ich matron?$B$BKilka dni temu wysłaliśmy procesję pogrzebową na Ziemie Przodków i do tej pory nie wróciła. Pójdziesz jej poszukać? Wyruszyli z Garadaru zachodnią drogą. Idź nią i omijaj Halaa.', 'Odszukaj zaginioną procesję Mag\'harów.', '', '', '', '', '', '', 0),
(9945, 'koKR', 'Wojna z Wojennymi Maczugami', 'Byliśmy w drodze na Ziemie Przodków, gdy wpadliśmy w zasadzkę Wojennych Maczug. Nadeszli ze wszystkich stron, zabijając kilku strażników procesji i wielu innych. Zbezcześcili nawet szczątki starszego na wozie.$B$BI po co? Żeby nas upokorzyć i pokazać swoją siłę. Nawet Głazopięści nie upadliby tak nisko.$B$BJestem orkiem uduchowionym, $N, ale nawet moja cierpliwość ma granice. Znajdź napastników na Wzgórzu Wojennych Maczug na północnym zachodzie i zniszcz ich!', 'Starszy Yorley przy Procesji Mag\'harów w Nagrandzie prosi, żebyś $gzabił:zabiła; 8 osiłków Wojennych Maczug i 8 czarnoksiężników Wojennych Maczug.', '', 'Wróć do starszego Yorleya przy Procesji Mag\'harów w Nagrandzie.', '', '', '', '', 0),
(9946, 'koKR', 'Cho\'war Łupieżca', '$GWidziałeś:Widziałaś; kiedyś ogrzego króla, $N? Niewielu go widziało i przeżyło, by o tym opowiedzieć. Niestety, właśnie z czymś takim mamy tu do czynienia.$B$BPrzywódcą tych barbarzyńców jest ogr imieniem Cho\'war. Podobno to on wygnał gronna z jaskini. Potem Cho\'war ogłosił się królem i rozwiązał klany ogrów, które służyły gronnowi. Tak narodziły się Wojenne Maczugi.$B$BZnajdź Cho\'wara w głębi jaskiń Wzgórza Wojennych Maczug. Zabij go i przynieś mi jego głowę.', 'Starszy Yorley przy Procesji Mag\'harów w Nagrandzie prosi, żebyś $gzabił:zabiła; Cho\'wara Łupieżcę i $gzdobył:zdobyła; Głowę Cho\'wara.', '', 'Wróć do starszego Yorleya przy Procesji Mag\'harów w Nagrandzie.', '', '', '', '', 0),
(9948, 'koKR', 'Odnaleźć ocalałych', 'Jeśli coś wiem o ograch, to to, że lubią świeże jedzenie. To znaczy, że Mag\'harowie, których pojmali, najpewniej są trzymani przy życiu, dopóki nie trafią na stół. Wiem, że to obrzydliwa myśl, ale musimy ją wykorzystać na naszą korzyść.$B$BUdaj się na Wzgórze Wojennych Maczug i szukaj więźniów Mag\'harów. Jeśli znajdziesz więźniów, klucze do ich klatek znajdziesz przy okolicznych ograch z Wojennych Maczug.$B$BZabijaj ogry, zdobądź klucze i uwolnij więźniów.', 'Starszy Ungriz przy Procesji Mag\'harów w Nagrandzie prosi, żebyś $guwolnił:uwolniła; 5 więźniów Mag\'harów.', '', 'Wróć do starszego Ungriza przy Procesji Mag\'harów w Nagrandzie.', 'Więzień Mag\'harów uwolniony', '', '', '', 0),
(9954, 'koKR', 'Okup za Corkiego', '<Arechron pokazuje ci umorusany list.>$B$BWłaśnie dostałem ten list. Jest od klanu ogrów zwanego Wojennymi Maczugami, który rządzi północno-zachodnimi ziemiami Nagrandu. Piszą, że mają Corkiego i jeśli nie będziemy współpracować, zjedzą go. Trzeba przyznać, że Corki to głupek, ale wciąż to moja krew. Uratujesz go, $N?$B$BPrzypuszczam, że siedzi zamknięty w klatce gdzieś na Wzgórzu Wojennych Maczug. Tam $gpowinieneś:powinnaś; zacząć.', 'Arechron chce, żebyś $godnalazł:odnalazła; Corkiego na Wzgórzu Wojennych Maczug.', '', '', '', '', '', '', 0),
(9955, 'koKR', 'Cho\'war Łupieżca', 'Nazywają go Cho\'war Łupieżca, $N. To ogr, który wygnał gronna rządzącego kiedyś tymi ogrami. Możesz mi wierzyć, że jest potężny!$B$BKucharz mówił, że Cho\'war mieszka w wielkiej jaskini – gdziekolwiek ona jest... Zdobądź ten klucz i wyciągnij mnie stąd! Jeśli przeżyjemy, mój ojciec na pewno da ci wielką nagrodę! Gdy tylko będę wolny, odszukaj go.', 'Corki chce, żebyś $gzdobył:zdobyła; Klucz Cho\'wara i $guwolnił:uwolniła; go z klatki. Jeśli ci się uda, wróć do Arechrona w Telaar.', '', 'Wróć do Arechrona w Telaar w Nagrandzie.', 'Corki uwolniony', '', '', '', 0),
(9956, 'koKR', '', 'Byłam w karawanie wiozącej zapasy do Przystani Orebor na Moczarach Zangarskich. Gdy zbliżaliśmy się do granicy moczarów, napadł na nas okrutny oddział ogrów z Wojennych Maczug. Zabili pozostałych, a mnie wzięli do niewoli razem ze wszystkimi naszymi zapasami.$B$BNa szczęście zapomnieli założyć tylną ściankę w mojej klatce. Gdy zasnęli, uciekłam.$B$BDla moich towarzyszy jest już za późno, ale bardzo przydałyby nam się zapasy, które ukradli. Wzgórze Wojennych Maczug leży w północno-zachodnich górach Nagrandu.', 'Łowczyni Kima w Telaar w Nagrandzie chce, żebyś $godzyskał:odzyskała; 10 skrzyń z zapasami z Telaar.', '', 'Wróć do łowczyni Kimy w Telaar w Nagrandzie.', '', '', '', '', 0),
(9962, 'koKR', 'Krąg Krwi: Złamany Palec', 'No to jak, $ggotów:gotowa; na pierwszą walkę? Jeśli tak, daj znać, a wszystko rozkręcę. Musisz tylko stanąć w Kręgu Krwi i poczekać, aż pojawi się przeciwnik.$B$BTa walka jest ze Złamanym Palcem, dzikim rozłupokopytem.$B$BPowodzenia! Mam nadzieję, że $gprzyprowadziłeś:przyprowadziłaś; przyjaciół.$B$BI pamiętaj, walka kończy się, gdy ty albo twój przeciwnik leżycie twarzą w piasku areny.$B', 'Pokonaj Złamanego Palca. Jeśli wygrasz, porozmawiaj z Wodinem Trollowym Sługą, by odebrać nagrodę.', 'Złamany Palec pokonany', 'Wróć do Wodina Trollowego Sługi w Ruinach Śmiejącej się Czaszki w Nagrandzie.', '', '', '', '', 0),
(9967, 'koKR', 'Krąg Krwi: Niebiescy Bracia', 'Następna walka to starcie z duetem – a dokładnie z braćmi bliźniakami. Nazywają siebie „Niebieskimi Braćmi”.$B$BJeszcze nie jest za późno, żeby stchórzyć, $N. Na pewno bym zrozumiał.$B$BAle jeśli masz ochotę na trochę akcji, wejdź do Kręgu Krwi i poczekaj, aż zjawią się bliźniacy z Mętnej Krwi.$B$BWygrywa ten, kto ostatni zostanie na nogach!', 'Pokonaj bliźniaków z Mętnej Krwi, którzy nazywają siebie Niebieskimi Braćmi. Jeśli wygrasz, porozmawiaj z Wodinem Trollowym Sługą, by odebrać nagrodę.', 'Niebiescy Bracia pokonani', 'Wróć do Wodina Trollowego Sługi w Ruinach Śmiejącej się Czaszki w Nagrandzie.', '', '', '', '', 0),
(9970, 'koKR', 'Krąg Krwi: Rokdar Rozdarty Władca', 'Ta walka będzie bolesna, $N. Masz przyjaciół, którzy są dość odważni, by ci pomóc? Ogrom udało się sprowadzić z Gór Klingi olbrzyma imieniem Rokdar! Uwierz mi, będziesz potrzebować przyjaciół, wydaje się nie do pokonania! Twardy jak skała – dosłownie!$B$BJeśli nadal chcesz z nim walczyć, wejdź do Kręgu Krwi, a on przyjdzie.', 'Pokonaj Rokdara Rozdartego Władcę. Jeśli wygrasz, porozmawiaj z Wodinem Trollowym Sługą, by odebrać nagrodę.', 'Rokdar Rozdarty Władca pokonany', 'Wróć do Wodina Trollowego Sługi w Ruinach Śmiejącej się Czaszki w Nagrandzie.', '', '', '', '', 0),
(9972, 'koKR', 'Krąg Krwi: Skra\'gath', 'Rozwalasz ich tam, $gmały:mała;! Na następną walkę sprowadzili podstawionego zawodnika. Mówią, że to jakiś władca pustki czy coś... Za nic nie chcą cię wystawić przeciw swojemu czempionowi. $GSłyszałeś:Słyszałaś;, jak ten osiłek Mogor na ciebie ujadał? Zakłady idą pod sufit!$B$BWłaź na ring i załatw go szybko!', 'Pokonaj Skra\'gatha. Jeśli wygrasz, porozmawiaj z Wodinem Trollowym Sługą, by odebrać nagrodę.', 'Skra\'gath pokonany', 'Wróć do Wodina Trollowego Sługi w Ruinach Śmiejącej się Czaszki w Nagrandzie.', '', '', '', '', 0),
(9973, 'koKR', 'Krąg Krwi: Czempion Wojennych Maczug', 'Musieli sprowadzić czempiona aż z gladiatorskich aren Gór Klingi. Trenował na górskich olbrzymach – po trzech naraz.$B$BJeśli wygrasz tę walkę, zostaniesz nowym czempionem. Jak myślisz, jakie masz szanse, $gmały:mała;? Dasz radę? Daj tylko słowo, a postawię na ciebie wszystko, co mam.$B$BA teraz właź tam i wygraj!', 'Pokonaj Czempiona Wojennych Maczug. Jeśli wygrasz, porozmawiaj z Wodinem Trollowym Sługą, by odebrać nagrodę.', 'Czempion Wojennych Maczug pokonany', 'Wróć do Wodina Trollowego Sługi w Ruinach Śmiejącej się Czaszki w Nagrandzie.', '', '', '', '', 0),
(9977, 'koKR', 'Krąg Krwi: Ostatnie wyzwanie', '<Gurgthock przelicza swoją ogromną stertę złota.>$B$BZarobiłem na tobie kupę forsy, $gmały:mała;. Jeśli pokonasz Mogora, obiecuję, że ci się to opłaci. Cały ból, który $gwycierpiałeś:wycierpiałaś; w Kręgu Krwi, w końcu się zwróci.$B$BA teraz właź tam i pokaż tym ogrom, z czego jesteś $gzrobiony:zrobiona;!', 'Pokonaj Mogora, Bohatera Wojennych Maczug. Jeśli wygrasz, porozmawiaj z Wodinem Trollowym Sługą, by odebrać nagrodę.', 'Mogor, Bohater Wojennych Maczug, pokonany', 'Wróć do Wodina Trollowego Sługi w Ruinach Śmiejącej się Czaszki w Nagrandzie.', '', '', '', '', 0),
(9982, 'koKR', 'Mówił, że nazywa się Altruis...', 'Pod koniec zeszłego tygodnia przybyła do miasta istota dosiadająca smokowca Otchłani. Przedstawił się jako Altruis, a potem zadał nam kilka pytań o Nagrand.$B$BTwierdził, że poluje na Legion. Że to szaleństwo to właściwie jego praca. Wyobrażasz sobie? Ktoś, kto z własnej woli poluje na demony?$B$BZanim odjechał, poprosił, byśmy przekazali kandydatom na bohaterów w mieście, że przez jakiś czas zostanie w zachodnim Nagrandzie, a jeśli szukają celu, niech go odnajdą.', 'Jeśli chcesz walczyć z Płonącym Legionem, odszukaj Altruisa Cierpiącego w zachodnim Nagrandzie.', '', '', '', '', '', '', 0),
(9983, 'koKR', 'Mówił, że nazywa się Altruis...', 'Pod koniec zeszłego tygodnia przybyła do miasta istota dosiadająca smokowca Otchłani. Przedstawił się jako Altruis, a potem zadał nam kilka pytań o Nagrand.$B$BTwierdził, że poluje na Legion. Że to szaleństwo to właściwie jego praca. Wyobrażasz sobie? Ktoś, kto z własnej woli poluje na demony?$B$BZanim odjechał, poprosił, byśmy przekazali kandydatom na bohaterów w mieście, że przez jakiś czas zostanie w zachodnim Nagrandzie, a jeśli szukają celu, niech go odnajdą.', 'Jeśli chcesz walczyć z Płonącym Legionem, odszukaj Altruisa Cierpiącego w zachodnim Nagrandzie.', '', '', '', '', '', '', 0),
(9991, 'koKR', 'Zbadaj teren', 'Bycie moimi oczami wymaga od ciebie sumienności. Nethrandamus przeniesie cię nad obozami Legionu, ale musisz zapamiętać wszystko, co zobaczysz. Nawet najdrobniejszy szczegół, który wyda ci się nieistotny, może nam się przydać.$B$BPrzede wszystkim chcę, żebyś $gzwrócił:zwróciła; uwagę na to, jakie budowle stoją w obozach i z czego składa się ich obrona.$B$BNethrandamus jest gotów, kiedy tylko zechcesz, $N. Nie bój się, uchroni cię przed wszelką krzywdą.$B', 'Rozsiądź się wygodnie i ciesz się lotem. Gdy zakończysz zwiad, porozmawiaj z Altruisem.', 'Obozy kuźnicze zbadane', 'Porozmawiaj z Altruisem Cierpiącym w Nagrandzie.', '', '', '', '', 0),
(9999, 'koKR', 'Na czas', 'Dopóki stoją transportery, nic, co zrobimy obozom kuźniczym, nie będzie trwałe. Musimy znaleźć sposób na zniszczenie budowli Legionu.$B$BPotrzebuję czasu, by opracować plan ataku. Jeśli zdołasz zająć czymś ich inżynierów i majsterkowiczów, mocno spowolni to ich postępy i da mi potrzebny czas.$B$BTrzymaj się jak najdalej od nadzorców, $N. To niezwykle niebezpieczne istoty.', 'Altruis Cierpiący w zachodnim Nagrandzie prosi, żebyś $gzabił:zabiła; 2 strażników Spaczenia-legionistów, 3 mo\'argów inżynierów i 8 gan\'argów majsterkowiczów.', '', 'Wróć do Altruisa Cierpiącego w Nagrandzie.', '', '', '', '', 0),
(10001, 'koKR', 'Główny planista', 'Każdy obóz kuźniczy ma głównego planistę. Główny planista ustala, jakie budowle powstaną w obozie kuźniczym i jak każda z nich zostanie rozmieszczona. Co więcej, informacje te zapisane są na zestawie projektów, które planista nosi przy sobie.$B$BPotrzebujemy projektów głównego planisty. Mając tak dokładne informacje, moglibyśmy przekonać pewnego mojego znajomego, by udzielił nam pomocy.$B$BZnajdź mo\'arga głównego planistę i zabierz mu projekty. Będzie stacjonował za kuźniami.', 'Altruis Cierpiący w zachodnim Nagrandzie prosi, żebyś $godzyskał:odzyskała; Projekty głównego planisty.', '', 'Wróć do Altruisa Cierpiącego w Nagrandzie.', '', '', '', '', 0),
(10011, 'koKR', 'Obóz kuźniczy: unicestwiony', 'Zbierz sojuszników, $N. Będą ci potrzebni, jeśli masz się zmierzyć z nadzorcą.$B$BGdy zbierzesz odpowiednią drużynę, znajdź i zabij nadzorców w każdym obozie. Zabierz im klucze i użyj ich, by obrócić spaczone działa i ostrzelać z nich obozy. Wróć do mnie, gdy obozy zostaną zniszczone.', 'Altruis Cierpiący w zachodnim Nagrandzie prosi, żebyś $gzniszczył:zniszczyła; Obóz Kuźniczy: Nienawiść i Obóz Kuźniczy: Strach.', '', 'Wróć do Altruisa Cierpiącego w Nagrandzie.', 'Obóz Kuźniczy: Nienawiść zniszczony', 'Obóz Kuźniczy: Strach zniszczony', '', '', 0),
(10044, 'koKR', 'Wizyta u Wszechmatki', 'Wszechmatka poprosiła, bym cię odszukał i przekazał wiadomość. Chce natychmiast z tobą porozmawiać.$B$BOpuściła mnie wola walki, ale nie łudź się, $N – jeśli rozgniewasz Wszechmatkę, spadnę na ciebie z całą siłą, jaką zdołam z siebie wykrzesać. Jest w głównej sali.$B$B<Garosz wskazuje duży budynek na północy.>$B$BWysłuchaj, co ma do powiedzenia, i zrób, co ci każe.', 'Porozmawiaj z Wszechmatką Geyah i wysłuchaj, co ma ci do powiedzenia.$B', 'Wysłuchaj Wszechmatki Geyah', 'Wróć do Wszechmatki Geyah w Garadarze w Nagrandzie.', '', '', '', '', 0),
(10045, 'koKR', 'Składniki', 'Matka Kashur chce z tobą porozmawiać, $N. Zanim będzie to możliwe, musisz zebrać zioła potrzebne do sporządzenia mikstury, która poszerzy twój umysł i pozwoli ci obcować z duchami.$B$BMusisz zebrać korzeń olemby w Puszczy Terokkar, borówki bagienne na Moczarach Zangarskich, liście z Telaar w Nagrandzie i smoczy kolec w Górach Klingi. Na tym pergaminie spisałam wskazówki, jak zdobyć te zioła. Wróć do mnie, gdy zbierzesz składniki.', 'Wszechmatka Geyah w Garadarze w Nagrandzie prosi, żebyś $gzebrał:zebrała; 1 korzeń olemby, 1 borówkę bagienną, 1 liść z Telaar i 1 smoczy kolec.$B', '', 'Wróć do Wszechmatki Geyah w Garadarze w Nagrandzie.', '', '', '', '', 0),
(10074, 'koKR', 'Proszek kryształowy z Oshu\'gun', 'Ta baza była głównym ośrodkiem badawczym draenei, w którym badano kryształy naaru.$B$BTo, co odkryliśmy, to prawdziwa kopalnia złota: notatki badawcze o kryształach z „diamentowej” góry, Oshu\'gun. Wygląda na to, że wszystko w tej okolicy nosi w sobie resztki proszku z kryształów Oshu\'gun. Jeśli podczas przygód w tej okolicy znajdziesz trochę proszku, przynieś mi go, a nagrodzę cię żetonem wdzięczności, za który zrobisz zakupy u kwatermistrza.', 'Główna badaczka Amereldine w Halaa chce 10 próbek proszku kryształowego z Oshu\'gun.', '', 'Wróć do głównej badaczki Amereldine w Halaa w Nagrandzie.', '', '', '', '', 0),
(10075, 'koKR', 'Proszek kryształowy z Oshu\'gun', '', '', '', 'Wróć do głównej badaczki Amereldine w Halaa w Nagrandzie.', '', '', '', '', 0),
(10076, 'koKR', 'Proszek kryształowy z Oshu\'gun', 'Ta baza była głównym ośrodkiem badawczym draenei, w którym badano kryształy naaru.$B$BTo, co odkryliśmy, to prawdziwa kopalnia złota: notatki badawcze o kryształach z „diamentowej” góry, Oshu\'gun. Wygląda na to, że wszystko w tej okolicy nosi w sobie resztki proszku z kryształów Oshu\'gun. Jeśli podczas przygód w tej okolicy znajdziesz trochę proszku, przynieś mi go, a nagrodzę cię żetonem wdzięczności, za który zrobisz zakupy u kwatermistrza.', 'Główny badacz Kartos w Halaa chce 10 próbek proszku kryształowego z Oshu\'gun.', '', 'Wróć do głównego badacza Kartosa w Halaa w Nagrandzie.', '', '', '', '', 0),
(10077, 'koKR', 'Proszek kryształowy z Oshu\'gun', '', '', '', 'Wróć do głównego badacza Kartosa w Halaa w Nagrandzie.', '', '', '', '', 0),
(10081, 'koKR', 'Spotkanie z Matką Kashur', 'Nie przerażaj się tym, co możesz zobaczyć, gdy mikstura zacznie działać! Te duchy są wszędzie wokół nas – zawsze. Mikstura pozwala twojemu umysłowi je zrozumieć, a w końcu także zobaczyć. Musisz być pod jej wpływem, jeśli chcesz porozmawiać z Matką Kashur.$B$BZnajdziesz ją daleko na południowym zachodzie, na Ziemiach Przodków.$B', 'Wszechmatka Geyah chce, żebyś $gporozmawiał:porozmawiała; z Matką Kashur.', '', '', '', '', '', '', 0),
(10082, 'koKR', 'Wzburzeni przodkowie', 'Widzisz, jak chodzą wokół nas? Ziemie Przodków są zwykle ciche i spokojne.$B$BOstatnio duchy przodków powstały i są niezwykle wzburzone. Coś wywołuje wśród duchów wielki niepokój. Musimy odkryć, co to może być, ale najpierw trzeba zażegnać bezpośrednie zagrożenie.$B$BTe zjawy, które widzisz, to nie prawdziwi przodkowie, lecz odbicie ich stanu. Musisz zniszczyć niespokojne duchy orków. Zrób to i wróć do mnie.', 'Matka Kashur prosi, żebyś $gukoił:ukoiła; 8 niespokojnych duchów orków.$B', '', 'Wróć do Matki Kashur na Ziemiach Przodków w Nagrandzie.', '', '', '', '', 0),
(10085, 'koKR', 'Wizyta u przodków', 'Musisz udać się do wiosek przodków, $N. Odwiedź każdą z nich i sprawdź, czy przodkowie wciąż tam przebywają.$B$BOdwiedź Posterunek Słonecznego Źródła na północy, Ruiny Śmiejącej się Czaszki daleko na północy, pod górami, Garadar na północnym wschodzie, a na koniec Ruiny Krwawiącego Oczodołu na granicy Nagrandu i Puszczy Terokkar, na wschodzie.$B$BWróć do mnie, gdy zobaczysz przodków w ich domach.', 'Matka Kashur na Ziemiach Przodków w Nagrandzie prosi, żebyś $godwiedził:odwiedziła; Posterunek Słonecznego Źródła, Ruiny Śmiejącej się Czaszki, Garadar i Ruiny Krwawiącego Oczodołu.', '', 'Wróć do Matki Kashur na Ziemiach Przodków w Nagrandzie.', 'Odwiedź Posterunek Słonecznego Źródła', 'Odwiedź ruiny klanu Śmiejącej się Czaszki', 'Odwiedź Garadar', 'Odwiedź ruiny klanu Krwawiącego Oczodołu', 0),
(10101, 'koKR', 'Gdy duchy przemawiają', 'Oshu\'gun – diamentowa góra – była niegdyś święta dla mojego ludu. To tam co roku zbierały się klany, by świętować wiosenny festyn. To tam nasi szamani obcowali z czcigodnymi przodkami. Była sercem naszej kultury – dopóki nie ogarnął nas cień. Gdy klany stały się hordą, duchy Oshu\'gun umilkły. Przodkowie odwrócili się od nas.$B$BA jednak coś wyrywa ich teraz ze spoczynku. Wyrusz do Oshu\'gun i odkryj, co tak niepokoi duchy.', 'Matka Kashur na Ziemiach Przodków w Nagrandzie prosi, żebyś $godszukał:odszukała; to, co $gujrzałeś:ujrzałaś; w wizji. Znajdź K\'ure w Oshu\'gun.', '', '', '', '', '', '', 0),
(10107, 'koKR', 'Środki dyplomatyczne', 'Kilrath przysyła wieści o przywódcy Głazopięściów: to ork! Wiekowy ork, który przeszedł przez Mroczny Portal za czasów naszych ojców i od tamtej pory wrócił do ojczyzny. Chcę, żebyś $godnalazł:odnalazła; tego orka i $gspróbował:spróbowała; przekonać go, by wycofał ogry Głazopięści. Przebywa na górnym tarasie w Ruinach Płonącego Ostrza, na południowy wschód stąd, przy granicy z Puszczą Terokkar. Powodzenia, $N!$B$BOstrzegam, to mistrz ostrza...', 'Jorin Celnooki w Garadarze w Nagrandzie prosi, żebyś $godnalazł:odnalazła; Lantresora z Ostrza w Ruinach Płonącego Ostrza i z nim $gporozmawiał:porozmawiała;.', 'Wysłuchaj opowieści mistrza ostrza', 'Wróć do Lantresora z Ostrza w Ruinach Płonącego Ostrza w Nagrandzie.', '', '', '', '', 0),
(10108, 'koKR', 'Środki dyplomatyczne', 'Agenci łowczyni przysyłają wieści o przywódcy Głazopięściów: to ork! Wiekowy ork, który przeszedł przez Mroczny Portal za czasów naszych ojców i od tamtej pory wrócił do ojczyzny. Chcę, żebyś $godnalazł:odnalazła; tego orka i $gspróbował:spróbowała; przekonać go, by wycofał ogry Głazopięści. Przebywa na górnym tarasie w Ruinach Płonącego Ostrza, na wschodzie. Powodzenia, $N!$B$BOstrzegam, to mistrz ostrza...', 'Mo\'mor Łamacz w Telaar w Nagrandzie prosi, żebyś $godnalazł:odnalazła; Lantresora z Ostrza w Ruinach Płonącego Ostrza i z nim $gporozmawiał:porozmawiała;.', 'Wysłuchaj opowieści mistrza ostrza', 'Wróć do Lantresora z Ostrza w Ruinach Płonącego Ostrza w Nagrandzie.', '', '', '', '', 0),
(10109, 'koKR', 'Muszę je mieć!', 'Widzisz je?! Na straszliwy nieświeży oddech Gazola, zdobędę te jaja! Ej, wyglądasz na kogoś, kto może się przydać.$B$BWiesz co? Jeśli zbierzesz dla mnie kilka rzeczy, żebym mógł uruchomić mój Skakotron 4000, dam ci klucz, dzięki któremu też będziesz $gmógł:mogła; korzystać z maszyny! Co można zrobić ze Skakotronem 4000, pytasz? Raczej: czego nie można...$B$BBędę potrzebował gazu żywiołaków powietrza od żywiołaków powietrza z Nagrandu. Są wszędzie, więc nie pytaj mnie, gdzie ich szukać!', 'Wazat naprzeciwko Klanowej Strażnicy w południowym Nagrandzie chce, żebyś $gprzyniósł:przyniosła; mu 3 porcje gazu żywiołaka powietrza.', '', 'Wróć do Wazata w Nagrandzie.', '', '', '', '', 0),
(10111, 'koKR', 'Przynieś mi jajo!', 'Teraz, gdy już $gprzeszedłeś:przeszłaś; wtajemniczenie, chcę, żebyś $gzdobył:zdobyła; dla mnie to jajo! Użyj Skakotronu i spróbuj trafić w sam środek gniazda. Ale uważaj! Nieudany skok może skończyć się obrażeniami ciała lub poważnym trwałym uszczerbkiem na zdrowiu.', 'Wazat w Nagrandzie chce, żebyś $gużył:użyła; Skakotronu 4000, by dostać się do gniazda na pobliskim drzewie i ukraść Tajemnicze jajo.', '', 'Wróć do Wazata w Nagrandzie.', 'Spróbuj ukraść jajo', '', '', '', 0),
(10113, 'koKR', 'Safari Nesingwary\'ego', '„Idź i znajdź nam trochę zapasów” – powiedział. Zanim trafiłem tutaj, o mało nie zginąłem jakieś 15 razy! Ci Złamani może nie są najgościnniejsi, ale przynajmniej nie próbują zedrzeć mi skóry z kości.$B$BTak czy inaczej, nie wracam. Moje dni polowania na grubego zwierza się skończyły. Jeśli skierujesz się na północny wschód, w stronę Moczarów Zangarskich, i natrafisz na Safari Nesingwary\'ego, powiedz im, że „Śrutówka” rezygnuje.$B$BHej, może zajmiesz moje miejsce! Powodzenia, $gnieznajomy:nieznajoma;.$B', '„Śrutówka” Jones chce, żebyś $gporozmawiał:porozmawiała; z Hemetem Nesingwarym na Safari Nesingwary\'ego na obrzeżach północno-wschodniego Nagrandu.$B', '', '', '', '', '', '', 0),
(10114, 'koKR', 'Safari Nesingwary\'ego', 'Ci orkowie nigdy wcześniej nie widzieli taurena – wyobrażasz sobie? Gdyby nie kapitan Kroghan, pewnie właśnie podawaliby mnie sobie na następny posiłek.$B$BAle gdzie moje maniery? Jestem Ohlorn Obieżyświat, łowca nad łowcami! Należę do wyprawy Nesingwary\'ego, która przybyła tu z Azeroth w poszukiwaniu grubego zwierza. Jeśli interesują cię łowy, odwiedź moich towarzyszy na Safari Nesingwary\'ego, dokładnie na wschód stąd, przy granicy z Moczarami Zangarskimi.$B', 'Ohlorn Obieżyświat chce, żebyś $gporozmawiał:porozmawiała; z Shado „Fitzem” Obieżyświatem na Safari Nesingwary\'ego w Nagrandzie.', '', '', '', '', '', '', 0),
(10168, 'koKR', 'Co widzi dusza', 'Przez wiele stuleci duchy Auchindoun zlewały się w moją mroczną esencję. Wiele katastrof, które spadły na tę kryptę, było bezpośrednim skutkiem mojego osłabienia.$B$BNiestety, nic nie przerwie tego cyklu. Taka jest natura naaru – bez pustki Światłość nie może istnieć.$B$BJedyne, co możesz zrobić, to zniszczyć pradawne duchy Nagrandu, zanim przemienią się w istoty pustki. Użyj luster duszy rozsianych po tej krypcie, by je uwolnić...', 'Odszukaj Lustro duszy gdzieś w Kryptach Auchenai i użyj go, by przywołać mroczne duchy z pradawnych przodków orków w Nagrandzie. Zniszcz 15 mrocznych duchów, by przodkowie mogli spoczywać w pokoju.$B$BPo wykonaniu zadania wróć do Matki Kashur na Ziemiach Przodków.', '', 'Wróć do Matki Kashur na Ziemiach Przodków w Nagrandzie.', '', '', '', '', 0),
(10170, 'koKR', 'Powrót do Wszechmatki', 'Wróć do Wszechmatki Geyah w Garadarze z wieścią o swoim zwycięstwie, $N. To z pewnością podniesie Mag\'harów na duchu. Może nawet młody Piekłorycz otrząśnie się z przygnębienia.', 'Wróć do Garadaru i porozmawiaj z Wszechmatką Geyah.', '', '', '', '', '', '', 0),
(10171, 'koKR', 'Niepocieszony wódz', 'Tak wiele $gzrobiłeś:zrobiłaś; dla Mag\'harów, $N. Twoje dokonania są znane wszystkim, także Garoszowi. Idź teraz do niego i opowiedz mu o swoim ostatnim zwycięstwie. Powiedz mu, że robisz to, co robisz, dla niego i jego ludu. Twoje słowa z pewnością dodadzą mu otuchy.', 'Wszechmatka Geyah w Garadarze prosi, żebyś $gporozmawiał:porozmawiała; z Garoszem.', '', '', '', '', '', '', 0),
(10172, 'koKR', 'Nie ma nadziei', 'Masz honor, $N. Wiele $gzrobiłeś:zrobiłaś; dla Mag\'harów. Nikt nigdy nie zaprzeczy twoim zasługom dla mojego ludu. Niestety, czas Mag\'harów dobiega końca. Bardziej niż cokolwiek innego $gpokazałeś:pokazałaś; mi, że nie nadaję się, by przewodzić temu ludowi. Moja przeklęta krew sięga zbyt głęboko. Nie... nie mogę zostać drugim Piekłoryczem, który skaże orków na potępienie.$B$BProszę, $N, wróć do Wszechmatki i powiedz jej, co ci powiedziałem. Zbyt się wstydzę, by się z nią zobaczyć... by spojrzeć jej w oczy.', 'Porozmawiaj z Wszechmatką Geyah i powtórz jej, co powiedział ci Garosz.', 'Porozmawiaj z Wszechmatką Geyah', 'Wróć do Wszechmatki Geyah w Garadarze w Nagrandzie.', '', '', '', '', 0),
(10252, 'koKR', 'Wizja umarłych', 'To już się zaczęło. Levixus stoi na ruinach Auchindoun i czyta z księgi umarłych. Wzywa zmarłych po imieniu i za pomocą demonicznego rytuału podporządkowuje sobie udręczone dusze. Jeśli mu się pozwoli, wskrzesi całe Auchindoun!$B$BAle... najpierw musisz się przygotować. Nie możesz walczyć z tym, czego nie widzisz.$B$B<Nitrin podaje ci pergamin.>$B$BPrzynieś mi to, czego potrzebuję do uwarzenia nalewki. Otworzy twój umysł i pozwoli ci zajrzeć do świata duchów.', 'Nitrin w Porzuconej Zbrojowni w Nagrandzie chce, żebyś $gprzyniósł:przyniosła; mu 1 gałkę oczną górskiego gronna, 1 nieskazitelny dziób większego wichrowego roka i 1 tłuszcz wiekowego rozłupokopyta.', '', 'Wróć do Nitrina Uczonego w Nagrandzie.', '', '', '', '', 0),
(10375, 'koKR', 'Obsydianowe paciorki wojenne', '$GUdowodniłeś:Udowodniłaś; swoją wartość naszemu ludowi, $N. Teraz czas, byś nam $gpokazał:pokazała;, że chcesz stać u naszego boku, nawet w obliczu najsilniejszego wroga.$B$BOgry z Rubieży są', '', '', '', '', '', '', '', 0),
(10476, 'koKR', 'Zażarci wrogowie', 'Jeśli chcesz udowodnić nam swoją lojalność, nie ma lepszego sposobu niż walka z naszymi wrogami.$B$BA spośród nich nikt nie dorównuje ogrom siłą i zaciekłością. Przynieś mi paciorki wojenne, które noszą na szyjach, jako dowód ich śmierci, a powiem innym o twoim kunszcie.', 'Strażnik Moi\'bff Jill w Telaar chce, żebyś $gzdobył:zdobyła; 10 obsydianowych paciorków wojennych od różnych ogrów zamieszkujących Nagrand.', '', 'Wróć do strażnika Moi\'bff Jilla w Telaar w Nagrandzie.', '', '', '', '', 0),
(10477, 'koKR', 'Więcej paciorków wojennych', '', '', '', 'Wróć do strażnika Moi\'bff Jilla w Telaar w Nagrandzie.', '', '', '', '', 0),
(10478, 'koKR', 'Więcej paciorków wojennych!', '', '', '', 'Wróć do strażnika Bullroka na Moczarach Zangarskich.', '', '', '', '', 0),
(10479, 'koKR', 'Dowód siły', 'Choć pragniemy spokojnego życia, mamy wielu wrogów. A spośród nich nikt nie dorównuje ogrom czystą, brutalną siłą.$B$BJeśli chcesz dowieść nam swojego kunsztu, przynieś mi paciorki wojenne, które noszą na szyjach. Opowiem innym o twoich dokonaniach.', 'Strażnik Bullrok w Garadarze chce, żebyś $gzdobył:zdobyła; 10 obsydianowych paciorków wojennych od różnych ogrów zamieszkujących Nagrand.', '', 'Wróć do strażnika Bullroka w Garadarze w Nagrandzie.', '', '', '', '', 0),
(10640, 'koKR', 'Altruis', 'W dzisiejszych czasach rzadko słyszy się o tych, którzy kroczą ścieżką łowcy demonów. Jeszcze rzadziej spotyka się kogoś, kto nią kroczy i nie jest wierny Illidanowi.$B$BKrążą pogłoski o jednej takiej osobie tu, na Rubieży. Podobno na opanowanych przez Legion polach Nagrandu pewnego imienia boją się bardziej niż jakiejkolwiek armii obrońców Aldorów. To imię to Altruis.$B$BUdaj się do zachodniego Nagrandu i odszukaj go. Może zechce rzucić nieco światła na te nowe tereny szkoleniowe łowców demonów.', 'Udaj się do zachodniego Nagrandu i odszukaj Altruisa Cierpiącego.$B$BWykonywanie zadań dla Aldorów obniży twoją reputację u Widzących.', '', '', '', '', '', '', 0),
(10641, 'koKR', 'Przeciw Legionowi', 'Płonący Legion wielokrotnie udowodnił, że potrafi deprawować śmiertelne dusze. Jeśli mam ci powierzyć wiedzę, której szukasz, muszę mieć dowód twojej wierności.$B$BDemonica zwana Sathal od dawna mi się wymyka, bo została obdarzona bezcielesną postacią.$B$BCzuwa nad kapłankami gniewu, które wykonują jej rozkazy w Bazie Kuźniczej Gehenna. Zabij jedną z jej sług i przelej jej krew na ziemię. Ta zniewaga powinna sprawić, że Sathal na chwilę się zmaterializuje. Zabij ją, póki możesz.', 'Altruis Cierpiący chce, żebyś $gzdobył:zdobyła; świeżo utoczoną krew od kapłanki gniewu w Bazie Kuźniczej Gehenna w Burzy Otchłani. Przelej ją na ziemię i zabij Awatara Sathal. Po wykonaniu zadania wróć do Altruisa.', '', 'Wróć do Altruisa Cierpiącego w Nagrandzie.', '', '', '', '', 0),
(10646, 'koKR', 'Uczeń Illidana', '$GDowiodłeś:Dowiodłaś; swojej wierności, $N. Wybacz mi ostrożność, ale na tym świecie nic nie jest takie, jakim się wydaje.$B$BOpowiem ci o Varedisie, gdy będziesz $ggotów:gotowa;.', 'Wysłuchaj opowieści Altruisa.', 'Uczeń Illidana', '', '', '', '', '', 0),
(10650, 'koKR', 'Powrót do Aldorów', 'Ta księga... Mógłbym jej użyć, by dziesięciokrotnie zwiększyć swoją moc... Nie! W końcu zepsułaby mi duszę, tego jestem pewien. Wróć do tych, którzy cię tu przysłali, $N.$B$BMasz teraz sposób, by powstrzymać Varedisa. Zaczekaj, aż przez metamorfozę przybierze demoniczną postać – wtedy musisz spalić księgę w jego obecności. Tylko w ten sposób pozbawisz go mocy.', 'Porozmawiaj z Egzarchą Onaalą przy Ołtarzu Sha\'tar w Dolinie Cienistego Księżyca.$B$BWykonywanie zadań dla Aldorów obniży twoją reputację u Widzących.', '', '', '', '', '', '', 0),
(10668, 'koKR', 'Przeciw Illidari', 'Wciąż szanuję Illidana. Bez niego nie odnalazłbym swojej ścieżki.$B$BNie jest już jednak tym, kim był. Jego duszę zepsuła władza, a umysł wypaczyła klęska. Stał się tym, co przysiągłem niszczyć, a jego pupile, Illidari, są taką samą ohydą jak każdy demon Płonącego Legionu.$B$BJego uścisk na Rubieży słabnie, lecz jego zasięg wciąż jest ogromny. Udowodnij, że nie jesteś po jego stronie – zabij jego porucznika Lothrosa w Punkcie Illidari w Dolinie Cienistego Księżyca.', 'Altruis Cierpiący chce, żebyś $gzabił:zabiła; Lothrosa w Punkcie Illidari w Dolinie Cienistego Księżyca.', '', 'Wróć do Altruisa Cierpiącego w Nagrandzie.', '', '', '', '', 0),
(10669, 'koKR', 'Wbrew wszelkim przeciwnościom', 'Niektóre demony nie są wierne nikomu poza sobą. Prawdziwy wróg demonów odnajduje i niszczy swoją ofiarę bez względu na jej przynależność.$B$BDemon Xeleth – zbieg z Legionu – był niegdyś czczony jako bóg przez prymitywne bagienne stwory z Moczarów Zangarskich. Gdy Draenor został niemal zniszczony, zapadł w sen głęboko pod Jeziorem Błędnych Ogników. Znajdź portal przy jeziorze i wbij tę włócznię w ziemię.$B$BXeleth się obudzi – bądź $ggotów:gotowa;, by go zabić i dowieść, że jesteś wrogiem wszystkich demonów.', 'Altruis Cierpiący chce, żebyś $gwziął:wzięła; Nasyconą srebrną włócznię i $gużył:użyła; jej na Polanie Portalu przy Jeziorze Błędnych Ogników na Moczarach Zangarskich, by obudzić Xeletha. Gdy zabijesz demona, wróć do Altruisa.', '', 'Wróć do Altruisa Cierpiącego w Nagrandzie.', '', '', '', '', 0),
(10689, 'koKR', 'Altruis', 'Dziś rzadko spotyka się łowców demonów. Ich własny lud patrzy na nich podejrzliwie, a bardzo rzadko trafia się taki, który nie byłby w jakiś sposób związany z Illidanem.$B$BKrążą pogłoski o jednym takim łowcy demonów w Nagrandzie. Nazywa się Altruis. Z pasją nienawidzi wszystkich demonów i pomoże nam, jeśli przekonasz go, że masz te same cele.$B$BUdaj się do zachodniego Nagrandu i odszukaj go. Może zechce rzucić nieco światła na te nowe tereny szkoleniowe łowców demonów.', 'Udaj się do zachodniego Nagrandu i odszukaj Altruisa Cierpiącego.$B$BWykonywanie zadań dla Widzących obniży twoją reputację u Aldorów.', '', '', '', '', '', '', 0),
(10691, 'koKR', 'Powrót do Widzących', 'Ta księga... Mógłbym jej użyć, by dziesięciokrotnie zwiększyć swoją moc... Nie! W końcu zepsułaby mi duszę, tego jestem pewien. Wróć do tych, którzy cię tu przysłali, $N.$B$BMasz teraz sposób, by powstrzymać Varedisa. Zaczekaj, aż przez metamorfozę przybierze demoniczną postać – wtedy musisz spalić księgę w jego obecności. Tylko w ten sposób pozbawisz go mocy.', 'Porozmawiaj z Larissą Słoneczne Uderzenie w Sanktuarium Gwiazd w Dolinie Cienistego Księżyca.$B$BWykonywanie zadań dla Widzących obniży twoją reputację u Aldorów.', '', '', '', '', '', '', 0),
(10953, 'koKR', 'Wizyta przy Tronie Żywiołów', '$GSłyszałeś:Słyszałaś; o Tronie Żywiołów? To podobno takie miejsce w Nagrandzie, gdzie są te potężne żywiołaki.$B$BKiedyś zostanę potężną magiczką, a może czarnoksiężniczką. Będę musiała się dowiedzieć czegoś o siłach żywiołów!$B$BMyślisz, że moglibyśmy tam pójść?$B$B<Salandria zerka na ciebie chytrze.>$B$BWiesz, to byłaby bardzo pouczająca wycieczka. To podobno tuż na północ od Garadaru, po drugiej stronie Jeziora Niebiańskiej Pieśni.', 'Zabierz swoją sierotę, Salandrię, do Tronu Żywiołów w Nagrandzie. Jeśli po przybyciu jej przy tobie nie będzie, przywołaj ją. Następnie porozmawiaj z elementalistką Sharvak.', 'Salandria zabrana do Tronu Żywiołów', 'Porozmawiaj z elementalistką Sharvak w Nagrandzie.', '', '', '', '', 0),
(10954, 'koKR', 'Jheel jest na Przystani Aeris!', 'Tęsknię za moim bratem, Jheelem. Jest kilka lat starszy ode mnie, więc pozwolili mu zacząć terminować u eteryków w Nagrandzie.$B$BByłoby miło go odwiedzić. Uwielbia geologię i takie tam, więc założę się, że świetnie się bawi.$B$BOpiekunka sierocińca powiedziała mi, że szkoli się w miejscu zwanym Przystanią Aeris w Nagrandzie. To podobno przy drodze, daleko na zachód od Telaar i na północny zachód od wielkiej góry, Oshu\'gun.', 'Zabierz swoją sierotę, Dornaę, na Przystań Aeris w Nagrandzie. Jeśli po przybyciu jej przy tobie nie będzie, przywołaj ją. Następnie porozmawiaj z Jheelem.', 'Dornaa zabrana na Przystań Aeris', 'Porozmawiaj z Jheelem w Nagrandzie.', '', '', '', '', 0),
(10986, 'koKR', 'Oczy na niebie', 'Odnalezienie fragmentów Księgi Kruka, o ile w ogóle przetrwały, będzie trudne. Naszą największą nadzieją jest para oczu bystrzejszych niż twoje.$B$BW zachodnim Nagrandzie, na wschodniej krawędzi Grani Zmierzchu, wartowniczka Elaira bada różne gatunki ptaków, które się tam gnieżdżą. Odwiedź ją i sprawdź, czy pomoże ci wykorzystać ptasi wzrok do zebrania fragmentów Księgi Kruka.', 'Porozmawiaj z wartowniczką Elairą na Grani Zmierzchu w Nagrandzie.', '', '', '', '', '', '', 0),
(10987, 'koKR', 'Złapać krogulca', 'Dzikie krogulce z Nagrandu mają najbystrzejszy wzrok ze wszystkich tutejszych ptaków drapieżnych. Ale z powodu swoich rozmiarów zostały wyparte z większości terenów przez większe wichrowe roki.$B$BWiększość krogulców gnieździ się tutaj, na Grani Zmierzchu. Jeśli złapiesz jednego, wyszkolę go, by wypatrywał fragmentów twojej zakopanej tablicy.$B$BBędzie to jednak trudne. Krogulce są bardzo płochliwe i uciekają, gdy się zbliżasz. Radzę osaczyć któregoś albo podkraść się dość blisko, by zarzucić sieć.', 'Użyj Sieci na krogulce, by schwytać dzikiego krogulca, i zanieś go wartowniczce Elairze na Grani Zmierzchu.', '', 'Wróć do wartowniczki Elairy na Grani Zmierzchu w Nagrandzie.', '', '', '', '', 0),
(10988, 'koKR', 'Krucze Kamienie', 'Wyszkoliłam twojego krogulca, by reagował na określony gwizd. Gdy usłyszy ten dźwięk, ptak przyleci do ciebie i poprowadzi cię do najbliższego fragmentu tablicy. Arthorn przekazała, że fragmenty, których szukasz, są zakopane w okolicach Skettis w południowo-wschodniej Puszczy Terokkar, więc ptak będzie tam na ciebie czekał.$B$BGdy zbierzesz wszystkie kamienie, oddaj gwizdek Arthorn, a ona zajmie się zwierzęciem i je wypuści.$B$BPozdrów ode mnie Arthorn, gdy ją zobaczysz.', 'Zbierz 8 Kruczych Kamieni w Skettis i zanieś je Arthorn Pieśni Wiatru w Wiecznym Gaju w Górach Klingi.', '', 'Wróć do Arthorn Pieśni Wiatru w Wiecznym Gaju w Górach Klingi.', '', '', '', '', 0),
(11037, 'koKR', 'Dziwna wizja', 'Miałam bardzo niezwykłą wizję, $N, i nie wiem, co o niej myśleć. Widziałam strzałę, ogromną strzałę, wzbijającą się w niebo na smudze ognia. Dla wprawnego maga to drobnostka, ale jakimś sposobem wiem, że strzała, którą widziałam, nie jest dziełem magii.$B$BBędzie to coś, czego lud Azeroth nigdy dotąd nie dokonał. Musisz odszukać tych, którzy nad tym pracują, $N. Pomóż im, bo bez twojej pomocy ich wysiłki mogą spełznąć na niczym.', 'Porozmawiaj z Rakietowodzem Kadłubkiem w Strefie 52.', '', '', '', '', '', '', 0),
(11042, 'koKR', 'Zagadkowa wizja', 'Nawiedza mnie dziwna wizja, $N. Widzę nieprzerwaną chmurę dymu wznoszącą się ku niebu, zostawianą przez olbrzymi ogień, który oddala się coraz szybciej. Nie jest to zjawisko naturalne ani dzieło zła – tyle wiem.$B$BNie wiem, jak to wygląda, poza tym, że jest owocem pracy wielu. Lecz bez kolejnych rąk do pracy może nigdy nie powstać.$B$BUdaj się do Burzy Otchłani, $N. Odszukaj tych, którzy za tym stoją, i zaoferuj im pomoc.', 'Porozmawiaj z Rakietowodzem Kadłubkiem w Strefie 52.', '', '', '', '', '', '', 0),
(11044, 'koKR', 'Wizje zniszczenia', 'Wizja kataklizmu często zakłóca mój spoczynek – deszcz zielonego ognia spadający na ziemię i powalający dzielnych obrońców potężnej twierdzy. Nawiedza mnie od tygodni, choć dopiero niedawno zrozumiałem jej znaczenie.$B$BDaleko na wschodzie, w Dolinie Cienistego Księżyca, krasnoludy z Dzikiego Młota odpierają nieustanne ataki Płonącego Legionu i wielu innych wrogów. Walczą dzielnie, ale bez wsparcia ich wrogowie zatriumfują. Stań u ich boku, $N. Pomóż im w walce.', 'Porozmawiaj z dowódcą skrzydła Nuainnem w Warowni Dzikiego Młota.', '', '', '', '', '', '', 0),
(11048, 'koKR', 'Raport Kroghana', 'Pierwotnie miałem rozkaz zostać przez krótki czas w Garadarze, a potem ruszyć dalej i zameldować się u strażnika krwi Gulmoka w Wiosce Cienistego Księżyca. Przez ten czas przekonałem się, że Garadarowi przydałby się stały łącznik z Hordą.$B$BWiem, że strażnik krwi Gulmok potrzebuje wszystkich żołnierzy, jakich może zdobyć, ale wiem też, że zrozumie, iż moja misja tutaj jeszcze się nie skończyła. Udaj się do Wioski Cienistego Księżyca w północno-zachodniej części Doliny Cienistego Księżyca i przekaż strażnikowi krwi Gulmokowi, że moje przybycie się opóźni.', 'Porozmawiaj ze strażnikiem krwi Gulmokiem w Wiosce Cienistego Księżyca.', '', '', '', '', '', '', 0),
(11502, 'koKR', 'W obronie Halaa', 'Nie jesteśmy wojowniczą rasą, $N. Lecz gdy wojna przychodzi na nasze ziemie, nie uciekamy przed nią.$B$BPrzymierze i Horda toczą wojnę w mieście Halaa, na północnym zachodzie. Nie wiemy, co knują krwawe elfy, ale każde zwycięstwo Hordy byłoby katastrofą. Historia naszego ludu i orków to historia rozlewu krwi i zdrady.$B$BIdź i zabijaj wrogów w Halaa, a zostaniesz $gnagrodzony:nagrodzona; monetą, honorem i sławą.', 'Pokonaj 10 wrogich graczy w Halaa i wróć do Lakoora w Telaar.', '', 'Wróć do Lakoora w Telaar w Nagrandzie.', '', '', '', '', 0),
(11503, 'koKR', 'Wrogowie starzy i nowi', 'Nasi odwieczni wrogowie, draenei, powrócili z potężnymi sojusznikami. Toczą wojnę w Halaa, na południowy zachód stąd.$B$BNie możemy pozwolić im tam zwyciężyć, bo wtedy bez wątpienia następny byłby Garadar.$B$BIdź i zabij tych, którzy pomagają naszym odwiecznym wrogom.', 'Pokonaj 10 wrogich graczy w Halaa i wróć do Karrtoga w Garadarze.', '', 'Wróć do Karrtoga w Garadarze w Nagrandzie.', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(9789, 'koKR', 'Niezły start. Ale to dopiero początek.$B$BMniejsze rozłupokopyty niczego nie dowodzą. Czas na większe wyzwanie.', 0),
(9800, 'koKR', 'Proszę, nie myj się w świętych wodach Tronu.$B$B<Elementalista Lo\'ap unosi przygotowaną tabletkę z caracoli.>$B$BWłóż ją pod język i poczekaj, aż się całkiem rozpuści. Gdy to nastąpi, będziesz $gmógł:mogła; oddychać wodą jak powietrzem.', 0),
(9804, 'koKR', '<Elementalista Lo\'ap klęka w wodzie i odmawia modlitwę.>$B$BKrąg Ziemi nie jest dumny z tego, co trzeba było zrobić. Robimy, co musimy, by uleczyć ziemię.', 0),
(9805, 'koKR', 'Twoje wysiłki zahamowały rozprzestrzenianie się skażenia, ale pojawiły się inne kłopoty.', 0),
(9810, 'koKR', 'Żywioły zaśpiewały o twoim zwycięstwie w chwili, gdy wzburzona esencja została zniszczona! Krąg Ziemi dziękuje ci i prosi, byś $gwybrał:wybrała; nagrodę.', 0),
(9815, 'koKR', 'Krąg Ziemi dziękuje ci, $N. Żywioły również ci dziękują. Twoje nieustające wysiłki w oczyszczaniu naszego świata zostały docenione i zapamiętane.', 0),
(9818, 'koKR', '<Gordawg zdaje się kiwać do ciebie głową.>$B$BSiadaj.$B$B', 0),
(9819, 'koKR', '<Gordawg z aprobatą kiwa głową.>$B$BDobrze. Duchy teraz śpią.', 0),
(9821, 'koKR', '<Gordawg wypluwa przeżuty kamień, zasypując cię gradem okruchów.>$B$BTrucizna. Te kamienie to nie Nagrand. Te kamienie są z trucizny. Ty niszczysz trujący kamień. Ty znajdujesz uzurpatora.', 0),
(9849, 'koKR', 'GUROK! Gurok zdradził żywioły!', 0),
(9850, 'koKR', 'Imponujące. Naprawdę imponujące.$B$BMasz potencjał, $gmały:mała;. A teraz dam ci okazję do prawdziwej zabawy!', 0),
(9851, 'koKR', 'Udało ci się! $GPowaliłeś:Powaliłaś; Banthara! Ani przez chwilę nie wątpiłem, $N.$B$BMasz, myślę, że w pełni na to $gzasłużyłeś:zasłużyłaś;.', 0),
(9852, 'koKR', '$N! Radujesz serce tego starego krasnoluda.$B$BTeraz się $gwykazałeś:wykazałaś;: $gdołączyłeś:dołączyłaś; do grona najlepszych! Inni uciekali ze strachu albo ginęli stratowani przez bestię. Ty $gużyłeś:użyłaś; rozumu, sprytu i determinacji, by dowieść swojego mistrzostwa w łowach.$B$BWeź to i pamiętaj, że zawsze możesz polować u mego boku!', 0),
(9853, 'koKR', '<Gordawg wgryza się w ziemną głowę Guroka, niemal rozkruszając kamienną bryłę.>$B$BRządy Guroka dobiegły końca. Żywiołaki ziemi są wolne. Wszystkie teraz śpią. Czempion dostaje nagrodę!', 0),
(9854, 'koKR', 'Każdy dzień to dar. Wykorzystaj go jak najlepiej. Bo jutro przemierzymy równiny szybciej niż dziś. Sięgniemy dalej i będziemy dążyć do tego, o czym dziś wieczorem możemy tylko marzyć, choćby miało nam to zawsze umykać.', 0),
(9855, 'koKR', 'Po raz kolejny $gdowiodłeś:dowiodłaś; swoich umiejętności, $N. Teraz musisz zapolować na najdzikszego z wichrowych roków.', 0),
(9856, 'koKR', 'Jej oko wygląda, jakby wciąż żyło. Myślisz, że nadal potrafi zajrzeć ci w duszę?$B$B$N, możesz się teraz zaliczać do najlepszych łowców safari. I jesteś o krok bliżej upolowania największej zdobyczy tej krainy – Ciosaczki!$B$B$GZasłużyłeś:Zasłużyłaś; na to. Niech dobrze ci służy.', 0),
(9857, 'koKR', 'Niezła opowieść... <kaszel>... o tym, jak $gustrzeliłeś:ustrzeliłaś; te wszystkie rogacze, $N. Ale myślę, że stać cię na więcej. Mam dla ciebie coś innego.', 0),
(9858, 'koKR', '<kaszel>, <kaszel>... $N! Udało ci się. Zostało już tylko... <kaszel>... jedno do... <kaszel>... zrobienia.', 0),
(9859, 'koKR', 'Rany! Udało ci się! To naprawdę kopyto Bach\'lora!$B$BHm, wygląda na to, że zaczynam czuć się dużo lepiej. Proszę, pozwól, że dam ci coś, by uczcić twój dowiedziony myśliwski kunszt!', 0),
(9861, 'koKR', 'To wołanie o pomoc, $N. Jakaś obca siła próbuje zawładnąć żywiołami.', 0),
(9862, 'koKR', '$GWidziałeś:Widziałaś;, jak panują nad żywiołami? Wiatr poddawał się ich woli?$B$B<Morgh na chwilę pogrąża się w myślach.>$B$BTo niepokojące, $N. Muszę naradzić się z pozostałymi.$B$BDziękujemy ci za twoje wysiłki, $N. Może $gpowinieneś:powinnaś; wrócić do swojej osady i sprawdzić, czy wiedzą coś więcej o Mętnej Krwi i jej niecnych zamiarach.', 0),
(9863, 'koKR', 'Dajesz Synom Błyskawicy nadzieję, $N. Skoro nasz przywódca nas nie obroni, może są inni, którzy to potrafią – tacy jak ty.', 0),
(9864, 'koKR', 'Słyszałem opowieści o moim ludzie. Mówią, że kiedyś byliśmy wojownikami...', 0),
(9865, 'koKR', '<Zaurzykieł odwraca się do ciebie.>$B$BCzy to krew czuję? Żałuję, że nie mogłem ci pomóc. Jakże musisz być $gdumny:dumna;. Pierś mi się rozpiera na samą myśl o tym, czego $gdokonałeś:dokonałaś;.$B$BCzy są inni tacy jak ty? Czy tam, skąd pochodzisz, jest więcej bohaterów?', 0),
(9866, 'koKR', '<Wieszcz Corhuk wpatruje się w ziemię, pogrążony w rozmyślaniach. Kiwa twierdząco głową.>$B$B<Wieszcz Corhuk ociera łzę.>$B$BSyn jest ojcem... Niech duchy zlitują się nad tymi, którzy staną mu na drodze.', 0),
(9867, 'koKR', 'A więc tak wygląda twarz naszego wroga? Każę ją zatknąć na pice i postawić przed Garadarem, przy bramach. Jeśli znów pomyślą o ataku na nas, zobaczą, jak kończą się ich czyny – będzie na nich spoglądać z góry...', 0),
(9868, 'koKR', 'Co to za różnica? Wszechmatka umiera. Nie warto żyć...', 0),
(9869, 'koKR', 'Ach, dziękuję za wiadomość. Może zechcesz pomóc Kręgowi Ziemi? Żywioły są w chaosie. Przyda nam się każda pomoc.', 0),
(9870, 'koKR', 'Ach, dziękuję za wiadomość. Może zechcesz pomóc Kręgowi Ziemi? Żywioły są w chaosie. Przyda nam się każda pomoc.', 0),
(9871, 'koKR', '<Arechron uderza pięścią w dłoń.>Ortor... Zdradziecki drań!', 0),
(9872, 'koKR', '<Garosz zgniata mapę i wrzuca ją do ognia.>$B$BI co z tego? Atakują nas od tygodni. To nic nowego.$B$BNie rozumiesz? Już po nas... Wszechmatka Geyah umiera.', 0),
(9873, 'koKR', 'Tysiąc martwych orków, powiadasz? Co mogło wywołać tak zuchwały wypad na ziemie orków? Dobrze, że nie żyje, ale kryje się za tym więcej, niż widać na pierwszy rzut macki.', 0),
(9874, 'koKR', '<Otonbu wzdycha.>$B$BTo odsunie wszelkie szanse na pokój z orkami o kolejne 10 lat. Przynajmniej doczekamy tych lat – w przeciwieństwie do tego, co mogłoby się stać, gdybyśmy pozwolili tym zwłokom zgnić.', 0),
(9878, 'koKR', 'Wątpię, by orkowie zrozumieli lub docenili to, co właśnie $gzrobiłeś:zrobiłaś;, ale Nagrand na tym zyskał. Dziękuję ci, $grozwiązywaczu:rozwiązywaczko; problemów...', 0),
(9879, 'koKR', 'Tak, wiem o tym totemie... ale ta historia kryje znacznie więcej. Niestety, nie mam prawa ci tego wyjawić. Tylko wybrańcy mogą poznać taką wiedzę.', 0),
(9882, 'koKR', 'No proszę, jestem pod wrażeniem. W większości są w doskonałym stanie.$B$BZadbam o to, by nasi dobrze o tobie usłyszeli.', 0),
(9883, 'koKR', 'Przynoś dalej odłamki kryształu, $N. Nie możemy pozwolić, by ci złodzieje zabierali naszą własność.$B$BNawet jeśli jeszcze nie całkiem jest nasza. To oczywiście formalność.', 0),
(9884, 'koKR', 'Konsorcjum słynie z tego, że dobrze dba o swoich przyjaciół. Na początku każdego miesiąca będę mieć dla ciebie trochę klejnotów jako zapłatę za twoje usługi.$B$BJakość klejnotów, które dostaniesz, zależy od tego, jak $gbyłeś:byłaś; nam $glojalny:lojalna;. Mam nadzieję, że postąpisz rozsądnie i zostaniesz z nami.', 0),
(9885, 'koKR', 'Konsorcjum słynie z tego, że dobrze dba o swoich przyjaciół. Na początku każdego miesiąca będę mieć dla ciebie trochę klejnotów jako zapłatę za twoje usługi.$B$BJakość klejnotów, które dostaniesz, zależy od tego, jak $gbyłeś:byłaś; nam $glojalny:lojalna;. Mam nadzieję, że postąpisz rozsądnie i zostaniesz z nami.', 0),
(9886, 'koKR', 'Konsorcjum słynie z tego, że dobrze dba o swoich przyjaciół. Na początku każdego miesiąca będę mieć dla ciebie trochę klejnotów jako zapłatę za twoje usługi.$B$BJakość klejnotów, które dostaniesz, zależy od tego, jak $gbyłeś:byłaś; nam $glojalny:lojalna;. Mam nadzieję, że postąpisz rozsądnie i zostaniesz z nami.', 0),
(9887, 'koKR', 'Konsorcjum słynie z tego, że dobrze dba o swoich przyjaciół. Na początku każdego miesiąca będę mieć dla ciebie trochę klejnotów jako zapłatę za twoje usługi.$B$BJakość klejnotów, które dostaniesz, zależy od tego, jak $gbyłeś:byłaś; nam $glojalny:lojalna;. Mam nadzieję, że postąpisz rozsądnie i zostaniesz z nami.', 0),
(9892, 'koKR', 'Dobrze na nich zarobimy, $N. Dopilnuję, żeby Khoraazi usłyszał o twojej pracy.', 0),
(9893, 'koKR', 'Świetnie. To utrzyma nasz interes, póki czekamy, aż Sha\'tar skończą te swoje porządki, które muszą zrobić w Oshu\'gun.', 0),
(9897, 'koKR', 'Cóż, nie widziałem, czy $gpomogłeś:pomogłaś; uratować Kristen, czy nie. Ale skoro dała ci jeden ze swoich pakunków skór, to w moich oczach jesteś w porządku. Oto twoja nagroda.', 0),
(9900, 'koKR', 'Dzięki tobie nie musimy się już martwić Gava\'xim. Zajmijmy się teraz twoją nagrodą.', 0),
(9906, 'koKR', 'Nasze zadanie jeszcze się nie skończyło. Trzeba dać nauczkę kolejnym!', 0),
(9907, 'koKR', 'Jeśli to nie zmrozi im krwi w żyłach, nic tego nie zrobi. $GOddałeś:Oddałaś; sprawiedliwość Mag\'harom, $N. A za sprawiedliwość Mag\'harowie sowicie nagradzają.', 0),
(9910, 'koKR', 'Może chcesz kolejne zadanie? Coś bardziej delikatnego, hm?', 0),
(9913, 'koKR', '$GGotów:Gotowa; do pracy? Chyba mam dla ciebie idealne zadanie.', 0),
(9914, 'koKR', 'Ani przez chwilę w ciebie nie wątpiłem, przyjacielu. Większość z nich to piękne okazy, choć trochę brudne i porysowane. Mimo to myślę, że są warte tyle, na ile się wcześniej umówiliśmy.$B$BMam nadzieję, że będziemy dalej robić interesy.', 0),
(9915, 'koKR', 'Świetnie, więcej pięknych okazów kłów, choć niektóre wyglądają na nieco zaniedbane. Masz daleko sięgającą wdzięczność Konsorcjum, $N.', 0),
(9916, 'koKR', 'Większość naszego dobytku została zniszczona lub skradziona podczas ataków. Nie mogę ci wiele zaoferować, ale jest tu kilka rzeczy, które mogą ci się przydać...', 0),
(9917, 'koKR', '<Bintook czyta plany.>NA ŚWIATŁOŚĆ! Mają okropny charakter pisma. Z tego, co udaje mi się odczytać, albo planują „zjeść niebieskoskórych i zabrać im wioskę”, albo upiec placek z jagodami. Równie dobrze może chodzić o jedno, jak i o drugie. Musimy dojść do sedna tej sprawy!', 0),
(9918, 'koKR', 'O rany! To ma być mały oddział zwiadowczo-łowiecki? Musisz powiedzieć Mo\'morowi, czego się $gdowiedziałeś:dowiedziałaś;.', 0),
(9920, 'koKR', 'A więc nowe plemię ogrów spycha Głazopięściów coraz dalej na południe. To bardzo niepokojące. Najpierw musimy się zająć sytuacją najbliżej domu...', 0),
(9921, 'koKR', 'Doskonale. Czy przypadkiem $gnatrafiłeś:natrafiłaś; na tę istotę, Lantresora, o której wspominał list tego głupka?$B$BTak czy inaczej, musimy działać dalej. Dostałem raporty o kolejnych ruchach ogrów, którymi trzeba się natychmiast zająć!', 0),
(9922, 'koKR', 'Świetna robota! Właśnie badam plemię Wojennych Maczug, o którym wspominał porucznik Głazopięści. Teraz zadania, które $gwykonałeś:wykonałaś;, muszą zostać sprawdzone.', 0),
(9923, 'koKR', 'Naprawdę bardzo mi przykro. Ciągle pakuje się w kłopoty. Chciałbym móc go trzymać na smyczy...', 0),
(9924, 'koKR', 'Bardzo ci dziękuję, $N. Od teraz zajmie się nim jego matka.', 0),
(9925, 'koKR', 'Wywołujesz uśmiech na mojej twarzy, $N. A raczej $gwywołałbyś:wywołałabyś; go, gdybym miał twarz.$B$BTak dalej, a zostaniemy najlepszymi przyjaciółmi.', 0),
(9927, 'koKR', 'Wyobrażasz sobie, jak będą się głowić, co się dzieje? To będzie wspaniałe.', 0),
(9928, 'koKR', 'Doskonale! Naszym następnym celem będą Ruiny Śmiejącej się Czaszki.', 0),
(9931, 'koKR', 'Plan jest doskonały, $N. Już widzę owoce twojej pracy.', 0),
(9932, 'koKR', 'Muszę przyznać, że od dziesięcioleci nie czułem się tak żywy. $GSpisałeś:Spisałaś; się dobrze, $N.', 0),
(9933, 'koKR', 'Proszę, $N, weź z daru pokoju, cokolwiek zechcesz. W końcu bez twoich wysiłków nie byłoby to możliwe.', 0),
(9934, 'koKR', '<Garosz odkopuje skrzynię na bok.>$B$BTracisz czas. Weź ze skrzyni, co chcesz. Ani mnie, ani Garadarowi nie są potrzebne te bezużyteczne błyskotki.', 0),
(9935, 'koKR', 'Wiedźma nie żyje! To wspaniała wiadomość, $N. Oto twoja nagroda.', 0),
(9936, 'koKR', 'Wiedźma nie żyje! To wspaniała wiadomość, $N. Oto twoja nagroda.', 0),
(9937, 'koKR', 'Mordercza hegemonia Durna dobiegła końca! Dzięki tobie Nagrand czeka jaśniejsze jutro, $gbohaterze:bohaterko;. Dobra robota!', 0),
(9938, 'koKR', 'Mordercza hegemonia Durna dobiegła końca! Dzięki tobie Nagrand czeka jaśniejsze jutro, $gbohaterze:bohaterko;. Dobra robota!', 0),
(9939, 'koKR', 'To wielkie zwycięstwo mieszkańców Garadaru! Dobra robota, $N!', 0),
(9940, 'koKR', 'To wielkie zwycięstwo mieszkańców Telaar! Dobra robota, $N!', 0),
(9944, 'koKR', 'Trzydziestu orków! Z tych trzydziestu zostaliśmy tylko Ungriz i ja. Młodego orka, Zaurzykła, znaleźliśmy ledwie żywego niedaleko Słonecznego Źródła. Najwyraźniej był tu z innego powodu...', 0),
(9945, 'koKR', 'To dobry początek, ale trzeba się rozprawić z ich przywódcą, by twoje czyny przyniosły trwały skutek.', 0),
(9946, 'koKR', 'Ta głowa zawiśnie na bramie Garadaru, żeby wszyscy mogli ją zobaczyć. Ogry zastanowią się dwa razy, zanim przerwą święte obrzędy Mag\'harów.', 0),
(9948, 'koKR', '$GDokonałeś:Dokonałaś; tego, co wszyscy uważali za niemożliwe, i $gsprowadziłeś:sprowadziłaś; z powrotem naszych zaginionych braci i siostry. Jesteś $gbohaterem:bohaterką; Mag\'harów, $N. Wszyscy poznają twoje imię i czyny, których dla nas $gdokonałeś:dokonałaś;.', 0),
(9954, 'koKR', 'Tym razem zamknęli mnie porządnie, $N. Klucz ma król Wojennych Maczug, Cho\'war.', 0),
(9955, 'koKR', 'Dziękuję, $N. Corkiego wysłano, by zamieszkał wśród nocnych elfów w Górach Klingi. Mam nadzieję, że zdołają go uchronić przed kłopotami.$B$BCo do nagrody...', 0),
(9956, 'koKR', 'Niesamowite! Jak $gzdołałeś:zdołałaś; to wszystko $gsam:sama; przynieść?', 0),
(9962, 'koKR', 'Hmm, nieźle. Całkiem nieźle... Masz potencjał, $gmały:mała;. Masz tu trochę złota, żeby ci się w kieszeniach nie nudziło...', 0),
(9967, 'koKR', 'Przyznaję, że nie dawałem ci żadnych szans, $N! To było niesamowite! To co, jeszcze jedna walka? Gurgthock ma już dla ciebie idealnego przeciwnika.', 0),
(9970, 'koKR', 'Ogry zaczynają się pocić, $gmały:mała;! Tym razem masz coś ekstra – nie wydaj wszystkiego w jednym miejscu.$B$B$GGotów:Gotowa; na kolejną walkę? Gurgthock stawia na ciebie cały bank!', 0),
(9972, 'koKR', '$GMAŁY:MAŁA;! $GMAŁY:MAŁA;, TO JEST TO! Następna walka to ta najważniejsza! Mistrzostwo!$B$BDobra, spokojnie. Nie chcemy, żeby ogry się zorientowały, że coś kręcimy. W końcu dostaję działkę od tego wszystkiego.', 0),
(9973, 'koKR', 'O rety. Mogor skorzystał z prawa do walki jako Bohater Wojennych Maczug. Musisz się z nim zmierzyć!$B$BNikt nigdy nie mówił, że Wojenne Maczugi to dobrzy sportowcy... ee... ogry.', 0),
(9977, 'koKR', 'Gurgthock mówił ci, że się opłaci, $gmały:mała;. Wybieraj!', 0),
(9982, 'koKR', 'Czy mój wygląd cię przeraża? Wiesz, kim jestem?', 0),
(9983, 'koKR', 'Czy mój wygląd cię przeraża? Wiesz, kim jestem?', 0),
(9991, 'koKR', 'Świetna robota, $N! Mamy teraz punkt wyjścia do zaplanowania kontrataku.', 0),
(9999, 'koKR', 'Tak jak podejrzewałem. Nie ma konwencjonalnych sposobów na zniszczenie spaczonej stali. Nie wszystko jednak stracone...', 0),
(10001, 'koKR', 'Mam nadzieję, że mój znajomy będzie wiedział, jak zniszczyć obozy. W końcu był inżynierem Legionu...', 0),
(10011, 'koKR', 'Zwyciężyliśmy! Natarcie Legionu zostało powstrzymane!$B$BZa twoje bohaterskie czyny możesz wybrać nagrodę!', 0),
(10044, 'koKR', 'Najpierw musimy poszerzyć twój umysł, byś $gmógł:mogła; obcować z przodkami.', 0),
(10045, 'koKR', 'Jesteś $gbardzo zaradny:bardzo zaradna;, $N. Naszym najlepszym zbieraczom zebranie tych ziół zajęłoby dwa razy więcej czasu.<Wszechmatka Geyah miesza zioła w miksturę, a potem przykłada nalewkę do twoich ust i zmusza cię do wypicia.>Nie bój się.', 0),
(10074, 'koKR', 'Wspaniale, $N. To pomoże nam w walce z plugastwem Przymierza, które pojawiło się na Rubieży.', 0),
(10075, 'koKR', 'Zawsze przyjmuję dostawy proszku kryształowego, $N. Za każdy zestaw próbek, który zdobędziesz, otrzymasz zapłatę.', 0),
(10076, 'koKR', 'Wspaniale, $N. To pomoże nam w walce z plugastwem Hordy, które pojawiło się na Rubieży.', 0),
(10077, 'koKR', 'Dziękuję za twój wkład, $N. Jeśli znajdziesz więcej, wiesz, dokąd go przynieść!', 0),
(10081, 'koKR', 'Mikstura, którą $gwypiłeś:wypiłaś;, nie działa naprawdę. Ducha można zobaczyć tylko wtedy, gdy on sam na to pozwoli. Mikstura jest jedynie symbolem twojej wiary i oddania. To była próba i $gprzeszedłeś:przeszłaś; ją...', 0),
(10082, 'koKR', 'To na nic. Wciąż powstają. Musi się dziać coś bardziej podstępnego.', 0),
(10085, 'koKR', 'To bardzo niepokojące. Mówisz, że w wioskach nie było żadnego z przodków? Że wszyscy ciągnęli na południe?', 0),
(10101, 'koKR', '<Łagodny, melodyjny głos wypełnia twój umysł.>$B$BJestem K\'ure z naaru, $N. Stoisz w sercu mojego pradawnego statku.$B$BOshu\'gun, jak nazwali go orkowie, to statek, który jako pierwszy przywiódł draenei na ten świat. Choć spadliśmy z niebios i rozbiliśmy się tutaj wiele setek lat temu, moja osłabiona energia pozostała uwięziona w tym wraku. Niestety, to ja jestem źródłem cierpienia duchów orków.', 0),
(10107, 'koKR', 'Jaka jest więc twoja decyzja? Będzie wojna czy udzielisz mi pomocy?', 0),
(10108, 'koKR', 'Jaka jest więc twoja decyzja? Będzie wojna czy udzielisz mi pomocy?', 0),
(10109, 'koKR', 'Świetnie! Jeszcze tylko kilka poprawek i ta maszyna będzie jak nowa. A, no tak, twój klucz! Proszę bardzo.$B$BA tak przy okazji, Skakotron ma jeszcze parę usterek, które muszę usunąć. Ee, po prostu uważaj.', 0),
(10111, 'koKR', 'No, to nie jajo... Hej! Kurczaki też uwielbiam! Po prostu przegryzę się przez ten gigantyczny szpon! Dzięki!', 0),
(10113, 'koKR', 'Chyba będziemy musieli znaleźć nowego chłopca od noszenia wody. Ej, wyglądasz na kogoś potężnego. Szukasz pracy? Czy może $gprzyszedłeś:przyszłaś; na łowy?', 0),
(10114, 'koKR', 'Ulżyło mi, gdy usłyszałem, że jest bezpieczny. $GPrzyszedłeś:Przyszłaś; dołączyć do łowów?', 0),
(10168, 'koKR', '$GOdbyłeś:Odbyłaś; długą i niebezpieczną podróż, narażając życie i zdrowie, by zapewnić bezpieczeństwo Mag\'harom i spokój naszym przodkom. Jestem ci za to wdzięczna bardziej, niż zdołają wyrazić słowa.', 0),
(10170, 'koKR', 'Chcę, żebyś $gosobiście przekazał:osobiście przekazała; te wieści Garoszowi.', 0),
(10171, 'koKR', 'Wszyscy są dumni. Dumni, że nasz lud dożyje kolejnej zimy. Ale co poza tym? Co jeszcze nam zostało?$B$BMoże to ty $gpowinieneś:powinnaś; przewodzić temu klanowi, $N. Może wtedy będzie mi wolno umrzeć, gdy odejdzie Wszechmatka. W końcu zmyć hańbę z nazwiska mojej rodziny. Tęsknię za takim spokojem.', 0),
(10172, 'koKR', '<Po twarzy Wszechmatki Geyah płyną łzy.>$B$BOdszukaj swojego wodza. Powiedz mu, że czekam tu na niego...', 0),
(10252, 'koKR', '$GNieznajomy:Nieznajoma;... Nie byłem z tobą szczery. Gdy wypijesz tę miksturę, już zawsze będziesz widzieć świat umarłych. Ten wywar to rytuał wtajemniczenia wszystkich kapłanów śmierci z Auchindoun. Wielu popada w obłęd, gdy zacznie działać. Widok umarłych jest... wstrząsający.$B$B<Nitrin przykłada miksturę do twoich ust.>$B$BCzy chcesz kontynuować?', 0),
(10476, 'koKR', 'Zaczynasz dowodzić swojej wartości jako $gsojusznik:sojuszniczka; i $gwojownik:wojowniczka;. Tak trzymaj.', 0),
(10477, 'koKR', 'Wciąż dowodzisz nam swojej wartości, $N. Oby siła nigdy cię nie opuściła.', 0),
(10478, 'koKR', 'Wciąż dowodzisz swojej siły i honoru, $N.', 0),
(10479, 'koKR', 'Jesteś naprawdę $gsilnym sojusznikiem:silną sojuszniczką;, $N. Nie każdy potrafi stanąć twarzą w twarz z ogrami Rubieży.', 0),
(10640, 'koKR', 'Daleką drogę $gprzebyłeś:przebyłaś;, $gnieznajomy:nieznajoma;. Dziwię się, że ktokolwiek cię przysłał, w ogóle o mnie słyszał.', 0),
(10641, 'koKR', '$GDowiodłeś:Dowiodłaś;, że nie skaził cię dotyk Legionu, a wróg mojego wroga jest moim przyjacielem.', 0),
(10646, 'koKR', 'Znasz już tę historię. Zostało tylko jedno do zrobienia.', 0),
(10650, 'koKR', 'Przynosisz tę ohydną księgę do tego świętego miejsca? Lepiej, żebyś $gmiał:miała; bardzo dobre wyjaśnienie, $N.', 0),
(10668, 'koKR', 'A więc nie jesteś po stronie Illidana. Jesteś o krok bliżej pełnego zaufania z mojej strony.', 0),
(10669, 'koKR', 'Dobra robota, $N. Pamiętał jeszcze dzień, w którym wbiłem w niego tę włócznię? To było tak dawno...', 0),
(10689, 'koKR', 'Daleką drogę $gprzebyłeś:przebyłaś;, $gnieznajomy:nieznajoma;. Dziwię się, że ktokolwiek cię przysłał, w ogóle o mnie słyszał.', 0),
(10691, 'koKR', 'Wielu zapłaciłoby wysoką cenę za księgę, którą nosisz. Szkoda, że będziemy musieli ją zniszczyć.', 0),
(10953, 'koKR', 'Przyprowadzasz tu dziecko? To lekkomyślne, ale obiecuję, że nie stanie jej się krzywda, przynajmniej dopóki nie podejdzie zbyt blisko Incineratusa.$b$bHmm, szkoda, że to krwawa elfka. Gdyby była zdolna do głębokiej więzi ze światem, moglibyśmy ją czegoś nauczyć, by pomogła nam leczyć jego rany. Ale może kontakt z tutejszymi żywiołami da jej choć trochę wglądu w ich działanie.$b$bIdź w pokoju i dopilnuj, by miała u ciebie dobrą opiekę.', 0),
(10954, 'koKR', 'Och, tak bardzo tęskniłem za Dornaą. Dziękuję, że $gprzyprowadziłeś:przyprowadziłaś; ją w odwiedziny. Tu, gdzie są tylko eterycy, bywa samotnie. A oni są ciągle tacy poważni przez te sprawy z Oshu\'gun.$b$bAle gdy zdam egzaminy ze szlifowania klejnotów, będę mógł odwiedzić sierociniec. W zeszłym tygodniu prawie je zdałem, ale jestem pewien, że jutro na teście pójdzie mi lepiej!', 0),
(10986, 'koKR', '<Elaira słucha, jak opisujesz poszukiwania Księgi Kruka i pomysł Arthorn, by za pomocą ptaków odnaleźć brakujące fragmenty tablicy.>$B$BTo świetny pomysł, a w Nagrandzie roi się od kandydatów, ale którego wybrać?', 0),
(10987, 'koKR', 'Dobra robota! Wciąż jeszcze zdobywam zaufanie jastrzębi, ale wiem o nich dość, by wyszkolić tego na twoje potrzeby.', 0),
(10988, 'koKR', '<Arthorn przyjmuje od ciebie fragmenty Księgi Kruka i zaczyna je składać.>$B$BCzęść znaków się zatarła, ale większość powinnam odczytać...', 0),
(11037, 'koKR', '<Wódz słucha, jak opisujesz wizję jasnowidzki.>$B$BCóż, nic o tym nie wiem, ale na pewno przyda nam się tu twoja pomoc. Podziwiaj rakietę za mną! To X-52...$B$BCzyż to nie najpiękniejsza rzecz, jaką $gwidziałeś:widziałaś;?', 0),
(11042, 'koKR', '<Wódz słucha, jak opisujesz wizję jasnowidza.>$B$BCóż, nic o tym nie wiem, ale na pewno przyda nam się tu twoja pomoc. Spójrz na tego olbrzyma za mną. To X-52...$B$BCzyż to nie najpiękniejsza rzecz, jaką $gwidziałeś:widziałaś;?', 0),
(11044, 'koKR', 'Wizja, powiadasz? Nieważne, czy zobaczył to w wizji, przeczytał w liście, czy usłyszał z ust lorda otchłani. Trafił w dziesiątkę! Liczy się to, że tu jesteś, przyjacielu, a przyda nam się każda pomoc.', 0),
(11048, 'koKR', '<Gulmok burczy pod nosem, słysząc o decyzji Kroghana.>$B$BRozumiem jego punkt widzenia, ale tu w okopach też potrzebujemy ludzi! Legion zasypuje nas piekielnikami dniem i nocą. Skoro Kroghan się spóźni, ty zajmiesz jego miejsce na polu bitwy!', 0),
(11502, 'koKR', 'Dziękuję ci, $N. Twoje wysiłki nie zostaną zapomniane.', 0),
(11503, 'koKR', 'Przynosisz wielki honor naszemu ludowi. Dziękujemy ci.', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(9789, 'koKR', 'Rozłupokopyty z Nagrandu to niezłe wyzwanie. Sam ustrzeliłem ich całkiem sporo.$B$BJak ci idzie?', 0),
(9800, 'koKR', '<Elementalista Lo\'ap zaciska obie pięści i z dezaprobatą kręci głową.>$B$BOgrze garście...', 0),
(9804, 'koKR', 'Zanim zanurkujesz głęboko w jeziorze, zjedz wiśnie z Nagrandu.', 0),
(9805, 'koKR', 'Z wielkim wstydem wyznaję, że to moi właśni pobratymcy chcą zmącić wody Nagrandu i zamienić je w bagna.', 0),
(9810, 'koKR', 'Krąg Ziemi pomoże na wszelkie możliwe sposoby.', 0),
(9815, 'koKR', 'Nie zostawiaj po sobie ani odrobiny skażonego mułu!', 0),
(9819, 'koKR', 'Czy śpią?', 0),
(9821, 'koKR', 'Gordawg je ten kamień. Gordawg znajduje uzurpatora. Przynieś kamień!', 0),
(9849, 'koKR', 'Gordawg chce, żeby oddać głaz.', 0),
(9850, 'koKR', 'Myślisz, że samce rozłupokopytów same padną martwe u twoich stóp tutaj, przy ognisku?', 0),
(9851, 'koKR', 'Ciepły ogień i kobietę u boku do pogawędki to możesz mieć w domu. Tutaj polujemy na grubego zwierza albo giniemy, próbując.', 0),
(9852, 'koKR', 'Nie ma wstydu w przyznaniu, że brak ci odwagi, by zapolować na najpotężniejsze zwierzę, jakie ma do zaoferowania ta kraina, $N.', 0),
(9853, 'koKR', 'Gordawg zjeść moc Guroka.', 0),
(9854, 'koKR', 'Czy $gpoznałeś:poznałaś; już spokój, który daje świadomość własnego miejsca w naturze? Jesteś łowcą czy zwierzyną?', 0),
(9855, 'koKR', 'Czy $gnauczyłeś:nauczyłaś; się już uspokajać bicie serca? Trwać nieruchomo jak spokojne jezioro i cierpliwie czekać na właściwą chwilę, by powalić zwierzynę?', 0),
(9856, 'koKR', '$GStanąłeś:Stanęłaś; już do walki z Patroszycielem?', 0),
(9857, 'koKR', 'Poleżę tu jeszcze chwilkę. Niedługo powinno mi przejść.', 0),
(9858, 'koKR', 'Pewnie jeszcze... <kaszel>... nie $gzająłeś:zajęłaś; się tymi... <kaszel>... cierniojadami?', 0),
(9859, 'koKR', 'Masz... kopyto?', 0),
(9861, 'koKR', 'Daj to tutaj! Szybko!', 0),
(9862, 'koKR', 'Duch powietrza twierdzi, że Mętna Krew czegoś szuka w Słonecznym Źródle...', 0),
(9863, 'koKR', 'Zrób to dla nas, bo sami nie możemy tego zrobić.', 0),
(9865, 'koKR', 'Za każdego z moich pobratymców, których zabili, musi zginąć dziesięciu z nich!', 0),
(9867, 'koKR', 'Przynieś mi głowę ich przywódcy, $N.', 0),
(9868, 'koKR', '<Garosz ledwie zauważa twoją obecność. Wydaje się pogrążony w głębokim przygnębieniu.>', 0),
(9871, 'koKR', 'Co to jest?', 0),
(9872, 'koKR', 'Co to jest?', 0),
(9873, 'koKR', 'Pamiętaj, $N, Ortor to szaman wielkiej mocy.', 0),
(9874, 'koKR', 'Orkowie nie zrozumieją, co robimy, ale to musi zostać zrobione. Dla dobra zarówno orków, jak i Złamanych.', 0),
(9878, 'koKR', 'Mętna Krew to niecne plemię Złamanych, $N. Mogą wyglądać jak Kurenai, ale bez wątpienia to dzikie, mordercze bestie.', 0),
(9882, 'koKR', 'Czy $godzyskałeś:odzyskałaś; odłamki kryształu, o które cię prosiłem, $N?', 0),
(9883, 'koKR', 'Masz więcej odłamków kryształu? Uważaj, żeby nie brać tych, które są jeszcze przytwierdzone do góry – nie chcielibyśmy narobić sobie kłopotów z naaru.', 0),
(9892, 'koKR', '$GZdobyłeś:Zdobyłaś; więcej paciorków wojennych? Mnóstwo ogrów znajdziesz daleko na północy, przy granicy z Moczarami Zangarskimi.', 0),
(9893, 'koKR', 'Jak cię traktują te ogry, $N? Twarde sztuki, co?', 0),
(9897, 'koKR', 'Kristen to bardzo miła... <kaszel>... osoba, skoro dzieli się skórami, nie sądzisz?', 0),
(9900, 'koKR', '$GWróciłeś:Wróciłaś;, $N. Czy Gava\'xi nie żyje?', 0),
(9906, 'koKR', 'Wysyłam niewielki, dobrze zorganizowany oddział na poszukiwanie reszty mieszkańców.', 0),
(9907, 'koKR', 'Trzeba im przypomnieć, że w tej okolicy jesteśmy siłą, z którą należy się liczyć.', 0),
(9910, 'koKR', 'Szacunek ze strachu! Jest tak samo dobry jak każdy inny.', 0),
(9914, 'koKR', 'Chodzi mi o kość słoniową, nie o wymówki. Oczywiście, jeśli wolisz, możemy renegocjować twój udział w zyskach. Wątpię jednak, by wynik cię zadowolił.', 0),
(9915, 'koKR', 'Wciąż potrzebuję kolejnych par kłów z kości słoniowej od dzikich elekków, które wędrują po tej krainie. Niestety, mój budżet nie udźwignie już twojego udziału w zyskach. Jeśli jednak nadal będziesz mi dostarczać, czego potrzebuję, zaskarbisz sobie przychylność Konsorcjum.', 0),
(9916, 'koKR', 'Może dzieci choć przez jeden dzień nie będą czuć ssania w żołądku.', 0),
(9917, 'koKR', '$GZnalazłeś:Znalazłaś; jakieś nowe informacje?', 0),
(9918, 'koKR', 'Pewnie śpi gdzieś na grani.', 0),
(9921, 'koKR', 'Dopiero niedawno odbiliśmy Telaar. Nie stracimy go znowu!', 0),
(9922, 'koKR', 'Uważaj na żywiołaki w kotlinie, $N.', 0),
(9923, 'koKR', 'Ten chłopak...$B$B<Arechron kręci głową z dezaprobatą.>$B$BWpędzi mnie do grobu.', 0),
(9924, 'koKR', '$GZnalazłeś:Znalazłaś; go?', 0),
(9925, 'koKR', '$GZająłeś:Zajęłaś; się pomiotami Pustki, $N?', 0),
(9927, 'koKR', '<Oczy Lantresora otwierają się szeroko w zdumieniu.>Zrobione?', 0),
(9928, 'koKR', 'Rozpalimy między tymi dwoma klanami nienawiść, jakiej dotąd nie widziano!', 0),
(9931, 'koKR', 'Potrafisz przewidzieć, co się teraz stanie?', 0),
(9932, 'koKR', 'Czy teraz rozumiesz, dlaczego nigdy nie $gwygrałbyś:wygrałabyś; ze mną wojny?', 0),
(9933, 'koKR', 'Pokój, powiadasz?', 0),
(9934, 'koKR', '<Garosza zdaje się nie poruszać ten dar.>', 0),
(9935, 'koKR', 'Przychodzisz po nagrodę?', 0),
(9936, 'koKR', 'Przychodzisz po nagrodę?', 0),
(9937, 'koKR', 'Za Mag\'harów!', 0),
(9938, 'koKR', 'Nie trać czasu! Durna trzeba powstrzymać!', 0),
(9939, 'koKR', 'Przychodzisz po nagrodę?', 0),
(9940, 'koKR', 'Przychodzisz po nagrodę?', 0),
(9945, 'koKR', 'To zaledwie jeden krok długiej drogi. Ogrom, jak psom, trzeba pokazać różnicę między dobrem a złem. Mówienie im nic nie da.', 0),
(9946, 'koKR', 'Bez wątpienia jest pilnie strzeżony.', 0),
(9948, 'koKR', '<Ungriz wzdycha.>$B$BWiem, że proszę o wiele, $N, ale sprowadź ich żywych...', 0),
(9955, 'koKR', 'Gdzie jest Corki?', 0),
(9956, 'koKR', 'Czuję się taka głupia. Syn Arechrona, Corki, zapytał mnie, co się stało, a ja mu powiedziałam. Teraz znowu zaginął!', 0),
(9962, 'koKR', 'Walka kończy się, gdy ty albo twój przeciwnik leżycie martwi na ziemi.', 0),
(9967, 'koKR', 'Walka kończy się, gdy ty albo twój przeciwnik leżycie martwi na ziemi.', 0),
(9970, 'koKR', 'Walka kończy się, gdy ty albo twój przeciwnik leżycie martwi na ziemi.', 0),
(9972, 'koKR', 'Walka kończy się, gdy ty albo twój przeciwnik leżycie martwi na ziemi.', 0),
(9973, 'koKR', 'Walka kończy się, gdy ty albo twój przeciwnik leżycie martwi na ziemi.', 0),
(9977, 'koKR', 'Walka kończy się, gdy ty albo twój przeciwnik leżycie martwi na ziemi.', 0),
(9991, 'koKR', 'Nigdy nie $glatałeś:latałaś; na grzbiecie smokowca Otchłani, co?', 0),
(10001, 'koKR', 'Za wszelką cenę unikaj nadzorców. Nie mogą się zorientować, że tam jesteś. Skutki mogłyby być katastrofalne!', 0),
(10044, 'koKR', 'Proszę, usiądź, $gmój drogi:moja droga;.', 0),
(10045, 'koKR', 'Witaj, $gmój drogi:moja droga;.', 0),
(10074, 'koKR', 'Krystaliczny proszek z góry przenika ziemne jądro tej krainy.$B$B', 0),
(10075, 'koKR', 'Ta baza była głównym ośrodkiem badawczym draenei, w którym badano kryształy naaru.$B$BTo, co odkryliśmy, to prawdziwa kopalnia złota: notatki badawcze o kryształach z „diamentowej” góry, Oshu\'gun. Wygląda na to, że wszystko w tej okolicy nosi w sobie resztki proszku z kryształów Oshu\'gun. Jeśli podczas przygód w tej okolicy znajdziesz trochę proszku, przynieś mi go, a nagrodzę cię żetonem wdzięczności, za który zrobisz zakupy u kwatermistrza.', 0),
(10076, 'koKR', 'Krystaliczny proszek z góry przenika ziemne jądro tej krainy.', 0),
(10077, 'koKR', 'Ta baza była głównym ośrodkiem badawczym draenei, w którym badano kryształy naaru.$B$BTo, co odkryliśmy, to prawdziwa kopalnia złota: notatki badawcze o kryształach z „diamentowej” góry, Oshu\'gun. Wygląda na to, że wszystko w tej okolicy nosi w sobie resztki proszku z kryształów Oshu\'gun. Jeśli podczas przygód w tej okolicy znajdziesz trochę proszku, przynieś mi go, a nagrodzę cię żetonem wdzięczności, za który zrobisz zakupy u kwatermistrza.', 0),
(10082, 'koKR', 'Nie potrzebujesz mikstury, by widzieć duchy, $N.', 0),
(10085, 'koKR', 'Pędź jak wiatr, $N.', 0),
(10109, 'koKR', 'Masz gaz?', 0),
(10111, 'koKR', 'Wspominałem już, jak bardzo kocham jajka?', 0),
(10168, 'koKR', '<Matka Kashur jest wyraźnie poruszona.>Ci naaru przewyższają mądrością wszelkie istoty na tym świecie.', 0),
(10172, 'koKR', '<Wszechmatka Geyah leży.>', 0),
(10252, 'koKR', 'Armia Levixusa z każdą sekundą rośnie w siłę i liczebność. Musisz się pospieszyć.', 0),
(10476, 'koKR', 'No i, $N? Tylko gadasz czy masz mi coś do pokazania?', 0),
(10477, 'koKR', 'Masz przy sobie więcej obsydianowych paciorków wojennych, $n?', 0),
(10478, 'koKR', '$GZdobyłeś:Zdobyłaś; więcej paciorków wojennych, $N?', 0),
(10479, 'koKR', 'Masz mi coś do pokazania, $N?', 0),
(10641, 'koKR', '$GZabiłeś:Zabiłaś; demonicę?', 0),
(10668, 'koKR', 'Czy porucznik Illidari nie żyje?', 0),
(10669, 'koKR', '$GWróciłeś:Wróciłaś;. Czy Xeleth nie żyje?', 0),
(10987, 'koKR', '$GZłapałeś:Złapałaś; któregoś krogulca?', 0),
(10988, 'koKR', 'Czy $godzyskałeś:odzyskałaś; dość fragmentów Księgi Kruka, bym mogła ją odtworzyć?', 0),
(11502, 'koKR', 'Czy twoje zadanie wykonane, $n?', 0),
(11503, 'koKR', 'Czy twoje zadanie wykonane, $N?', 0);
