INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(2944, 'koKR', '<HTML>\n<BODY>\n<IMG src="Interface\\Pictures\\24475_gordawg_256"/>\n</BODY>\n</HTML>', 0),
(2945, 'koKR', '<HTML>\n<BODY>\n<BR/>\n<BR/>\n<H1 align="center">\nZIELONE WZGÓRZA CIERNIODŁAWÓW\n</H1>\n<BR/>\n<H3 align="center">\nHemet Nesingwary\n</H3>\n</BODY>\n</HTML>', 0),
(2949, 'koKR', 'W latach, które nastąpiły, gdy Wichrogród zdradził Gildię Kamieniarzy, sir Erlgadin coraz bardziej gorzkniał z powodu roli szlachty w królestwie. Nie chciał już piastować pozycji, jaką ród jego ojca wywalczył mu w Izbie Szlachty.$B$BAle odbiegam od tematu. Celem tej opowieści nie jest rozprawa polityczna ani biografia. To relacja z moich polowań na grubą zwierzynę na zielonych wzgórzach Cierniodławów...', 0),
(2952, 'koKR', 'Wyruszyliśmy na zachód, przez gęste poszycie splątanej dżungli. Posuwając się powoli i rozważnie, przedzieraliśmy się przez gęstwinę w poszukiwaniu zwierzyny. Poranek minął w pełnym frustracji milczeniu. W dolinie nic się nie poruszało, nie było nawet wiatru. Po południu wyprawę ogarnęło zniecierpliwienie. Barnil nie stąpał już ostrożnie jak drapieżnik tropiący ofiarę. Przeciwnie, człapał niezgrabnie ścieżką, raz po raz z trzaskiem nadeptując na suche liście i opadłe gałęzie.', 0),
(2960, 'koKR', 'Wkrótce Ajeck wytropiła panterę na południowym zachodzie. Szliśmy cicho, z bronią w pogotowiu, wyczekując zdobyczy. Trzask gałązek w pobliskiej kępie drzew natychmiast zwrócił naszą uwagę. Coś tam było. Wystarczyło jedno surowe spojrzenie na Barnila, by przekazać mu moje myśli. Barnil powoli opuścił karabin. Ta zdobycz nie była dla nas, lecz dla naszych ludzkich towarzyszy. Przed naszymi dymiącymi lufami padły już niezliczone pantery. Ta miała paść dla ludzi.', 0),
(2963, 'koKR', 'Jego broń gwałtownie szarpnęła mu się w rękach. Lufa odskoczyła w bok i podbiła karabin Ajeck. Ajeck właśnie w tej chwili pociągnęła za spust. Karabin, teraz niezgrabnie skierowany ku linii drzew, wypalił z wyraźnym hukiem. Stado ptaków z wrzaskiem zerwało się z koron drzew, rozpierzchając się na wszystkie strony. Z drzewa uniósł się pióropusz dymu. Z osłupieniem patrzyliśmy, jak potężny konar spada prosto na uciekającą panterę i łamie jej grzbiet.', 0),
(2967, 'koKR', 'Zwierzę nawet nie wyczuło naszej obecności. Prawdę mówiąc, jedynym powitaniem, jakie zgotowała mu wyprawa, była kula między oczy.$B$BSir Erlgadin wydał gromkie *hurra*, a Ajeck skinęła mi głową z wyraźnym uznaniem. Zacząłem przetrząsać plecak w poszukiwaniu fajki, licząc na uroczystego dymka. Barnil pomknął w górę zbocza, by przynieść truchło raptora. Wpatrywałem się w powaloną bestię z satysfakcją, która towarzyszy każdej grubej zdobyczy.', 0),
(2968, 'koKR', 'Nie mogłem jednak długo pławić się w chwale zdobyczy. Gdy bowiem spojrzałem ku horyzontowi, na grzbiecie wzgórza, tuż nad biednym Barnilem, pojawiło się kilka sylwetek.$B$B*Uciekaj, Barnil!* – krzyknąłem. Ajeck, sir Erlgadin i ja posłaliśmy salwę kul, strzał i bełtów nad głową Barnila w stronę ścigających go raptorów. W zamieszaniu któreś z nas powaliło jednego z nich.', 0),
(2969, 'koKR', 'Nasze pospiesznie oddane strzały wystarczyły, by Barnil zdołał uciec. Zbiegł z powrotem ze wzgórza i dołączył do drużyny. Czmychnęliśmy w dżunglę, a stado dzikich raptorów biczoogonów śledziło każdy nasz ruch.$B$BŁowcy stali się zwierzyną.', 0),
(2974, 'koKR', 'Pędziliśmy bez wytchnienia aż do obozu głównego. Późnym wieczorem siedzieliśmy w milczeniu przy ognisku, wiedząc, że życie ocalił nam dziwaczny zbieg okoliczności. Takie jest ryzyko łowcy grubej zwierzyny. Igramy z losem, sami go wymierzając. A jednak każdy z nas w pewnej chwili stanie oko w oko z ostrymi jak brzytwa zębami losu. Ten krasnolud cieszy się po prostu, że ta chwila nie nadeszła na zielonych wzgórzach Cierniodławów.$B$B--Koniec--', 0),
(2975, 'koKR', 'Głupku,\n\nZnajdź jedzenie. Niebieskie dobre w smak. Lantresor mówić, że wolno. Przynieś jedzenie do Bryła. Bryła jeść pierwszy, potem głupek jeść. Dobra? Szybko, albo Bryła zjeść ciebie.\n\n-Bryła', 0),
(2979, 'koKR', 'Korzeń olemby to dość pospolity korzeń, który rośnie w Puszczy Terokkar. Szukaj wystających z ziemi korzeni w pobliżu drzew olemby, z których składa się większość lasów Terokkaru.\n\nBorówka bagienna rośnie tylko na Moczarach Zangarskich. Można ją znaleźć wyłącznie w Warowni Ango\'rosh, w północno-zachodniej części moczarów. Strzeż się ogrów, które zawzięcie pilnują cennych jagód.\n\nLiść z Telaar jest chyba najłatwiejszym do zdobycia ziołem z tej listy. Liście znajdziesz na południe od Garadaru, w Kotlinie Telaari. Rosną blisko wody.\n\nOstatnie zioło z listy występuje tylko w Górach Klingi. Góry Klingi znajdziesz na północ od Moczarów Zangarskich. Smoczy kolec rośnie na końcach poszarpanych skalnych formacji, które strzegą kanionów Gór Klingi. Zrozumiesz, o czym mówię, gdy pierwszy raz zobaczysz Góry Klingi. Te formacje skalne wyglądają jak rzędy ostrych, spiczastych zębów.', 0),
(2983, 'koKR', 'Aby obdarzyć pijącego nalewkę zdolnością widzenia umarłych, trzeba zebrać pewne składniki.$B$BNajpierw gałkę oczną górskiego gronna z zachodniego Nagrandu, spod przeklętych obozów kuźniczych Płonącego Legionu, na południe od Wzgórza Wojennych Maczug.$B$BW zachodnim Nagrandzie żyją też większe wichrowe roki. Nada się tylko nieskazitelny okaz!$B$BWreszcie tłuszcz wiekowego rozłupokopyta z zachodniego i południowo-zachodniego Nagrandu.$B$BZbierz te rzeczy i przynieś mi je! Pospiesz się!$B$B-Nitrin', 0);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(14758, 'koKR', 'Duchy są niespokojne. Uważaj na otoczenie, gdy przebywasz w Nagrandzie, by nie pochłonęła cię ich furia.', '', 0),
(14759, 'koKR', 'Krąg Ziemi dąży do zachowania siły i majestatu żywiołów.', '', 0),
(14760, 'koKR', '', 'Jak mój lud ma walczyć, gdy żywioły są w takim zamęcie? Czy nie widzą, że bez wsparcia żywiołów świat po prostu nie może istnieć?', 0),
(14761, 'koKR', 'Jestem Untrag z Kręgu Ziemi. Postaraj się nie niepokoić żywiołów, póki przebywasz przy Tronie Żywiołów.', '', 0),
(14778, 'koKR', 'Płoń! Płoń! Płoń!', '', 0),
(14802, 'koKR', '<Ziemia dudni, gdy Gordawg nieruchomieje.>$B$BMów.', '', 0),
(14849, 'koKR', 'Miej oczy szeroko otwarte, $N. Nigdy nie wiesz, kiedy to jakiś zwierzak poluje na ciebie, a nie na odwrót.', '', 0),
(14850, 'koKR', 'Hemecie Nesingwary, co robisz tu, na Rubieży?', 'Hemecie Nesingwary, co robisz tu, na Rubieży?', 0),
(14851, 'koKR', 'Słuchaj, $gchłopcze:dziewczyno;. Zostawiłem wyprawę w dobrych rękach mojego syna, juniora. Gdy już się upolowało najlepszego zwierza w całym Azeroth, zaczyna człowieka swędzieć, żeby spróbować czegoś więcej.$B$BA widziałeś, jakie tu są wielkie bestie?!$B$BPoluję tu na najgroźniejszą zwierzynę, jaką kiedykolwiek zobaczysz. Zamierzam ustrzelić Ciosaczkę i zabrać jej serce jako trofeum!', '', 0),
(14852, 'koKR', '$N! Aż za dobrze pamiętam twój myśliwski kunszt. Może i w Cierniodławach $gzaczynałeś:zaczynałaś; niepewnie, ale $gwytrwałeś:wytrwałaś; i $gstałeś się jednym:stałaś się jedną; z najlepszych, gdy $gustrzeliłeś:ustrzeliłaś; starego Bangalasha.$B$BAle słuchaj, $gchłopcze:dziewczyno;, tu, na Rubieży, zwierzyna jest prawdziwa. I mam blizny, które tego dowodzą!', '', 0),
(14934, 'koKR', 'Witaj, $N. Chcesz sprawdzić granice swojego myśliwskiego kunsztu? Nie szukaj dalej.$B$BHemet Nesingwary zebrał najlepszą wyprawę, jaką kiedykolwiek widziały resztki tego świata. Dołącz do nas na safari, jeśli się odważysz.', '', 0),
(14954, 'koKR', '$GDowiodłeś:Dowiodłaś;, że $gjesteś bardzo zdolnym myśliwym:jesteś bardzo zdolną myśliwą;, $N. Ale jest jeszcze jedna bestia, która nawiedza cię w snach... Ciosaczka!', '', 0),
(14955, 'koKR', '$GUstrzeliłeś:Ustrzeliłaś; je wszystkie: Bach\'lora, Banthara, Patroszyciela, a nawet potężną Ciosaczkę! Naprawdę jesteś $gnajlepszym myśliwym:najlepszą myśliwą; na grubego zwierza, jakiego znam!', '', 0),
(14956, 'koKR', 'No i tarzam się w kłującym poszyciu z talbukiem rogaczem, walczymy wręcz, a ratują mnie tylko ostry nóż... <kaszel>... i bystry umysł myśliwego.$B$BNagle z nieba rzuca się na mnie para drapieżnych wichrowych roków! Ich tchórzliwy atak... <kaszel>... na nic im się jednak nie zdał.$B$BI choć mam ich dzioby jako trofea, nabawiłem się przy tym zakażonego zadrapania. Paskudna sprawa i bardzo boli, ale na pewno za dzień czy dwa się zagoi.', '', 0),
(14983, 'koKR', 'Garadar jest w rozsypce, $gnieznajomy:nieznajoma;. Odkąd Wszechmatka zachorowała, Garosz popadł w głębokie przygnębienie. Z pewnością nie jest synem swojego ojca.$B$B<Kurkush wzdycha.>', '', 0),
(14995, 'koKR', 'Zginęli. Wszyscy...$B$BGdy Mętna Krew przedzierała się przez nasze szeregi, ogarnęło mnie coś, czego nie potrafię zrozumieć. Powiedz mi, czy $gczułeś:czułaś; kiedyś gniew tak wielki, że płonie całe twoje jestestwo? Żar, od którego więdnie wszystko, co żywe? Żar, który spala krew w żyłach? To właśnie czułem.$B$B<Oczy Zaurzykła na moment rozbłyskują czerwienią.>$B$BZostałem ostatni przy życiu. Otoczyło mnie trzydziestu... Mętna Krew... Poza tą wizją nic nie pamiętam. Straciłem przytomność i ocknąłem się jakiś czas później.', '', 0),
(14996, 'koKR', 'Nadchodzą mroczne czasy, $gnieznajomy:nieznajoma;...', '', 0),
(14997, 'koKR', 'Duchy są bardzo wzburzone. Musimy znaleźć przyczynę tego niepokoju.', '', 0),
(15000, 'koKR', 'Nadchodzą następni! Uważaj!', '', 0),
(15001, 'koKR', 'Lepiej się teraz rozdzielmy, na wypadek gdyby wysłali za nami kolejnych. Miejmy nadzieję, że któryś z nas dotrze do Garosza. Żegnaj, $gnieznajomy:nieznajoma;.', '', 0),
(15002, 'koKR', 'Nie dajcie im uciec! Najpierw zabijcie silnego!', '', 0),
(15003, 'koKR', 'A ty dokąd? Zabić wszystkich!', '', 0),
(15006, 'koKR', 'Dosiądź błyskawicy, plugawcze!', '', 0),
(15009, 'koKR', 'MROŹNY WSTRZĄS!', '', 0),
(15023, 'koKR', 'Hemet to najlepszy myśliwy, jakiego znam. Wiele księżyców temu spotkaliśmy się przypadkiem na wzgórzach Zimozdroju w Azeroth. Obaj tropiliśmy tę samą zwierzynę: wielkiego kota zwanego Rak\'shiri.$B$BZamiast walczyć ze sobą o zdobycz, założyliśmy się: kto zdobędzie skórę mroźnego szablozębego, ten może zażądać czegoś od drugiego. Ku mojej wiecznej hańbie, tak właśnie dorobiłem się przezwiska Fitz.$B$BCzy ja wyglądam na Fitza?', '', 0),
(15034, 'koKR', '$GWielki łowca:Wielka łowczyni;, $N, powraca. Opowiedz mi, jak $gtropiłeś:tropiłaś; swoją ostatnią zdobycz.', '', 0),
(15044, 'koKR', 'To zasadzka! Broń się!', '', 0),
(15045, 'koKR', 'Tak, tak, czuję się lepiej, ale trochę mi się tu na dole podoba.', '', 0),
(15047, 'koKR', 'Jesteśmy otoczeni!', '', 0),
(15048, 'koKR', 'Przed nami droga do Telaar. Rozdzielimy się na rozwidleniu, bo na pewno wyślą za nami więcej Mętnej Krwi. Miejmy nadzieję, że któryś z nas dotrze żywy do Telaar.', '', 0),
(15087, 'koKR', 'Konsorcjum planowało to przedsięwzięcie od miesięcy! Mieliśmy rozkopać Oshu\'gun, największy znany diament we wszechświecie.$B$BNa kilka minut przed rozpoczęciem książę Nexusa Haramad przysyła wiadomość, że mamy się wstrzymać, dopóki w Burzy Otchłani nie zostanie rozwiązana pewna sprawa polityczna. Tymczasem przerobiłem nasze przedsięwzięcie na punkt przerzutu przemycanych klejnotów, ale to powoli zżera nasze zyski.', '', 0),
(15088, 'koKR', 'Oho, te rogacze nie wyglądają na zadowolone!', '', 0),
(15089, 'koKR', 'Uważaj, Fitz, idą prosto na nas!', '', 0),
(15090, 'koKR', 'Co się dzieje?!', '', 0),
(15091, 'koKR', '%s uśmiecha się i chowa strzelbę.', '', 0),
(15092, 'koKR', 'Gezhe jest tu, żeby wykonać robotę. Ja jestem tu, żeby nikt mu w tym nie przeszkadzał.', '', 0),
(15093, 'koKR', 'Ee... chłopaki?', '', 0),
(15094, 'koKR', 'Hemet? Fitz?', '', 0),
(15095, 'koKR', 'O, dobrze, już zaczynałem się martwić.', '', 0),
(15099, 'koKR', '', 'Nie rozbilibyśmy się, gdyby Hemet nauczył się nie strzelać przez lotki, kiedy próbuje ustrzelić zwierzynę na ziemi!$B$BAle bez obaw, szybko ją naprawię.', 0),
(15102, 'koKR', '', 'Cześć, Haroldzie. Mam twoje skóry!', 0),
(15104, 'koKR', '', 'Ach! Niech ktoś mi pomoże!', 0),
(15112, 'koKR', 'Ee... jasne, Gankly. Tylko... <kaszel>... zaczekaj tam. <Kaszel> Chłopaki?', '', 0),
(15113, 'koKR', '', 'Tak się cieszę, że ten podły Gankly Zgniłopięść dostał za swoje! Mam mnóstwo skór, jeśli chcesz trochę zanieść Haroldowi.', 0),
(15140, 'koKR', '', 'Hej! Czy nie dałam ci już wcześniej pakunku skór?$B$BTak czy inaczej, cieszę się, że ktoś mnie uratował z bezlitosnych szponów tego podłego Gankly\'ego Zgniłopięścia!', 0),
(15149, 'koKR', '', 'Wszechmatka wychowała nas wszystkich. Życie każdego Mag\'hara, którego tu widzisz, Wszechmatka w jakiś szczególny sposób naznaczyła. Będzie nam jej bardzo brakowało, gdy odejdzie.', 0),
(15152, 'koKR', '', 'Wszechmatka mówi, że dostałem imię po wielkim orkowym bohaterze.', 0),
(15157, 'koKR', '%s wierci się i jęczy z bólu, który sprawia mu zadrapanie od ciernia.', '', 0),
(15158, 'koKR', '%s jęczy z bólu.', '', 0),
(15159, 'koKR', '%s spogląda na przyjaciół, a potem boleśnie stęka.', '', 0),
(15160, 'koKR', '%s budzi się od własnego chrapania.', '', 0),
(15161, 'koKR', '%s krzywi się, gdy dotyka obolałego miejsca wokół zadrapania.', '', 0),
(15162, 'koKR', '%s zaczyna pogwizdywać melodię, ale nagle przerywa i jęczy.', '', 0),
(15197, 'koKR', 'Wyglądasz na kogoś rozsądnego. Może moglibyśmy sobie nawzajem pomóc.', '', 0),
(15278, 'koKR', 'W Nagrand jedzenie polować ogr!', '', 0),
(15279, 'koKR', 'Ty smaczny, może z odrobina sól i pieprz.', '', 0),
(15281, 'koKR', 'Czemu ty niedobry dla Bryła? Bryła głodny, i tyle.', '', 0),
(15282, 'koKR', 'Dobra, dobra! Bryła się poddawać!', '', 0),
(15283, 'koKR', 'Potrzebuję odpowiedzi, ogrze!', 'Potrzebuję odpowiedzi, ogrze!', 0),
(15284, 'koKR', 'Dobra! Bryła powiedzieć, co ty chcieć!', '', 0),
(15285, 'koKR', 'Czemu Głazopięści zapuszczają się tak daleko? Wiesz, że to terytorium Kurenai.', 'Czemu Głazopięści zapuszczają się tak daleko? Wiesz, że to terytorium Kurenai.', 0),
(15286, 'koKR', 'Głazopięści głodni! Trzeba jedzenie! Plemię ogrów Wojenne Maczugi wykopać Głazopięści z kopca na północy. Teraz dużo więcej Głazopięści do nakarmić.', '', 0),
(15287, 'koKR', 'I myślicie, że możecie jeść, co chcecie? Najwyraźniej chcecie zjeść Złamanych z Telaar.', 'I myślicie, że możecie jeść, co chcecie? Najwyraźniej chcecie zjeść Złamanych z Telaar.', 0),
(15288, 'koKR', 'To nie prawda. Ja tylko skubnąć. Ja nie zjeść wszystkich. No dobra, może zjeść te małe.$B$BOne takie pyszne!', '', 0),
(15289, 'koKR', 'To oznacza wojnę, Bryło! Wojnę, mówię!', 'To oznacza wojnę, Bryło! Wojnę, mówię!', 0),
(15290, 'koKR', '<Bryła wzrusza ramionami.>$B$BTy przynieść wojna do Głazopięści. My wrzucić ją do gulasz.', '', 0),
(15291, 'koKR', 'Wyciągnij mnie stąd!', '', 0),
(15297, 'koKR', 'Dzięki! Na pewno tata sowicie cię wynagrodzi! Pa!', '', 0),
(15308, 'koKR', 'To ostatni raz, kiedy dałem się złapać! Obiecuję! Pa!', '', 0),
(15314, 'koKR', 'Kto śmie tak zuchwale stawać przed Lantresorem z Ostrza? Nie poznajesz śmierci, gdy ją widzisz, $gchłopcze:dziewczyno;?', '', 0),
(15315, 'koKR', '$GZabiłem:Zabiłam; wiele twoich ogrów, Lantresorze. Nie czuję strachu.', '$GZabiłem:Zabiłam; wiele twoich ogrów, Lantresorze. Nie czuję strachu.', 0),
(15316, 'koKR', 'W takim razie jesteś głupcem. Nie wiesz, kim jestem?', '', 0),
(15317, 'koKR', 'A $gpowinienem:powinnam; wiedzieć? Dla mnie wyglądasz na orka.', 'A $gpowinienem:powinnam; wiedzieć? Dla mnie wyglądasz na orka.', 0),
(15318, 'koKR', 'Na orka...$B$B<Lantresor prycha.>$B$BJestem mistrzem ostrza, w połowie orkiem.', '', 0),
(15319, 'koKR', 'A w drugiej połowie?', 'A w drugiej połowie?', 0),
(15320, 'koKR', 'Draenei... I przez to nie jestem ani jednym, ani drugim. Ani orkiem, ani draenei. Tacy jak ja to rzadkość. Większość zabito dziesiątki lat temu... Żyję dzięki sile woli.', '', 0),
(15321, 'koKR', '$GSłyszałem:Słyszałam; o takich jak ty, ale nie sądziłem, że dożyję dnia, w którym spotkam mieszańca.', '$GSłyszałem:Słyszałam; o takich jak ty, ale nie sądziłem, że dożyję dnia, w którym spotkam mieszańca.', 0),
(15322, 'koKR', 'Ugryź się w język. Widziałem w życiu rzeczy, o których ty $gsłyszałeś:słyszałaś; tylko w legendach. Zabijałem mężczyzn, kobiety i dzieci bez wyrzutów sumienia. Służyłem pod sztandarem dwóch wodzów Hordy... A teraz rządzę Głazopięściami.', '', 0),
(15323, 'koKR', 'Przepraszam. Nie $gchciałem:chciałam; cię urazić. Jestem tu w imieniu mojego ludu.', 'Przepraszam. Nie $gchciałem:chciałam; cię urazić. Jestem tu w imieniu mojego ludu.', 0),
(15324, 'koKR', 'A czego twój lud chce od Lantresora?', '', 0),
(15325, 'koKR', 'Mój lud prosi, byś wycofał swoje ogry Głazopięści i zaprzestał wszelkich ataków na nasze ziemie. W zamian my również wycofamy nasze siły.', 'Mój lud prosi, byś wycofał swoje ogry Głazopięści i zaprzestał wszelkich ataków na nasze ziemie. W zamian my również wycofamy nasze siły.', 0),
(15326, 'koKR', '<Lantresor śmieje się serdecznie.>$B$BWiesz, gdzie jesteś, głupcze? To ziemia ogrów. Zanim był ork, zanim byli draenei, był ogr. A ty chcesz rozpętać wojnę, którą nieuchronnie przegrasz? Głazopięści cię zmiażdżą. A jeśli nie zniszczą cię Głazopięści, zrobią to Wojenne Maczugi...$B$BAle myślę, że twoi przywódcy już to wiedzą...', '', 0),
(15327, 'koKR', 'W takim razie będziemy z tobą walczyć do końca, Lantresorze. Nie będziemy bezczynnie patrzeć, jak łupisz nasze miasta i zabijasz nasz lud.', 'W takim razie będziemy z tobą walczyć do końca, Lantresorze. Nie będziemy bezczynnie patrzeć, jak łupisz nasze miasta i zabijasz nasz lud.', 0),
(15328, 'koKR', '<Lantresor patrzy na ciebie gniewnie, jakby patrzył na wskroś.>$B$BMoże jest inny sposób... Zgodzę się na żądania twojego przywódcy, ale tylko jeśli zrobisz dokładnie to, o co proszę.$B$BDzięki twojej pomocy możemy sobie nawzajem bardzo pomóc.', '', 0),
(15329, 'koKR', 'Co muszę zrobić?', 'Co muszę zrobić?', 0),
(15330, 'koKR', 'Zainscenizujesz ciąg zdarzeń, który przekona orków z Kil\'sorrow w Fortecy Kil\'sorrow, że ogry z Wojennych Maczug zaatakowały ich bazę, a potem kolejny, który przekona ogry z Wojennych Maczug, że to orkowie z Kil\'sorrow atakują ich bazę.$B$BZrób to, a rozwiążesz oba nasze problemy.$B$BGłazopięści odzyskają swoje terytorium, a twój lud uwolni się od ataków Głazopięści, Wojennych Maczug i Rady Cieni.', '', 0),
(15369, 'koKR', 'Przed zamieszczeniem jakiegokolwiek zlecenia należy porozmawiać ze strażnikiem Bullrokiem.$B$BWinni zamieszczania niezatwierdzonych ogłoszeń zostaną ukarani.$B$BZakaz naklejania ogłoszeń.', '', 0),
(15370, 'koKR', 'Przed zamieszczeniem jakiegokolwiek zlecenia należy porozmawiać ze strażnikiem Moi\'bff Jillem.$B$BWinni zamieszczania niezatwierdzonych ogłoszeń zostaną ukarani.$B$BZakaz naklejania ogłoszeń.', '', 0),
(15371, 'koKR', 'Niech szlag trafi te ogry. Niech je Otchłań pochłonie. Czy nikt nas nie uratuje przed tymi dzikusami?! To już piąte porwanie w ciągu pięciu dni.', '', 0),
(15372, 'koKR', 'To najlepsza nagroda, jaką możemy zaoferować. Miejmy nadzieję, że ktoś przyjmie zlecenie.', '', 0),
(15373, 'koKR', 'Nowe ogłoszenie! Poszukiwacze przygód i bohaterowie, zbierzcie się przy tablicy ogłoszeń!', '', 0),
(15374, 'koKR', 'To powinno zapewnić Telaar pomoc, której potrzebuje!', '', 0),
(15375, 'koKR', 'Jeśli szukasz pracy, sprawdź tablicę ogłoszeń.', '', 0),
(15380, 'koKR', 'Nie mają szacunku dla zmarłych. Trzeba dać ogrom nauczkę.', '', 0),
(15381, 'koKR', 'Musimy szukać ocalałych. Jeśli ktoś jeszcze żyje, musimy przynajmniej spróbować go sprowadzić z powrotem...', '', 0),
(15384, 'koKR', 'Pewnego dnia powstanie bohater, który przywróci orkom dawną chwałę.', 'Pewnego dnia powstanie bohater, który przywróci orkom dawną chwałę.', 0),
(15387, 'koKR', 'Dziękuję! Mag\'harowie nie zapomną twojej przysługi.', 'Dziękuję! Mag\'harowie nie zapomną twojej przysługi.', 0),
(15388, 'koKR', 'Śmierć ogrom!', 'Śmierć ogrom!', 0),
(15389, 'koKR', 'Stokrotne dzięki, $gbohaterze:bohaterko;!', 'Stokrotne dzięki, $gbohaterze:bohaterko;!', 0),
(15390, 'koKR', 'Niech duchy czuwają nad tobą!', 'Niech duchy czuwają nad tobą!', 0),
(15419, 'koKR', 'TO ROBI, CO MU KAZAĆ!', '', 0),
(15420, 'koKR', 'WŁAŹ DO GULASZ!', '', 0),
(15421, 'koKR', 'TY DOBRY W BRZUCH!', '', 0),
(15422, 'koKR', '', 'Musimy odzyskać te skrzynie z zapasami!', 0),
(15424, 'koKR', 'Dzięki, $n! Ile razy już $guratowałeś:uratowałaś; mi życie? Trzy? W moich oczach to czyni nas braćmi krwi!', '', 0),
(15426, 'koKR', 'Twój tatuś zapłacić Wojenne Maczugi, to może my ciebie nie zjeść.', '', 0),
(15427, 'koKR', 'Cha, cha! Żartować. My ciebie i tak na pewno zjeść!', '', 0),
(15430, 'koKR', 'BAM! Patrz, jak ta chrząstka skwierczeć!', '', 0),
(15431, 'koKR', 'A to przepis na najlepszejsza zupa ze Złamanych!', '', 0),
(15432, 'koKR', 'Najpierw trzeba przyprawy.', '', 0),
(15433, 'koKR', 'Sól iść do gar...', '', 0),
(15434, 'koKR', 'Potem ty wrzucić pieprz do gar...', '', 0),
(15435, 'koKR', 'A teraz my podkręcić smak tajnym skła... skal... sklad... tajnym sosem!', '', 0),
(15436, 'koKR', 'I na koniec my wrzucić Corki!', '', 0),
(15437, 'koKR', 'Na pewno masz siłę, ale czy masz to, czego trzeba, by zostać czempionem Wojennych Maczug?', '', 0),
(15439, 'koKR', 'Walka zaraz się zacznie! $n kontra dziki rozłupokopyt, Złamany Palec!', '', 0),
(15441, 'koKR', 'Wejdź do Kręgu Krwi, $n. Walka zaraz się zacznie!', '', 0),
(15442, 'koKR', '$n pokonuje Złamanego Palca!', '', 0),
(15443, 'koKR', '$n przegrywa!', '', 0),
(15461, 'koKR', 'Walka zaraz się zacznie! Bezlitośni bliźniacy z Mętnej Krwi kontra $n!', '', 0),
(15462, 'koKR', 'Niewiarygodne! $n pokonuje bliźniaków z Mętnej Krwi!', '', 0),
(15467, 'koKR', 'Prosto z Gór Klingi – Rokdar Rozdarty Władca! $n stoczy walkę życia.', '', 0),
(15469, 'koKR', '$n znów zwycięża!', '', 0),
(15470, 'koKR', 'To był kupa! Mogor stoczyć dużo lepszy walka!', '', 0),
(15473, 'koKR', 'Skądś z nieznanych stron: Skra\'gath! Czy $n zdoła przetrwać natarcie energii pustki?', '', 0),
(15474, 'koKR', 'Mogor nie pod wrażeniem! Skra\'gath być zrobiony z powietrze i cień! Miękki jak mięciutkie orki!', '', 0),
(15475, 'koKR', 'Oto chwila, na którą wszyscy czekaliśmy! Czempion Wojennych Maczug po raz pierwszy od tygodni pokaże się w Kręgu Krwi! Czy $n przegra równie łatwo jak inni przeciwnicy czempiona? Zobaczymy...', '', 0),
(15477, 'koKR', 'CO!? NIEMOŻLIWNE!! Teraz ty walczyć z Mogor! Mogor zniszczyć!', '', 0),
(15478, 'koKR', 'Teraz ty stanąć przed prawdziwy czempion! Mogor dać ci szansa uciec, mały. Uciekaj teraz, zanim Mogor zdzie... zdziesię... Uciekaj, zanim Mogor ZABIĆ!', '', 0),
(15479, 'koKR', 'Koniec szans! Teraz ty zapłacić ogr!', '', 0),
(15480, 'koKR', 'Mogor rzucił ci wyzwanie. Musisz je przyjąć! Wejdź na ring, gdy będziesz $ggotów:gotowa; do walki.', '', 0),
(15481, 'koKR', 'Po raz pierwszy w historii Kręgu Krwi Mogor postanowił skorzystać z prawa do walki! Na tej zbroczonej wojną ziemi $n zmierzy się z Mogorem, Bohaterem Wojennych Maczug!', '', 0),
(15482, 'koKR', '$n pokonuje Bohatera Wojennych Maczug, Mogora! Niech żyje $n!', '', 0),
(15483, 'koKR', 'Koniec miły ogr! Ty zranić Mogor!!', '', 0),
(15484, 'koKR', '$n pada jak worek orkowych czaszek!', '', 0),
(15485, 'koKR', '$n to teraz tylko czerwona plama na ziemi!', '', 0),
(15486, 'koKR', 'Witaj, $gczempionie:czempionko;! Myślisz czasem, żeby zająć się gladiatorstwem na pełen etat? Ty i ja moglibyśmy zbić górę złota.', '', 0),
(15534, 'koKR', 'Chyba dorobię sobie na boku, póki inni zastanawiają się, czy wolno już wejść do Oshu\'gun.$B$BCzas to zysk!', '', 0),
(15701, 'koKR', 'Pamiętam wszystko...', 'Pamiętam wszystko...', 0),
(15704, 'koKR', 'Duchy wzywają... Jestem pochłonięty.', 'Duchy wzywają... Jestem pochłonięty.', 0),
(15705, 'koKR', 'Ból jest nie do zniesienia.', 'Ból jest nie do zniesienia.', 0),
(15706, 'koKR', 'Przestań płakać! DOŚĆ!', 'Przestań płakać! DOŚĆ!', 0),
(15707, 'koKR', 'Umiera. Umiera. Umiera.', 'Umiera. Umiera. Umiera.', 0),
(15709, 'koKR', 'Co się z nami stanie, gdy upadnie?', 'Co się z nami stanie, gdy upadnie?', 0),
(15710, 'koKR', 'Nie mogę zapanować... Wciąga mnie... Pustka rośnie...', 'Nie mogę zapanować... Wciąga mnie... Pustka rośnie...', 0),
(15949, 'koKR', '', 'Jeśli nie $gprzyszedłeś:przyszłaś; wspierać sprawy, wynoś się.', 0),
(15950, 'koKR', 'Z twoją pomocą może uda nam się to wygrać!', '', 0),
(15954, 'koKR', 'Możesz u mnie kupować za bitewne i badawcze żetony z Halaa.', '', 0),
(16022, 'koKR', '', 'Witaj w Garadarze, $gnieznajomy:nieznajoma;. Szukasz miejsca na odpoczynek?', 0),
(16062, 'koKR', '', 'Twoja krew spłynie po murach Kil\'sorrow!', 0),
(16063, 'koKR', 'Krąg Prób był niegdyś miejscem wielkiej chwały i honoru. Ale potem przybył Kartel Parochlebców ze swoimi wozami złota i piórami ostrzejszymi niż jakikolwiek orkowy topór...', '', 0),
(16072, 'koKR', 'Witajcie, witajcie na niedawno przejętym i bezdusznie przemianowanym Stadionie Parochlebców!', '', 0),
(16124, 'koKR', 'Trzeba ostrego ostrza i wzmocnionej zbroi, by przywrócić Nagrandowi spokój. Czy mam naprawić twój ekwipunek, byś $gmógł:mogła; wymierzać sprawiedliwość?', '', 0),
(16126, 'koKR', 'Szukasz odczynników albo składników do trucizn? Jeśli tak, dobrze $gtrafiłeś:trafiłaś;!', '', 0),
(16128, 'koKR', 'Sprzedaję towary potrzebne rzemieślnikom. Same podstawy, nic wymyślnego.', '', 0),
(16132, 'koKR', '', '$GZgubiłeś:Zgubiłaś; się? Większość kupców w mieście ma stragany blisko centrum.', 0),
(16133, 'koKR', '', 'Mam różne rupiecie, ale głównie rupiecie.', 0),
(16136, 'koKR', 'To doprowadza mnie do szału. Nie mogę dosięgnąć tych przeklętych jaj!', '', 0),
(16137, 'koKR', 'Wyglądają tak smakowicie...', '', 0),
(16138, 'koKR', 'Gdybym tylko mógł uruchomić tę przeklętą maszynę!', '', 0),
(16139, 'koKR', 'Och, słodkie, pyszne, nakrapiane jajeczka – będziecie moje...', '', 0),
(16143, 'koKR', 'Dobrze cię znowu widzieć, $n! Jeszcze tylko kilka poprawek i tor skoku będzie idealny!', '', 0),
(16218, 'koKR', 'Dzikie równiny Nagrandu oferują jedne z najlepszych łowów, jakich kiedykolwiek doświadczyłem.', '', 0),
(16223, 'koKR', 'Nigdy nie patrz tym Złamanym prosto w oczy. Myślę, że jak zechcą, potrafią wyssać z ciebie duszę!', '', 0),
(16225, 'koKR', 'No proszę, co za $gtwardziel:twardzielka;... Może uważasz, że starczy ci siły, by wejść do Kręgu Krwi i zmierzyć się z czempionem Wojennych Maczug?$B$B<Wojownik areny się śmieje.>$B$BRaczej wątpię, ale jeśli kiedyś zechcesz sprawdzić swoją siłę, Krąg Krwi jest daleko na północy, pod górami oddzielającymi Nagrand od Moczarów Zangarskich. Gurgthock prowadzi całe widowisko w starych Ruinach Śmiejącej się Czaszki i to on wydaje nagrody. A skoro o nagrodach mowa, słyszałem, że w tym sezonie są niesamowite!', '', 0),
(16229, 'koKR', 'Wojownik areny zwycięży! Tylko na niego spójrzcie!', 'Wojownik areny zwycięży! Tylko na niego spójrzcie!', 0),
(16230, 'koKR', 'Jest taki zdyscyplinowany!', 'Jest taki zdyscyplinowany!', 0),
(16231, 'koKR', 'Jak on to robi?', 'Jak on to robi?', 0),
(16233, 'koKR', 'Rany! Patrzcie, jakie ma mięśnie!', 'Rany! Patrzcie, jakie ma mięśnie!', 0),
(16234, 'koKR', 'Chcę być taki jak wojownik areny!', 'Chcę być taki jak wojownik areny!', 0),
(16235, 'koKR', 'Wygra? Da radę wygrać?', 'Wygra? Da radę wygrać?', 0),
(16236, 'koKR', 'Wojownik areny zwycięży! Tylko na niego spójrzcie!', 'Wojownik areny zwycięży! Tylko na niego spójrzcie!', 0),
(16237, 'koKR', 'Jest taki zdyscyplinowany!', 'Jest taki zdyscyplinowany!', 0),
(16238, 'koKR', 'Jak on to robi?', 'Jak on to robi?', 0),
(16247, 'koKR', 'Śledczy próbuje ustalić, co te krwawe elfy robią w Nagrandzie. Z tego, co słyszę, chodzi im o resztki proszku kryształowego z Oshu\'gun, diamentowej góry na zachodzie.$B$BBez wątpienia do jakiegoś podstępnego planu albo wywaru...$B$BJeśli chcesz wesprzeć naszą sprawę i powstrzymać te krwawe elfy, walki toczą się właśnie teraz na północnym zachodzie, w Halaa. Krwawe elfy biją się z żołnierzami Ręki Argusa! Dołącz do walki i pokaż im, co słuszne!', 'Śledczy próbuje ustalić, co te krwawe elfy robią w Nagrandzie. Z tego, co słyszę, chodzi im o resztki proszku kryształowego z Oshu\'gun, diamentowej góry na zachodzie.$B$BBez wątpienia do jakiegoś podstępnego planu albo wywaru...$B$BJeśli chcesz wesprzeć naszą sprawę i powstrzymać te krwawe elfy, walki toczą się właśnie teraz na północnym zachodzie, w Halaa. Krwawe elfy biją się z żołnierzami Ręki Argusa! Dołącz do walki i pokaż im, co słuszne!', 0),
(16248, 'koKR', 'Draenei wrócili! Ta grupa napadła na dwóch moich najlepszych wilczych jeźdźców, gdy patrolowali zachodnie drogi. Rzecz jasna, wygraliśmy tę potyczkę.$B$BNie jestem pewien, co się dzieje, ale według moich zwiadowców w Halaa roi się od krwawych elfów i draenei. Nie przepadam za krwawymi elfami, ale jeśli czegoś nienawidzę, to draenei. Jeśli zobaczysz w Halaa draenei albo któregoś z ich sojuszników, daj im ode mnie kopa w tyłek.$B$BHalaa jest na zachodzie... Gdybyś $gchciał:chciała; iść od razu.', 'Draenei wrócili! Ta grupa napadła na dwóch moich najlepszych wilczych jeźdźców, gdy patrolowali zachodnie drogi. Rzecz jasna, wygraliśmy tę potyczkę.$B$BNie jestem pewien, co się dzieje, ale według moich zwiadowców w Halaa roi się od krwawych elfów i draenei. Nie przepadam za krwawymi elfami, ale jeśli czegoś nienawidzę, to draenei. Jeśli zobaczysz w Halaa draenei albo któregoś z ich sojuszników, daj im ode mnie kopa w tyłek.$B$BHalaa jest na zachodzie... Gdybyś $gchciał:chciała; iść od razu.', 0),
(16835, 'koKR', 'Co... Czym ja się stałem? Aaarrgh...', 'Co... Czym ja się stałem? Aaarrgh...', 0),
(16837, 'koKR', 'Czeka zimny uścisk...', 'Czeka zimny uścisk...', 0),
(16838, 'koKR', 'Idzie po ciebie...', 'Idzie po ciebie...', 0),
(16839, 'koKR', 'To niemożliwe...', 'To niemożliwe...', 0),
(16840, 'koKR', 'Co to za podstęp? Ja... ARGH...', 'Co to za podstęp? Ja... ARGH...', 0),
(16841, 'koKR', 'Niech przodkowie czuwają nad tobą, dobra duszo...', 'Niech przodkowie czuwają nad tobą, dobra duszo...', 0),
(16957, 'koKR', 'Rakietowódz Kadłubek, dowódca B.U.M. – Bractwa Umysłów od Mechaniki orbitalnej – do usług.$B$BCzy wszystkie systemy gotowe?! Wygląda na to, że przy Rakiecie Otchłani X-52 jest jeszcze mnóstwo pracy!$B$BNo dalej, ludzie... tu jest T-minus NIGDY!', '', 0),
(17005, 'koKR', 'Kim on jest? Wygląda tak znajomo.', 'Kim on jest? Wygląda tak znajomo.', 0),
(17006, 'koKR', 'Czy plotki są prawdziwe? Czy naprawdę płynie w nim krew Wszechmatki?', 'Czy plotki są prawdziwe? Czy naprawdę płynie w nim krew Wszechmatki?', 0),
(17007, 'koKR', 'Czy to możliwe? Syn Durotana?', 'Czy to możliwe? Syn Durotana?', 0),
(17008, 'koKR', 'Czy przybył, by nas prowadzić?', 'Czy przybył, by nas prowadzić?', 0),
(17009, 'koKR', 'Nigdy nie czułem, by od orka biła taka siła. Czy on jest... śmiertelnikiem...', 'Nigdy nie czułem, by od orka biła taka siła. Czy on jest... śmiertelnikiem...', 0),
(17010, 'koKR', 'On niesie Zgładziciela!', 'On niesie Zgładziciela!', 0),
(17011, 'koKR', 'Po raz pierwszy czuję się bezpiecznie. Nie znam cię, $gnieznajomy:nieznajoma;, ale wiem, że oddałbym za ciebie życie, gdybyś tylko $gpoprosił:poprosiła;.', 'Po raz pierwszy czuję się bezpiecznie. Nie znam cię, $gnieznajomy:nieznajoma;, ale wiem, że oddałbym za ciebie życie, gdybyś tylko $gpoprosił:poprosiła;.', 0),
(17012, 'koKR', 'Syn Durotana... Wnuk Garada i Geyah... Pochylcie głowy, bo jest wśród nas wódz...', 'Syn Durotana... Wnuk Garada i Geyah... Pochylcie głowy, bo jest wśród nas wódz...', 0),
(17098, 'koKR', 'Twoja obecność to dla nas zaszczyt, synu Durotana. Wszechmatka czeka na ciebie w lecznicy.', '', 0),
(17099, 'koKR', '%s wskazuje lecznicę.', '', 0),
(17135, 'koKR', 'Jak sobie życzysz, Thrallu, synu Durotana.', '', 0),
(17164, 'koKR', 'Przez całe życie uważałem, że mój ród jest przeklęty. Żyłem w cieniu największej porażki mojego ojca.', '', 0),
(17166, 'koKR', 'Nienawidziłem go za to, co zrobił. Nienawidziłem go za brzemię, które mi zostawił. Ale teraz...', '', 0),
(17167, 'koKR', 'Pokazałeś mi prawdy, których nigdy bym nie poznał. Ty i twoi sojusznicy obdarowaliście mnie czymś, co nie ma ceny: odkupieniem. Thrallu, odkupicielu Mag\'harów, oddajesz mi cześć jak nikt dotąd...', '', 0),
(17168, 'koKR', 'Tego dnia wielki ciężar spadł mi z piersi. Serce rozpiera mi duma. I po raz pierwszy mogę z dumą obwieścić, kim jestem. W końcu mogę uwolnić furię z mojego serca.', '', 0),
(17169, 'koKR', 'Jestem Garosz Piekłorycz, syn Groma, wódz Mag\'harów! Niech bojowy okrzyk Piekłorycza doda wam odwagi i siły! Niech wzmocni was mój zew!', '', 0),
(17171, 'koKR', 'Dziękuję ci, synu Durotana.', '', 0),
(17183, 'koKR', 'Czego chcesz?', '', 0),
(17184, 'koKR', 'Witaj, Gezhe! W Sektorze Hara\'samid złożono kolejne siedemnaście zamówień. Rynki ciężkiego veldarytu niemal się załamały, tak jak przewidziałeś.', '', 0),
(17185, 'koKR', 'Za pozwoleniem, panie.', '', 0),
(17186, 'koKR', 'Eksport z Heraazi rośnie, panie. Przekupiliśmy już odpowiednich poborców podatkowych i kontrabanda zacznie napływać w ciągu kilku dni.', '', 0),
(17190, 'koKR', 'Tak jak się spodziewałem. Dobrze, odejść.', '', 0),
(17191, 'koKR', 'Nic zaskakującego. Wróć z jakimiś prawdziwymi wieściami, dobrze?', '', 0),
(17474, 'koKR', 'O nie! Ktoś atakuje Rakietę Otchłani X-52! Straże! Straże!', '', 0),
(19052, 'koKR', '<Nuainn Burzoskrzydły kręci głową.>$B$BZ Legionem z jednej strony i sługami Illidana z drugiej, obrona warowni będzie nas kosztować wszystko, co mamy – ale obronimy ją! Każdy prawdziwy Dziki Młot prędzej zginie, niż odda nasz dom.', '', 0),
(19493, 'koKR', '', 'Gdy byłam młoda, ciężko się szkoliłam, by zostać anachoretką w kapłaństwie. O kobietach egzarchach właściwie nikt nie słyszał.$B$BDziś płeć niewiele znaczy – całą różnicę robią odwaga i przekonania.', 0),
(19598, 'koKR', '', 'Poczuj mój gniew, ścierwo! Nie ujdzie ci to na sucho!', 0),
(19599, 'koKR', 'Kto zakłóca mój sen? Ta włócznia... Wciąż noszę bliznę!', '', 0),
(19850, 'koKR', 'Ach, $gkolejny chętny:kolejna chętna; do bycia gladiatorem, co? Dobrze!\nSprzedaję karty drużyn areny, których potrzebujesz, by brać udział w rankingowych meczach Ligi Walk Parochlebców.', 'Ach, $gkolejny chętny:kolejna chętna; do bycia gladiatorem, co? Dobrze!\nSprzedaję karty drużyn areny, których potrzebujesz, by brać udział w rankingowych meczach Ligi Walk Parochlebców.', 0),
(19852, 'koKR', 'Jak mogę założyć drużynę areny?', 'Jak mogę założyć drużynę areny?', 0),
(19908, 'koKR', 'W pustce nikt nie usłyszy twojego krzyku!', '', 0),
(20473, 'koKR', 'Gezhe jest dla mnie naprawdę miły, że pozwolił mi tu przyjść na praktykę i uczyć się tych wszystkich fajnych rzeczy, $gproszę pana:proszę pani;.$B$B<Jheel zwiesza głowę.>$B$BAle nie znoszę być z dala od siostry.', '', 0),
(20738, 'koKR', '', 'Podejdź bliżej, maleńki. Ani ja, ani $n nie zrobimy ci krzywdy.', 0),
(20740, 'koKR', '', 'Wyszkolę cię, byś pomógł w bardzo ważnym zadaniu, które ma $n. Potem, obiecuję, będziesz mógł wrócić do domu.', 0),
(20751, 'koKR', '', 'Usłyszysz wezwanie, gdy będziesz potrzebny. Leć na wschód, do Skettis, i czekaj tam, aż $n da ci sygnał.', 0),
(20923, 'koKR', '', 'Ciii! Mów ciszej. Maleństwa śpią.', 0),
(21292, 'koKR', 'Moje oczy wypełniają wizje zdarzeń, które dzieją się na całym świecie, i tych, które mogą dopiero nastąpić. Wiele z nich jest ponurych, ale nie musimy wierzyć, że nie da się ich zmienić.', '', 0),
(23952, 'koKR', 'Czasy się zmieniają, $n. Nadeszła wojna.$B$BCzy nasz lud stanie na wysokości zadania i wesprze sojuszników... czy będziemy stać z boku?', '', 0),
(23957, 'koKR', 'Niewielu nas zostało, $n. Powrót dawnego wroga to powód do wielkiego niepokoju.', '', 0),
(24172, 'koKR', 'Kiedyś nazywałem się Iolol, dopóki w mieście nie przeprowadzono tajnego głosowania, przez które musiałem zmienić imię. Albo je zmienię, albo skończę jak Corki. $GZrobiłbyś:Zrobiłabyś; to samo. Jak ci się podoba moje nowe imię? Ogromna poprawa, co?$B$BA tak przy okazji, jeśli szukasz pracy, sprawdź tablicę ogłoszeń.', '', 0),
(39797, 'koKR', 'Uważaj!', '', 0);
